REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(1, 'BULBASAUR', 'Bulbasaur', 'GRASS', 'POISON', 45, 49, 49, 65, 65, 45, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'OVERGROW', NULL, 'CHLOROPHYLL', 'Monster,Grass', 5120, 0.7, 6.9, 'Green', 'Quadruped', 'Grassland', 'Seed', 'Bulbasaur can be seen napping in bright sunlight. There is a seed on its back. By soaking up the sun''s rays, the seed grows progressively larger.', '1', 'IVYSAUR,Level,16', '0001_Bulbasaur'),
(2, 'IVYSAUR', 'Ivysaur', 'GRASS', 'POISON', 60, 62, 63, 80, 80, 60, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'OVERGROW', NULL, 'CHLOROPHYLL', 'Monster,Grass', 5120, 1.0, 13.0, 'Green', 'Quadruped', 'Grassland', 'Seed', 'To support its bulb, Ivysaur''s legs grow sturdy. If it spends more time lying in the sunlight, the bud will soon bloom into a large flower.', '1', 'VENUSAUR,Level,32', '0002_Ivysaur'),
(3, 'VENUSAUR', 'Venusaur', 'GRASS', 'POISON', 80, 82, 83, 100, 100, 80, 'FemaleOneEighth', 'Parabolic', 263, 45, 50, 'OVERGROW', NULL, 'CHLOROPHYLL', 'Monster,Grass', 5120, 2.0, 100.0, 'Green', 'Quadruped', 'Grassland', 'Seed', 'Venusaur''s flower is said to take on vivid colors if it gets plenty of nutrition and sunlight. The flower''s aroma soothes the emotions of people.', '1', NULL, '0003_Venusaur'),
(4, 'CHARMANDER', 'Charmander', 'FIRE', NULL, 39, 52, 43, 60, 50, 65, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'SOLARPOWER', 'Monster,Dragon', 5120, 0.6, 8.5, 'Red', 'BipedalTail', 'Mountain', 'Lizard', 'The flame that burns at the tip of its tail is an indication of its emotions. The flame wavers when Charmander is happy, and blazes when it is enraged.', '1', 'CHARMELEON,Level,16', '0004_Charmander'),
(5, 'CHARMELEON', 'Charmeleon', 'FIRE', NULL, 58, 64, 58, 80, 65, 80, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'BLAZE', NULL, 'SOLARPOWER', 'Monster,Dragon', 5120, 1.1, 19.0, 'Red', 'BipedalTail', 'Mountain', 'Flame', 'Without pity, its sharp claws destroy foes. If it encounters a strong enemy, it becomes agitated, and the flame on its tail flares with a bluish white color.', '1', 'CHARIZARD,Level,36', '0005_Charmeleon'),
(6, 'CHARIZARD', 'Charizard', 'FIRE', 'FLYING', 78, 84, 78, 109, 85, 100, 'FemaleOneEighth', 'Parabolic', 267, 45, 50, 'BLAZE', NULL, 'SOLARPOWER', 'Monster,Dragon', 5120, 1.7, 90.5, 'Red', 'BipedalTail', 'Mountain', 'Flame', 'A Charizard flies about in search of strong opponents. It breathes intense flames that can melt any material. However, it will never torch a weaker foe.', '1', NULL, '0006_Charizard'),
(7, 'SQUIRTLE', 'Squirtle', 'WATER', NULL, 44, 48, 65, 50, 64, 43, 'FemaleOneEighth', 'Parabolic', 63, 45, 50, 'TORRENT', NULL, 'RAINDISH', 'Monster,Water1', 5120, 0.5, 9.0, 'Blue', 'BipedalTail', 'WatersEdge', 'Tiny Turtle', 'Its shell is not just for protection. Its rounded shape and the grooves on its surface minimize resistance in water, enabling Squirtle to swim at high speeds.', '1', 'WARTORTLE,Level,16', '0007_Squirtle'),
(8, 'WARTORTLE', 'Wartortle', 'WATER', NULL, 59, 63, 80, 65, 80, 58, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'TORRENT', NULL, 'RAINDISH', 'Monster,Water1', 5120, 1.0, 22.5, 'Blue', 'BipedalTail', 'WatersEdge', 'Turtle', 'Its large tail is covered with rich, thick fur that deepens in color with age. The scratches on its shell are evidence of this Pokémon''s toughness in battle.', '1', 'BLASTOISE,Level,36', '0008_Wartortle'),
(9, 'BLASTOISE', 'Blastoise', 'WATER', NULL, 79, 83, 100, 85, 105, 78, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'RAINDISH', 'Monster,Water1', 5120, 1.6, 85.5, 'Blue', 'BipedalTail', 'WatersEdge', 'Shellfish', 'The waterspouts that protrude from its shell are highly accurate. Their bullets of water can precisely nail tin cans from a distance of over 160 feet.', '1', NULL, '0009_Blastoise'),
(10, 'CATERPIE', 'Caterpie', 'BUG', NULL, 45, 30, 35, 20, 20, 45, 'Female50Percent', 'Medium', 39, 255, 50, 'SHIELDDUST', NULL, 'RUNAWAY', 'Bug', 3840, 0.3, 2.9, 'Green', 'Insectoid', 'Forest', 'Worm', 'Its voracious appetite compels it to devour leaves bigger than itself without hesitation. It releases a terribly strong odor from its antennae.', '1', 'METAPOD,Level,7', '0010_Caterpie'),
(11, 'METAPOD', 'Metapod', 'BUG', NULL, 50, 20, 55, 25, 25, 30, 'Female50Percent', 'Medium', 72, 120, 50, 'SHEDSKIN', NULL, NULL, 'Bug', 3840, 0.7, 9.9, 'Green', 'Serpentine', 'Forest', 'Cocoon', 'Its shell is as hard as an iron slab. A Metapod does not move very much because it is preparing its soft innards for evolution inside the shell.', '1', 'BUTTERFREE,Level,10', '0011_Metapod'),
(12, 'BUTTERFREE', 'Butterfree', 'BUG', 'FLYING', 60, 45, 50, 90, 80, 70, 'Female50Percent', 'Medium', 198, 45, 50, 'COMPOUNDEYES', NULL, 'TINTEDLENS', 'Bug', 3840, 1.1, 32.0, 'White', 'MultiWinged', 'Forest', 'Butterfly', 'It has a superior ability to search for delicious honey from flowers. It can seek, extract, and carry honey from flowers blooming over six miles away.', '1', NULL, '0012_Butterfree'),
(13, 'WEEDLE', 'Weedle', 'BUG', 'POISON', 40, 35, 30, 20, 20, 50, 'Female50Percent', 'Medium', 39, 255, 50, 'SHIELDDUST', NULL, 'RUNAWAY', 'Bug', 3840, 0.3, 3.2, 'Brown', 'Insectoid', 'Forest', 'Hairy Bug', 'A Weedle has an extremely acute sense of smell. It distinguishes its favorite kinds of leaves from those it dislikes by sniffing with its big red proboscis (nose).', '1', 'KAKUNA,Level,7', '0013_Weedle'),
(14, 'KAKUNA', 'Kakuna', 'BUG', 'POISON', 45, 25, 50, 25, 25, 35, 'Female50Percent', 'Medium', 72, 120, 50, 'SHEDSKIN', NULL, NULL, 'Bug', 3840, 0.6, 10.0, 'Yellow', 'Serpentine', 'Forest', 'Cocoon', 'It remains virtually immobile while it clings to a tree. However, on the inside, it busily prepares for evolution. This is evident from how hot its shell becomes.', '1', 'BEEDRILL,Level,10', '0014_Kakuna'),
(15, 'BEEDRILL', 'Beedrill', 'BUG', 'POISON', 65, 90, 40, 45, 80, 75, 'Female50Percent', 'Medium', 198, 45, 50, 'SWARM', NULL, 'SNIPER', 'Bug', 3840, 1.0, 29.5, 'Yellow', 'MultiWinged', 'Forest', 'Poison Bee', 'A Beedrill is extremely territorial. For safety reasons, no one should ever approach its nest. If angered, they will attack in a swarm.', '1', NULL, '0015_Beedrill'),
(16, 'PIDGEY', 'Pidgey', 'NORMAL', 'FLYING', 40, 45, 40, 35, 35, 56, 'Female50Percent', 'Parabolic', 50, 255, 50, 'KEENEYE', 'TANGLEDFEET', 'BIGPECKS', 'Flying', 3840, 0.3, 1.8, 'Brown', 'Winged', 'Forest', 'Tiny Bird', 'It has an extremely sharp sense of direction. It can unerringly return home to its nest, however far it may be removed from its familiar surroundings.', '1', 'PIDGEOTTO,Level,18', '0016_Pidgey'),
(17, 'PIDGEOTTO', 'Pidgeotto', 'NORMAL', 'FLYING', 63, 60, 55, 50, 50, 71, 'Female50Percent', 'Parabolic', 122, 120, 50, 'KEENEYE', 'TANGLEDFEET', 'BIGPECKS', 'Flying', 3840, 1.1, 30.0, 'Brown', 'Winged', 'Forest', 'Bird', 'This Pokémon flies around, patrolling its large territory. If its living space is violated, it shows no mercy in thoroughly punishing the foe with its sharp claws.', '1', 'PIDGEOT,Level,36', '0017_Pidgeotto'),
(18, 'PIDGEOT', 'Pidgeot', 'NORMAL', 'FLYING', 83, 80, 75, 70, 70, 101, 'Female50Percent', 'Parabolic', 240, 45, 50, 'KEENEYE', 'TANGLEDFEET', 'BIGPECKS', 'Flying', 3840, 1.5, 39.5, 'Brown', 'Winged', 'Forest', 'Bird', 'Pidgeot has gorgeous, glossy feathers. Many trainers are so captivated by the beautiful feathers on its head that they choose Pidgeot as their Pokémon.', '1', NULL, '0018_Pidgeot'),
(19, 'RATTATA', 'Rattata', 'NORMAL', NULL, 30, 56, 35, 25, 35, 72, 'Female50Percent', 'Medium', 51, 255, 50, 'RUNAWAY', 'GUTS', 'HUSTLE', 'Field', 3840, 0.3, 3.5, 'Purple', 'Quadruped', 'Grassland', 'Mouse', 'A Rattata is cautious in the extreme. Even while it is asleep, it constantly moves its ears and listens for danger. It will make its nest anywhere.', '1', 'RATICATE,Level,20', '0019_Rattata'),
(20, 'RATICATE', 'Raticate', 'NORMAL', NULL, 55, 81, 60, 50, 70, 97, 'Female50Percent', 'Medium', 145, 127, 50, 'RUNAWAY', 'GUTS', 'HUSTLE', 'Field', 3840, 0.7, 18.5, 'Brown', 'Quadruped', 'Grassland', 'Mouse', 'A Raticate''s sturdy fangs grow steadily. To keep them ground down, it gnaws on rocks and logs. It may even chew on the walls of houses.', '1', NULL, '0020_Raticate'),
(21, 'SPEAROW', 'Spearow', 'NORMAL', 'FLYING', 40, 60, 30, 31, 31, 70, 'Female50Percent', 'Medium', 52, 255, 50, 'KEENEYE', NULL, 'SNIPER', 'Flying', 3840, 0.3, 2.0, 'Brown', 'Winged', 'RoughTerrain', 'Tiny Bird', 'Its loud cry can be heard over half a mile away. If its high, keening cry is heard echoing all around, it is a sign that they are warning each other of danger.', '1', 'FEAROW,Level,20', '0021_Spearow'),
(22, 'FEAROW', 'Fearow', 'NORMAL', 'FLYING', 65, 90, 65, 61, 61, 100, 'Female50Percent', 'Medium', 155, 90, 50, 'KEENEYE', NULL, 'SNIPER', 'Flying', 3840, 1.2, 38.0, 'Brown', 'Winged', 'RoughTerrain', 'Beak', 'Its long neck and elongated beak are ideal for catching prey in soil or water. It deftly moves this extended and skinny beak to pluck prey.', '1', NULL, '0022_Fearow'),
(23, 'EKANS', 'Ekans', 'POISON', NULL, 35, 60, 44, 40, 54, 55, 'Female50Percent', 'Medium', 58, 255, 50, 'INTIMIDATE', 'SHEDSKIN', 'UNNERVE', 'Field,Dragon', 5120, 2.0, 6.9, 'Purple', 'Serpentine', 'Grassland', 'Snake', 'An Ekans curls itself up in a spiral while it rests. This position allows it to quickly respond to an enemy from any direction with a threat from its upraised head.', '1', 'ARBOK,Level,22', '0023_Ekans'),
(24, 'ARBOK', 'Arbok', 'POISON', NULL, 60, 95, 69, 65, 79, 80, 'Female50Percent', 'Medium', 157, 90, 50, 'INTIMIDATE', 'SHEDSKIN', 'UNNERVE', 'Field,Dragon', 5120, 3.5, 65.0, 'Purple', 'Serpentine', 'Grassland', 'Cobra', 'This Pokémon has a terrifically strong constricting power. It can even flatten steel oil drums. Once it wraps its body around its foe, escaping is impossible.', '1', NULL, '0024_Arbok'),
(25, 'PIKACHU', 'Pikachu', 'ELECTRIC', NULL, 35, 55, 40, 50, 50, 90, 'Female50Percent', 'Medium', 112, 190, 50, 'STATIC', NULL, 'LIGHTNINGROD', 'Field,Fairy', 2560, 0.4, 6.0, 'Yellow', 'Quadruped', 'Forest', 'Mouse', 'It stores electricity in the electric sacs on its cheeks. When it releases pent-up energy in a burst, the electric power is equal to a lightning bolt.', '1', 'RAICHU,Item,THUNDERSTONE', '0025_Pikachu'),
(26, 'RAICHU', 'Raichu', 'ELECTRIC', NULL, 60, 90, 55, 90, 80, 110, 'Female50Percent', 'Medium', 243, 75, 50, 'STATIC', NULL, 'LIGHTNINGROD', 'Field,Fairy', 2560, 0.8, 30.0, 'Yellow', 'BipedalTail', 'Forest', 'Mouse', 'If it stores too much electricity, its behavior turns aggressive. To avoid this, it occasionally discharges excess energy and calms itself down.', '1', NULL, '0026_Raichu'),
(27, 'SANDSHREW', 'Sandshrew', 'GROUND', NULL, 50, 75, 85, 20, 30, 40, 'Female50Percent', 'Medium', 60, 255, 50, 'SANDVEIL', NULL, 'SANDRUSH', 'Field', 5120, 0.6, 12.0, 'Yellow', 'BipedalTail', 'RoughTerrain', 'Mouse', 'When it curls up in a ball, it can make any attack bounce off harmlessly. Its hide has turned tough and solid as a result of living in the desert.', '1', 'SANDSLASH,Level,22', '0027_Sandshrew'),
(28, 'SANDSLASH', 'Sandslash', 'GROUND', NULL, 75, 100, 110, 45, 55, 65, 'Female50Percent', 'Medium', 158, 90, 50, 'SANDVEIL', NULL, 'SANDRUSH', 'Field', 5120, 1.0, 29.5, 'Yellow', 'BipedalTail', 'RoughTerrain', 'Mouse', 'It curls up in a ball to protect itself from enemy attacks. It also curls up to prevent heatstroke during the daytime when temperatures rise sharply.', '1', NULL, '0028_Sandslash'),
(29, 'NIDORANfE', 'Nidoran♀', 'POISON', NULL, 55, 47, 52, 40, 40, 41, 'AlwaysFemale', 'Parabolic', 55, 235, 50, 'POISONPOINT', 'RIVALRY', 'HUSTLE', 'Monster,Field', 5120, 0.4, 7.0, 'Blue', 'Quadruped', 'Grassland', 'Poison Pin', 'Its highly toxic barbs are thought to have developed as protection for this small-bodied Pokémon. When enraged, it releases a horrible toxin from its horn.', '1', 'NIDORINA,Level,16', '0029_Nidoran-F'),
(30, 'NIDORINA', 'Nidorina', 'POISON', NULL, 70, 62, 67, 55, 55, 56, 'AlwaysFemale', 'Parabolic', 128, 120, 50, 'POISONPOINT', 'RIVALRY', 'HUSTLE', 'Monster,Field', 5120, 0.8, 20.0, 'Blue', 'Quadruped', 'Grassland', 'Poison Pin', 'When it is with its friends or family, its barbs are tucked away to prevent injury. It appears to become nervous if separated from the others.', '1', 'NIDOQUEEN,Item,MOONSTONE', '0030_Nidorina'),
(31, 'NIDOQUEEN', 'Nidoqueen', 'POISON', 'GROUND', 90, 92, 87, 75, 85, 76, 'AlwaysFemale', 'Parabolic', 253, 45, 50, 'POISONPOINT', 'RIVALRY', 'SHEERFORCE', 'Monster,Field', 5120, 1.3, 60.0, 'Blue', 'BipedalTail', 'Grassland', 'Drill', 'It is adept at sending foes flying with harsh tackles using its tough, scaly body. This Pokémon is at its strongest when it is defending its young.', '1', NULL, '0031_Nidoqueen'),
(32, 'NIDORANmA', 'Nidoran♂', 'POISON', NULL, 46, 57, 40, 40, 40, 50, 'AlwaysMale', 'Parabolic', 55, 235, 50, 'POISONPOINT', 'RIVALRY', 'HUSTLE', 'Monster,Field', 5120, 0.5, 9.0, 'Purple', 'Quadruped', 'Grassland', 'Poison Pin', 'The male Nidoran has developed muscles that freely move its ears in any direction. Even the slightest sound does not escape this Pokémon''s notice.', '1', 'NIDORINO,Level,16', '0032_Nidoran-M'),
(33, 'NIDORINO', 'Nidorino', 'POISON', NULL, 61, 72, 57, 55, 55, 65, 'AlwaysMale', 'Parabolic', 128, 120, 50, 'POISONPOINT', 'RIVALRY', 'HUSTLE', 'Monster,Field', 5120, 0.9, 19.5, 'Purple', 'Quadruped', 'Grassland', 'Poison Pin', 'Its horn is harder than a diamond. If it senses a hostile presence, all the barbs on its back bristle up at once, and it challenges the foe with all its might.', '1', 'NIDOKING,Item,MOONSTONE', '0033_Nidorino'),
(34, 'NIDOKING', 'Nidoking', 'POISON', 'GROUND', 81, 102, 77, 85, 75, 85, 'AlwaysMale', 'Parabolic', 253, 45, 50, 'POISONPOINT', 'RIVALRY', 'SHEERFORCE', 'Monster,Field', 5120, 1.4, 62.0, 'Purple', 'BipedalTail', 'Grassland', 'Drill', 'A Nidoking''s thick tail packs enormously destructive power capable of toppling a metal transmission tower. Once it goes on a rampage, there is no stopping it.', '1', NULL, '0034_Nidoking'),
(35, 'CLEFAIRY', 'Clefairy', 'FAIRY', NULL, 70, 45, 48, 60, 65, 35, 'Female75Percent', 'Fast', 113, 150, 140, 'CUTECHARM', 'MAGICGUARD', 'FRIENDGUARD', 'Fairy', 2560, 0.6, 7.5, 'Pink', 'BipedalTail', 'Mountain', 'Fairy', 'On every night of a full moon, they come out to play. When dawn arrives, the tired Clefairy go to sleep nestled up against each other in deep and quiet mountains.', '1', 'CLEFABLE,Item,MOONSTONE', '0035_Clefairy'),
(36, 'CLEFABLE', 'Clefable', 'FAIRY', NULL, 95, 70, 73, 95, 90, 60, 'Female75Percent', 'Fast', 242, 25, 140, 'CUTECHARM', 'MAGICGUARD', 'UNAWARE', 'Fairy', 2560, 1.3, 40.0, 'Pink', 'BipedalTail', 'Mountain', 'Fairy', 'A Clefable uses its wings to skip lightly as if it were flying. Its bouncy step lets it even walk on water. On quiet, moonlit nights, it strolls on lakes.', '1', NULL, '0036_Clefable'),
(37, 'VULPIX', 'Vulpix', 'FIRE', NULL, 38, 41, 40, 50, 65, 65, 'Female75Percent', 'Medium', 60, 190, 50, 'FLASHFIRE', NULL, 'DROUGHT', 'Field', 5120, 0.6, 9.9, 'Brown', 'Quadruped', 'Grassland', 'Fox', 'It can freely control fire, making fiery orbs fly like will-o''-the-wisps. Just before evolution, its six tails grow hot as if on fire.', '1', 'NINETALES,Item,FIRESTONE', '0037_Vulpix'),
(38, 'NINETALES', 'Ninetales', 'FIRE', NULL, 73, 76, 75, 81, 100, 100, 'Female75Percent', 'Medium', 177, 75, 50, 'FLASHFIRE', NULL, 'DROUGHT', 'Field', 5120, 1.1, 19.9, 'Yellow', 'Quadruped', 'Grassland', 'Fox', 'It has long been said that each of the nine tails embody an enchanted power. A long-lived Ninetales will have fur that shines like gold.', '1', NULL, '0038_Ninetales'),
(39, 'JIGGLYPUFF', 'Jigglypuff', 'NORMAL', 'FAIRY', 115, 45, 20, 45, 25, 20, 'Female75Percent', 'Fast', 95, 170, 50, 'CUTECHARM', 'COMPETITIVE', 'FRIENDGUARD', 'Fairy', 2560, 0.5, 5.5, 'Pink', 'Bipedal', 'Grassland', 'Balloon', 'Nothing can avoid falling asleep hearing a Jigglypuff''s song. The sound waves of its singing voice match the brain waves of someone in a deep sleep.', '1', 'WIGGLYTUFF,Item,MOONSTONE', '0039_Jigglypuff'),
(40, 'WIGGLYTUFF', 'Wigglytuff', 'NORMAL', 'FAIRY', 140, 70, 45, 85, 50, 45, 'Female75Percent', 'Fast', 218, 50, 50, 'CUTECHARM', 'COMPETITIVE', 'FRISK', 'Fairy', 2560, 1.0, 12.0, 'Pink', 'Bipedal', 'Grassland', 'Balloon', 'Its fur is the ultimate in luxuriousness. Sleeping alongside a Wigglytuff is simply divine. Its body expands seemingly without end when it inhales.', '1', NULL, '0040_Wigglytuff'),
(41, 'ZUBAT', 'Zubat', 'POISON', 'FLYING', 40, 45, 35, 30, 40, 55, 'Female50Percent', 'Medium', 49, 255, 50, 'INNERFOCUS', NULL, 'INFILTRATOR', 'Flying', 3840, 0.8, 7.5, 'Purple', 'Winged', 'Cave', 'Bat', 'While living in pitch-black caverns, their eyes gradually grew shut and deprived them of vision. They use ultrasonic waves to detect obstacles.', '1', 'GOLBAT,Level,22', '0041_Zubat'),
(42, 'GOLBAT', 'Golbat', 'POISON', 'FLYING', 75, 80, 70, 65, 75, 90, 'Female50Percent', 'Medium', 159, 90, 50, 'INNERFOCUS', NULL, 'INFILTRATOR', 'Flying', 3840, 1.6, 55.0, 'Purple', 'Winged', 'Cave', 'Bat', 'Its fangs easily puncture even thick animal hide. It loves to feast on the blood of people and Pokémon. It flits about in darkness and strikes from behind.', '1', 'CROBAT,Happiness,', '0042_Golbat'),
(43, 'ODDISH', 'Oddish', 'GRASS', 'POISON', 45, 50, 55, 75, 65, 30, 'Female50Percent', 'Parabolic', 64, 255, 50, 'CHLOROPHYLL', NULL, 'RUNAWAY', 'Grass', 5120, 0.5, 5.4, 'Blue', 'HeadLegs', 'Grassland', 'Weed', 'It grows by absorbing moonlight. During the daytime, it buries itself in the ground, leaving only its leaves exposed to avoid detection by its enemies.', '1', 'GLOOM,Level,21', '0043_Oddish'),
(44, 'GLOOM', 'Gloom', 'GRASS', 'POISON', 60, 65, 70, 85, 75, 40, 'Female50Percent', 'Parabolic', 138, 120, 50, 'CHLOROPHYLL', NULL, 'STENCH', 'Grass', 5120, 0.8, 8.6, 'Blue', 'Bipedal', 'Grassland', 'Weed', 'A horribly noxious honey drools from its mouth. One whiff of the honey can result in memory loss. Some fans are said to enjoy this overwhelming stink, however.', '1', 'VILEPLUME,Item,LEAFSTONE,BELLOSSOM,Item,SUNSTONE', '0044_Gloom'),
(45, 'VILEPLUME', 'Vileplume', 'GRASS', 'POISON', 75, 80, 85, 110, 90, 50, 'Female50Percent', 'Parabolic', 245, 45, 50, 'CHLOROPHYLL', NULL, 'EFFECTSPORE', 'Grass', 5120, 1.2, 18.6, 'Red', 'Bipedal', 'Grassland', 'Flower', 'In seasons when it produces more pollen, the air around a Vileplume turns yellow with the powder as it walks. The pollen is highly toxic and causes paralysis.', '1', NULL, '0045_Vileplume'),
(46, 'PARAS', 'Paras', 'BUG', 'GRASS', 35, 70, 55, 45, 55, 25, 'Female50Percent', 'Medium', 57, 190, 50, 'EFFECTSPORE', 'DRYSKIN', 'DAMP', 'Bug,Grass', 5120, 0.3, 5.4, 'Red', 'Insectoid', 'Forest', 'Mushroom', 'A Paras has parasitic tochukaso mushrooms growing on its back. They grow by drawing nutrients from the host. They are valued as a medicine for long life.', '1', 'PARASECT,Level,24', '0046_Paras'),
(47, 'PARASECT', 'Parasect', 'BUG', 'GRASS', 60, 95, 80, 60, 80, 30, 'Female50Percent', 'Medium', 142, 75, 50, 'EFFECTSPORE', 'DRYSKIN', 'DAMP', 'Bug,Grass', 5120, 1.0, 29.5, 'Red', 'Insectoid', 'Forest', 'Mushroom', 'Parasect are known to infest the roots of large trees en masse and drain nutrients. When an infested tree dies, they move onto another tree all at once.', '1', NULL, '0047_Parasect'),
(48, 'VENONAT', 'Venonat', 'BUG', 'POISON', 60, 55, 50, 40, 55, 45, 'Female50Percent', 'Medium', 61, 190, 50, 'COMPOUNDEYES', 'TINTEDLENS', 'RUNAWAY', 'Bug', 5120, 1.0, 30.0, 'Purple', 'Bipedal', 'Forest', 'Insect', 'Its coat of thin, stiff hair that covers its entire body is said to have evolved for protection. Its large eyes never fail to spot even miniscule prey.', '1', 'VENOMOTH,Level,31', '0048_Venonat'),
(49, 'VENOMOTH', 'Venomoth', 'BUG', 'POISON', 70, 65, 60, 90, 75, 90, 'Female50Percent', 'Medium', 158, 75, 50, 'SHIELDDUST', 'TINTEDLENS', 'WONDERSKIN', 'Bug', 5120, 1.5, 12.5, 'Purple', 'MultiWinged', 'Forest', 'Poison Moth', 'Venomoth are nocturnal--they only are active at night. Their favorite prey are insects that gather around streetlights, attracted by the light in the darkness.', '1', NULL, '0049_Venomoth'),
(50, 'DIGLETT', 'Diglett', 'GROUND', NULL, 10, 55, 25, 35, 45, 95, 'Female50Percent', 'Medium', 53, 255, 50, 'SANDVEIL', 'ARENATRAP', 'SANDFORCE', 'Field', 5120, 0.2, 0.8, 'Brown', 'HeadBase', 'Cave', 'Mole', 'Diglett are raised in most farms. The reason is simple--wherever they burrow, the soil is left perfectly tilled for growing delicious crops.', '1', 'DUGTRIO,Level,26', '0050_Diglett'),
(51, 'DUGTRIO', 'Dugtrio', 'GROUND', NULL, 35, 100, 50, 50, 70, 120, 'Female50Percent', 'Medium', 149, 50, 50, 'SANDVEIL', 'ARENATRAP', 'SANDFORCE', 'Field', 5120, 0.7, 33.3, 'Brown', 'MultiBody', 'Cave', 'Mole', 'Because the triplets originally split from one body, they think exactly alike. They work cooperatively to burrow endlessly through the ground.', '1', NULL, '0051_Dugtrio'),
(52, 'MEOWTH', 'Meowth', 'NORMAL', NULL, 40, 45, 35, 40, 40, 90, 'Female50Percent', 'Medium', 58, 255, 50, 'PICKUP', 'TECHNICIAN', 'UNNERVE', 'Field', 5120, 0.4, 4.2, 'Yellow', 'Quadruped', 'Urban', 'Scratch Cat', 'Meowth withdraw their sharp claws into their paws to silently sneak about. For some reason, this Pokémon loves shiny coins that glitter with light.', '1', 'PERSIAN,Level,28,PERRSERKER,None,', '0052_Meowth'),
(53, 'PERSIAN', 'Persian', 'NORMAL', NULL, 65, 70, 60, 65, 65, 115, 'Female50Percent', 'Medium', 154, 90, 50, 'LIMBER', 'TECHNICIAN', 'UNNERVE', 'Field', 5120, 1.0, 32.0, 'Yellow', 'Quadruped', 'Urban', 'Classy Cat', 'A Persian''s six bold whiskers sense air movements to determine what is in its vicinity. It becomes docile if grabbed by the whiskers.', '1', NULL, '0053_Persian'),
(54, 'PSYDUCK', 'Psyduck', 'WATER', NULL, 50, 52, 48, 65, 50, 55, 'Female50Percent', 'Medium', 64, 190, 50, 'DAMP', 'CLOUDNINE', 'SWIFTSWIM', 'Water1,Field', 5120, 0.8, 19.6, 'Yellow', 'BipedalTail', 'WatersEdge', 'Duck', 'When its headache intensifies, it starts using strange powers. However, it has no recollection of its powers, so it always looks befuddled and bewildered.', '1', 'GOLDUCK,Level,33', '0054_Psyduck'),
(55, 'GOLDUCK', 'Golduck', 'WATER', NULL, 80, 82, 78, 95, 80, 85, 'Female50Percent', 'Medium', 175, 75, 50, 'DAMP', 'CLOUDNINE', 'SWIFTSWIM', 'Water1,Field', 5120, 1.7, 76.6, 'Blue', 'BipedalTail', 'WatersEdge', 'Duck', 'A Golduck is an adept swimmer. It sometimes joins competitive swimmers in training. It uses psychic powers when its forehead shimmers with light.', '1', NULL, '0055_Golduck'),
(56, 'MANKEY', 'Mankey', 'FIGHTING', NULL, 40, 80, 35, 35, 45, 70, 'Female50Percent', 'Medium', 61, 190, 50, 'VITALSPIRIT', 'ANGERPOINT', 'DEFIANT', 'Field', 5120, 0.5, 28.0, 'Brown', 'BipedalTail', 'Mountain', 'Pig Monkey', 'When it starts shaking and its nasal breathing turns rough, it''s a sure sign of anger. However, since this happens instantly, there is no time to flee.', '1', 'PRIMEAPE,Level,28', '0056_Mankey'),
(57, 'PRIMEAPE', 'Primeape', 'FIGHTING', NULL, 65, 105, 60, 60, 70, 95, 'Female50Percent', 'Medium', 159, 75, 50, 'VITALSPIRIT', 'ANGERPOINT', 'DEFIANT', 'Field', 5120, 1.0, 32.0, 'Brown', 'BipedalTail', 'Mountain', 'Pig Monkey', 'When it becomes furious, its blood circulation becomes more robust, and its muscles are made stronger. But it also becomes much less intelligent.', '1', NULL, '0057_Primeape'),
(58, 'GROWLITHE', 'Growlithe', 'FIRE', NULL, 55, 70, 45, 70, 50, 60, 'Female25Percent', 'Slow', 70, 190, 50, 'INTIMIDATE', 'FLASHFIRE', 'JUSTIFIED', 'Field', 5120, 0.7, 19.0, 'Brown', 'Quadruped', 'Grassland', 'Puppy', 'Its superb sense of smell ensures that this Pokémon won''t forget any scent, no matter what. It uses its sense of smell to detect the emotions of others.', '1', 'ARCANINE,Item,FIRESTONE', '0058_Growlithe'),
(59, 'ARCANINE', 'Arcanine', 'FIRE', NULL, 90, 110, 80, 100, 80, 95, 'Female25Percent', 'Slow', 194, 75, 50, 'INTIMIDATE', 'FLASHFIRE', 'JUSTIFIED', 'Field', 5120, 1.9, 155.0, 'Brown', 'Quadruped', 'Grassland', 'Legendary', 'This fleet-footed Pokémon is said to run over 6,200 miles in a single day and night. The fire that blazes wildly within its body is its source of power.', '1', NULL, '0059_Arcanine'),
(60, 'POLIWAG', 'Poliwag', 'WATER', NULL, 40, 50, 40, 40, 40, 90, 'Female50Percent', 'Parabolic', 60, 255, 50, 'WATERABSORB', 'DAMP', 'SWIFTSWIM', 'Water1', 5120, 0.6, 12.4, 'Blue', 'HeadLegs', 'WatersEdge', 'Tadpole', 'It is possible to see this Pokémon''s spiral innards right through its thin skin. However, the skin is also very flexible. Even sharp fangs bounce right off it.', '1', 'POLIWHIRL,Level,25', '0060_Poliwag'),
(61, 'POLIWHIRL', 'Poliwhirl', 'WATER', NULL, 65, 65, 65, 50, 50, 90, 'Female50Percent', 'Parabolic', 135, 120, 50, 'WATERABSORB', 'DAMP', 'SWIFTSWIM', 'Water1', 5120, 1.0, 20.0, 'Blue', 'Bipedal', 'WatersEdge', 'Tadpole', 'Its body surface is always wet and slick with an oily fluid. Because of this greasy covering, it can easily slip and slide out of the clutches of any enemy in battle.', '1', 'POLIWRATH,Item,WATERSTONE,POLITOED,TradeItem,KINGSROCK', '0061_Poliwhirl'),
(62, 'POLIWRATH', 'Poliwrath', 'WATER', 'FIGHTING', 90, 95, 95, 70, 90, 70, 'Female50Percent', 'Parabolic', 255, 45, 50, 'WATERABSORB', 'DAMP', 'SWIFTSWIM', 'Water1', 5120, 1.3, 54.0, 'Blue', 'Bipedal', 'WatersEdge', 'Tadpole', 'Its highly developed muscles never grow fatigued, however much it exercises. This Pokémon can swim back and forth across the Pacific Ocean without effort.', '1', NULL, '0062_Poliwrath'),
(63, 'ABRA', 'Abra', 'PSYCHIC', NULL, 25, 20, 15, 105, 55, 90, 'Female25Percent', 'Parabolic', 62, 200, 50, 'SYNCHRONIZE', 'INNERFOCUS', 'MAGICGUARD', 'Humanlike', 5120, 0.9, 19.5, 'Brown', 'BipedalTail', 'Urban', 'Psi', 'A Pokémon that sleeps 18 hours a day. Observation revealed that it uses Teleport to change its location once every hour.', '1', 'KADABRA,Level,16', '0063_Abra'),
(64, 'KADABRA', 'Kadabra', 'PSYCHIC', NULL, 40, 35, 30, 120, 70, 105, 'Female25Percent', 'Parabolic', 140, 100, 50, 'SYNCHRONIZE', 'INNERFOCUS', 'MAGICGUARD', 'Humanlike', 5120, 1.3, 56.5, 'Brown', 'BipedalTail', 'Urban', 'Psi', 'It is rumored that a boy with psychic abilities suddenly transformed into Kadabra while he was assisting research into extrasensory powers.', '1', 'ALAKAZAM,Trade,', '0064_Kadabra'),
(65, 'ALAKAZAM', 'Alakazam', 'PSYCHIC', NULL, 55, 50, 45, 135, 95, 120, 'Female25Percent', 'Parabolic', 250, 50, 50, 'SYNCHRONIZE', 'INNERFOCUS', 'MAGICGUARD', 'Humanlike', 5120, 1.5, 48.0, 'Brown', 'Bipedal', 'Urban', 'Psi', 'While it has strong psychic abilities and high intelligence, an Alakazam''s muscles are very weak. It uses psychic power to move its body.', '1', NULL, '0065_Alakazam'),
(66, 'MACHOP', 'Machop', 'FIGHTING', NULL, 70, 80, 50, 35, 35, 35, 'Female25Percent', 'Parabolic', 61, 180, 50, 'GUTS', 'NOGUARD', 'STEADFAST', 'Humanlike', 5120, 0.8, 19.5, 'Gray', 'BipedalTail', 'Mountain', 'Superpower', 'It continually undertakes strenuous training to master all forms of martial arts. Its strength lets it easily hoist a sumo wrestler onto its shoulders.', '1', 'MACHOKE,Level,28', '0066_Machop'),
(67, 'MACHOKE', 'Machoke', 'FIGHTING', NULL, 80, 100, 70, 50, 60, 45, 'Female25Percent', 'Parabolic', 142, 90, 50, 'GUTS', 'NOGUARD', 'STEADFAST', 'Humanlike', 5120, 1.5, 70.5, 'Gray', 'Bipedal', 'Mountain', 'Superpower', 'A belt is worn by a Machoke to keep its overwhelming power under control. Because it is so dangerous, no one has ever removed the belt.', '1', 'MACHAMP,Trade,', '0067_Machoke'),
(68, 'MACHAMP', 'Machamp', 'FIGHTING', NULL, 90, 130, 80, 65, 85, 55, 'Female25Percent', 'Parabolic', 253, 45, 50, 'GUTS', 'NOGUARD', 'STEADFAST', 'Humanlike', 5120, 1.6, 130.0, 'Gray', 'Bipedal', 'Mountain', 'Superpower', 'It is impossible to defend against punches and chops doled out by its four arms. Its fighting spirit flares up when it faces a tough opponent.', '1', NULL, '0068_Machamp'),
(69, 'BELLSPROUT', 'Bellsprout', 'GRASS', 'POISON', 50, 75, 35, 70, 30, 40, 'Female50Percent', 'Parabolic', 60, 255, 50, 'CHLOROPHYLL', NULL, 'GLUTTONY', 'Grass', 5120, 0.7, 4.0, 'Green', 'Bipedal', 'Forest', 'Flower', 'A Bellsprout''s thin and flexible body lets it bend and sway to avoid any attack, however strong it may be. From its mouth, it leaks a fluid that melts even iron.', '1', 'WEEPINBELL,Level,21', '0069_Bellsprout'),
(70, 'WEEPINBELL', 'Weepinbell', 'GRASS', 'POISON', 65, 90, 50, 85, 45, 55, 'Female50Percent', 'Parabolic', 137, 120, 50, 'CHLOROPHYLL', NULL, 'GLUTTONY', 'Grass', 5120, 1.0, 6.4, 'Green', 'HeadBase', 'Forest', 'Flycatcher', 'At night, a Weepinbell hangs on to a tree branch with its hooked rear and sleeps. If it moves around in its sleep, it may wake up to find itself on the ground.', '1', 'VICTREEBEL,Item,LEAFSTONE', '0070_Weepinbell'),
(71, 'VICTREEBEL', 'Victreebel', 'GRASS', 'POISON', 80, 105, 65, 100, 70, 70, 'Female50Percent', 'Parabolic', 245, 45, 50, 'CHLOROPHYLL', NULL, 'GLUTTONY', 'Grass', 5120, 1.7, 15.5, 'Green', 'HeadBase', 'Forest', 'Flycatcher', 'The long vine extending from its head is waved about as if it were a living thing to attract prey. When an unsuspecting victim approaches, it is swallowed whole.', '1', NULL, '0071_Victreebel'),
(72, 'TENTACOOL', 'Tentacool', 'WATER', 'POISON', 40, 40, 35, 50, 100, 70, 'Female50Percent', 'Slow', 67, 190, 50, 'CLEARBODY', 'LIQUIDOOZE', 'RAINDISH', 'Water3', 5120, 0.9, 45.5, 'Blue', 'Multiped', 'Sea', 'Jellyfish', 'Its body is almost entirely composed of water. It ensnares its foe with its two long tentacles, then stabs with the poison stingers at their tips.', '1', 'TENTACRUEL,Level,30', '0072_Tentacool'),
(73, 'TENTACRUEL', 'Tentacruel', 'WATER', 'POISON', 80, 70, 65, 80, 120, 100, 'Female50Percent', 'Slow', 180, 60, 50, 'CLEARBODY', 'LIQUIDOOZE', 'RAINDISH', 'Water3', 5120, 1.6, 55.0, 'Blue', 'Multiped', 'Sea', 'Jellyfish', 'It lives in complex rock formations on the ocean floor and traps prey using its 80 tentacles. Its red orbs glow when it grows excited or agitated.', '1', NULL, '0073_Tentacruel'),
(74, 'GEODUDE', 'Geodude', 'ROCK', 'GROUND', 40, 80, 100, 30, 30, 20, 'Female50Percent', 'Parabolic', 60, 255, 50, 'ROCKHEAD', 'STURDY', 'SANDVEIL', 'Mineral', 3840, 0.4, 20.0, 'Brown', 'HeadArms', 'Mountain', 'Rock', 'It climbs mountain paths using only the power of its arms. Because they look just like boulders lining paths, hikers may step on them without noticing.', '1', 'GRAVELER,Level,25', '0074_Geodude'),
(75, 'GRAVELER', 'Graveler', 'ROCK', 'GROUND', 55, 95, 115, 45, 45, 35, 'Female50Percent', 'Parabolic', 137, 120, 50, 'ROCKHEAD', 'STURDY', 'SANDVEIL', 'Mineral', 3840, 1.0, 105.0, 'Brown', 'Bipedal', 'Mountain', 'Rock', 'They descend from mountains by tumbling down steep slopes. They are so brutal, they smash aside obstructing trees and huge boulders with thunderous tackles.', '1', 'GOLEM,Trade,', '0075_Graveler'),
(76, 'GOLEM', 'Golem', 'ROCK', 'GROUND', 80, 120, 130, 55, 65, 45, 'Female50Percent', 'Parabolic', 248, 45, 50, 'ROCKHEAD', 'STURDY', 'SANDVEIL', 'Mineral', 3840, 1.4, 300.0, 'Brown', 'Bipedal', 'Mountain', 'Megaton', 'It is said to live in volcanic craters on mountain peaks. Once a year, it sheds its hide and grows larger. The shed hide crumbles and returns to the soil.', '1', NULL, '0076_Golem'),
(77, 'PONYTA', 'Ponyta', 'FIRE', NULL, 50, 85, 55, 65, 65, 90, 'Female50Percent', 'Medium', 82, 190, 50, 'RUNAWAY', 'FLASHFIRE', 'FLAMEBODY', 'Field', 5120, 1.0, 30.0, 'Yellow', 'Quadruped', 'Grassland', 'Fire Horse', 'A Ponyta is very weak at birth. It can barely stand up. Its legs become stronger as it stumbles and falls while trying to keep up with its parent.', '1', 'RAPIDASH,Level,40', '0077_Ponyta'),
(78, 'RAPIDASH', 'Rapidash', 'FIRE', NULL, 65, 100, 70, 80, 80, 105, 'Female50Percent', 'Medium', 175, 60, 50, 'RUNAWAY', 'FLASHFIRE', 'FLAMEBODY', 'Field', 5120, 1.7, 95.0, 'Yellow', 'Quadruped', 'Grassland', 'Fire Horse', 'It usually canters casually in the fields and plains. But once a Rapidash turns serious, its fiery manes flare and blaze as it gallops its way up to 150 mph.', '1', NULL, '0078_Rapidash'),
(79, 'SLOWPOKE', 'Slowpoke', 'WATER', 'PSYCHIC', 90, 65, 65, 40, 40, 15, 'Female50Percent', 'Medium', 63, 190, 50, 'OBLIVIOUS', 'OWNTEMPO', 'REGENERATOR', 'Monster,Water1', 5120, 1.2, 36.0, 'Pink', 'Quadruped', 'WatersEdge', 'Dopey', 'It catches prey by dipping its tail in water at the side of a river. But it often forgets what it is doing and spends whole days just loafing at the water''s edge.', '1', 'SLOWBRO,Level,37,SLOWKING,TradeItem,KINGSROCK', '0079_Slowpoke'),
(80, 'SLOWBRO', 'Slowbro', 'WATER', 'PSYCHIC', 95, 75, 110, 100, 80, 30, 'Female50Percent', 'Medium', 172, 75, 50, 'OBLIVIOUS', 'OWNTEMPO', 'REGENERATOR', 'Monster,Water1', 5120, 1.6, 78.5, 'Pink', 'BipedalTail', 'WatersEdge', 'Hermit Crab', 'Its tail has a Shellder firmly attached with a bite. As a result, the tail can''t be used for fishing anymore. This forces it to reluctantly swim and catch prey.', '1', NULL, '0080_Slowbro');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(81, 'MAGNEMITE', 'Magnemite', 'ELECTRIC', 'STEEL', 25, 35, 70, 95, 55, 45, 'Genderless', 'Medium', 65, 190, 50, 'MAGNETPULL', 'STURDY', 'ANALYTIC', 'Mineral', 5120, 0.3, 6.0, 'Gray', 'HeadArms', 'RoughTerrain', 'Magnet', 'The units at its sides are extremely powerful magnets. They generate enough magnetism to draw in iron objects from over 300 feet away.', '1', 'MAGNETON,Level,30', '0081_Magnemite'),
(82, 'MAGNETON', 'Magneton', 'ELECTRIC', 'STEEL', 50, 60, 95, 120, 70, 70, 'Genderless', 'Medium', 163, 60, 50, 'MAGNETPULL', 'STURDY', 'ANALYTIC', 'Mineral', 5120, 1.0, 60.0, 'Gray', 'MultiBody', 'RoughTerrain', 'Magnet', 'It is actually three Magnemite linked by magnetism. It generates powerful radio waves that raise temperatures by 3.6 degrees F within a 3,300-foot radius.', '1', 'MAGNEZONE,Item,THUNDERSTONE,MAGNEZONE,LocationFlag,Magnetic', '0082_Magneton'),
(83, 'FARFETCHD', 'Farfetch''d', 'NORMAL', 'FLYING', 52, 90, 55, 58, 62, 60, 'Female50Percent', 'Medium', 132, 45, 50, 'KEENEYE', 'INNERFOCUS', 'DEFIANT', 'Flying,Field', 5120, 0.8, 15.0, 'Brown', 'Winged', 'Grassland', 'Wild Duck', 'It is always seen with a stick from a plant. Apparently, there are good sticks and bad sticks. This Pokémon occasionally fights with others over choice sticks.', '1', 'SIRFETCHD,None,', '0083_Farfetch''d'),
(84, 'DODUO', 'Doduo', 'NORMAL', 'FLYING', 35, 85, 45, 35, 35, 75, 'Female50Percent', 'Medium', 62, 190, 50, 'RUNAWAY', 'EARLYBIRD', 'TANGLEDFEET', 'Flying', 5120, 1.4, 39.2, 'Brown', 'HeadLegs', 'Grassland', 'Twin Bird', 'Even while eating or sleeping, one of the heads remains always vigilant for any sign of danger. When threatened, it flees at over 60 miles per hour.', '1', 'DODRIO,Level,31', '0084_Doduo'),
(85, 'DODRIO', 'Dodrio', 'NORMAL', 'FLYING', 60, 110, 70, 60, 60, 110, 'Female50Percent', 'Medium', 165, 45, 50, 'RUNAWAY', 'EARLYBIRD', 'TANGLEDFEET', 'Flying', 5120, 1.8, 85.2, 'Brown', 'HeadLegs', 'Grassland', 'Triple Bird', 'A peculiar Pokémon species with three heads. It vigorously races across grassy plains even in arid seasons with little rainfall.', '1', NULL, '0085_Dodrio'),
(86, 'SEEL', 'Seel', 'WATER', NULL, 65, 45, 55, 45, 70, 45, 'Female50Percent', 'Medium', 65, 190, 50, 'THICKFAT', 'HYDRATION', 'ICEBODY', 'Water1,Field', 5120, 1.1, 90.0, 'White', 'Finned', 'Sea', 'Sea Lion', 'Seel hunt for prey in frigid, ice-covered seas. When it needs to breathe, it punches a hole through the ice with the sharply protruding section of its head.', '1', 'DEWGONG,Level,34', '0086_Seel'),
(87, 'DEWGONG', 'Dewgong', 'WATER', 'ICE', 90, 70, 80, 70, 95, 70, 'Female50Percent', 'Medium', 166, 75, 50, 'THICKFAT', 'HYDRATION', 'ICEBODY', 'Water1,Field', 5120, 1.7, 120.0, 'White', 'Finned', 'Sea', 'Sea Lion', 'It loves to snooze on bitterly cold ice. The sight of this Pokémon sleeping on a glacier was mistakenly thought to be a mermaid by a mariner long ago.', '1', NULL, '0087_Dewgong'),
(88, 'GRIMER', 'Grimer', 'POISON', NULL, 80, 80, 50, 40, 50, 25, 'Female50Percent', 'Medium', 65, 190, 50, 'STENCH', 'STICKYHOLD', 'POISONTOUCH', 'Amorphous', 5120, 0.9, 30.0, 'Purple', 'HeadArms', 'Urban', 'Sludge', 'Born from polluted sludge in the sea, Grimer''s favorite food is anything filthy. They feed on wastewater pumped out from factories.', '1', 'MUK,Level,38', '0088_Grimer'),
(89, 'MUK', 'Muk', 'POISON', NULL, 105, 105, 75, 65, 100, 50, 'Female50Percent', 'Medium', 175, 75, 50, 'STENCH', 'STICKYHOLD', 'POISONTOUCH', 'Amorphous', 5120, 1.2, 30.0, 'Purple', 'HeadArms', 'Urban', 'Sludge', 'It prefers warm and humid habitats. In the summertime, the toxic substances in its body intensify, making Muk reek like putrid kitchen garbage.', '1', NULL, '0089_Muk'),
(90, 'SHELLDER', 'Shellder', 'WATER', NULL, 30, 65, 100, 45, 25, 40, 'Female50Percent', 'Slow', 61, 190, 50, 'SHELLARMOR', 'SKILLLINK', 'OVERCOAT', 'Water3', 5120, 0.3, 4.0, 'Purple', 'Head', 'Sea', 'Bivalve', 'At night, it burrows a hole in the seafloor with its broad tongue to make a place to sleep. While asleep, it closes its shell, but leaves its tongue hanging out.', '1', 'CLOYSTER,Item,WATERSTONE', '0090_Shellder'),
(91, 'CLOYSTER', 'Cloyster', 'WATER', 'ICE', 50, 95, 180, 85, 45, 70, 'Female50Percent', 'Slow', 184, 60, 50, 'SHELLARMOR', 'SKILLLINK', 'OVERCOAT', 'Water3', 5120, 1.5, 132.5, 'Purple', 'Head', 'Sea', 'Bivalve', 'It swims in the sea by swallowing water, then jetting it out toward the rear. The Cloyster shoots spikes from its shell using the same system.', '1', NULL, '0091_Cloyster'),
(92, 'GASTLY', 'Gastly', 'GHOST', 'POISON', 30, 35, 30, 100, 35, 80, 'Female50Percent', 'Parabolic', 62, 190, 50, 'LEVITATE', NULL, NULL, 'Amorphous', 5120, 1.3, 0.1, 'Purple', 'Head', 'Cave', 'Gas', 'When exposed to a strong wind, a Gastly''s gaseous body quickly dwindles away. They cluster under the eaves of houses to escape the ravages of wind.', '1', 'HAUNTER,Level,25', '0092_Gastly'),
(93, 'HAUNTER', 'Haunter', 'GHOST', 'POISON', 45, 50, 45, 115, 55, 95, 'Female50Percent', 'Parabolic', 142, 90, 50, 'LEVITATE', NULL, NULL, 'Amorphous', 5120, 1.6, 0.1, 'Purple', 'HeadArms', 'Cave', 'Gas', 'If a Haunter beckons you while it is floating in darkness, don''t approach it. This Pokémon will try to lick you with its tongue and steal your life away.', '1', 'GENGAR,Trade,', '0093_Haunter'),
(94, 'GENGAR', 'Gengar', 'GHOST', 'POISON', 60, 65, 60, 130, 75, 110, 'Female50Percent', 'Parabolic', 250, 45, 50, 'CURSEDBODY', NULL, NULL, 'Amorphous', 5120, 1.5, 40.5, 'Purple', 'BipedalTail', 'Cave', 'Shadow', 'Deep in the night, your shadow cast by a streetlight may suddenly overtake you. It is actually a Gengar running past you, pretending to be your shadow.', '1', NULL, '0094_Gengar'),
(95, 'ONIX', 'Onix', 'ROCK', 'GROUND', 35, 45, 160, 30, 45, 70, 'Female50Percent', 'Medium', 77, 45, 50, 'ROCKHEAD', 'STURDY', 'WEAKARMOR', 'Mineral', 6400, 8.8, 210.0, 'Gray', 'Serpentine', 'Cave', 'Rock Snake', 'There is a magnet in its brain that prevents an Onix from losing direction while tunneling. As it grows older, its body becomes steadily rounder and smoother.', '1', 'STEELIX,TradeItem,METALCOAT', '0095_Onix'),
(96, 'DROWZEE', 'Drowzee', 'PSYCHIC', NULL, 60, 48, 45, 43, 90, 42, 'Female50Percent', 'Medium', 66, 190, 50, 'INSOMNIA', 'FOREWARN', 'INNERFOCUS', 'Humanlike', 5120, 1.0, 32.4, 'Yellow', 'Bipedal', 'Grassland', 'Hypnosis', 'If your nose becomes itchy while you are sleeping, it''s a sure sign that a Drowzee is standing above your pillow and trying to eat your dream through your nostrils.', '1', 'HYPNO,Level,26', '0096_Drowzee'),
(97, 'HYPNO', 'Hypno', 'PSYCHIC', NULL, 85, 73, 70, 73, 115, 67, 'Female50Percent', 'Medium', 169, 75, 50, 'INSOMNIA', 'FOREWARN', 'INNERFOCUS', 'Humanlike', 5120, 1.6, 75.6, 'Yellow', 'Bipedal', 'Grassland', 'Hypnosis', 'The arcing movement and glitter of the pendulum in a Hypno''s hand lull the foe into deep hypnosis. While searching for prey, it polishes the pendulum.', '1', NULL, '0097_Hypno'),
(98, 'KRABBY', 'Krabby', 'WATER', NULL, 30, 105, 90, 25, 25, 50, 'Female50Percent', 'Medium', 65, 225, 50, 'HYPERCUTTER', 'SHELLARMOR', 'SHEERFORCE', 'Water3', 5120, 0.4, 6.5, 'Red', 'Insectoid', 'WatersEdge', 'River Crab', 'Krabby live in holes dug into beaches. On sandy shores with little in the way of food, they can be seen squabbling with each other over territory.', '1', 'KINGLER,Level,28', '0098_Krabby'),
(99, 'KINGLER', 'Kingler', 'WATER', NULL, 55, 130, 115, 50, 50, 75, 'Female50Percent', 'Medium', 166, 60, 50, 'HYPERCUTTER', 'SHELLARMOR', 'SHEERFORCE', 'Water3', 5120, 1.3, 60.0, 'Red', 'Insectoid', 'WatersEdge', 'Pincer', 'It waves its huge, oversized claw in the air to communicate with others. But since the claw is so heavy, this Pokémon quickly tires.', '1', NULL, '0099_Kingler'),
(100, 'VOLTORB', 'Voltorb', 'ELECTRIC', NULL, 40, 30, 50, 55, 55, 100, 'Genderless', 'Medium', 66, 190, 50, 'SOUNDPROOF', 'STATIC', 'AFTERMATH', 'Mineral', 5120, 0.5, 10.4, 'Red', 'Head', 'Urban', 'Ball', 'It bears an uncanny and unexplained resemblance to a Poké Ball. Because it explodes at the slightest shock, even veteran trainers treat it with caution.', '1', 'ELECTRODE,Level,30', '0100_Voltorb'),
(101, 'ELECTRODE', 'Electrode', 'ELECTRIC', NULL, 60, 50, 70, 80, 80, 150, 'Genderless', 'Medium', 172, 60, 50, 'SOUNDPROOF', 'STATIC', 'AFTERMATH', 'Mineral', 5120, 1.2, 66.6, 'Red', 'Head', 'Urban', 'Ball', 'They appear in great numbers at electric power plants. Because they feed on electricity, they cause massive and chaotic blackouts in nearby cities.', '1', NULL, '0101_Electrode'),
(102, 'EXEGGCUTE', 'Exeggcute', 'GRASS', 'PSYCHIC', 60, 40, 80, 60, 45, 40, 'Female50Percent', 'Slow', 65, 90, 50, 'CHLOROPHYLL', NULL, 'HARVEST', 'Grass', 5120, 0.4, 2.5, 'Pink', 'MultiBody', 'Forest', 'Egg', 'It consists of six eggs that care for each other. The eggs attract each other and spin around. When cracks increasingly appear, it is close to evolution.', '1', 'EXEGGUTOR,Item,LEAFSTONE', '0102_Exeggcute'),
(103, 'EXEGGUTOR', 'Exeggutor', 'GRASS', 'PSYCHIC', 95, 95, 85, 125, 75, 55, 'Female50Percent', 'Slow', 186, 45, 50, 'CHLOROPHYLL', NULL, 'HARVEST', 'Grass', 5120, 2.0, 120.0, 'Yellow', 'HeadLegs', 'Forest', 'Coconut', 'Originally from the tropics, Exeggutor''s heads grow larger with exposure to bright sunlight. It is said that when the heads fall, they group to form an Exeggcute.', '1', NULL, '0103_Exeggutor'),
(104, 'CUBONE', 'Cubone', 'GROUND', NULL, 50, 50, 95, 40, 50, 35, 'Female50Percent', 'Medium', 64, 190, 50, 'ROCKHEAD', 'LIGHTNINGROD', 'BATTLEARMOR', 'Monster', 5120, 0.4, 6.5, 'Brown', 'BipedalTail', 'Mountain', 'Lonely', 'It pines for the mother it will never see again. Seeing a likeness of its mother in the full moon, it cries. The stains on the skull it wears are from its tears.', '1', 'MAROWAK,Level,28', '0104_Cubone'),
(105, 'MAROWAK', 'Marowak', 'GROUND', NULL, 60, 80, 110, 50, 80, 45, 'Female50Percent', 'Medium', 149, 75, 50, 'ROCKHEAD', 'LIGHTNINGROD', 'BATTLEARMOR', 'Monster', 5120, 1.0, 45.0, 'Brown', 'BipedalTail', 'Mountain', 'Bone Keeper', 'A Marowak is the evolved form of a Cubone that has grown tough by overcoming the grief of losing its mother. Its tempered and hardened spirit is not easily broken.', '1', NULL, '0105_Marowak'),
(106, 'HITMONLEE', 'Hitmonlee', 'FIGHTING', NULL, 50, 120, 53, 35, 110, 87, 'AlwaysMale', 'Medium', 159, 45, 50, 'LIMBER', 'RECKLESS', 'UNBURDEN', 'Humanlike', 6400, 1.5, 49.8, 'Brown', 'Bipedal', 'Urban', 'Kicking', 'Its legs freely stretch and contract. Using these springlike limbs, it bowls over foes with devastating kicks. After battle, it rubs down its tired legs.', '1', NULL, '0106_Hitmonlee'),
(107, 'HITMONCHAN', 'Hitmonchan', 'FIGHTING', NULL, 50, 105, 79, 35, 110, 76, 'AlwaysMale', 'Medium', 159, 45, 50, 'KEENEYE', 'IRONFIST', 'INNERFOCUS', 'Humanlike', 6400, 1.4, 50.2, 'Brown', 'Bipedal', 'Urban', 'Punching', 'A Hitmonchan is said to possess the spirit of a boxer who aimed to become the world champion. Having an indomitable spirit means that it will never give up.', '1', NULL, '0107_Hitmonchan'),
(108, 'LICKITUNG', 'Lickitung', 'NORMAL', NULL, 90, 55, 75, 60, 75, 30, 'Female50Percent', 'Medium', 77, 45, 50, 'OWNTEMPO', 'OBLIVIOUS', 'CLOUDNINE', 'Monster', 5120, 1.2, 65.5, 'Pink', 'BipedalTail', 'Grassland', 'Licking', 'Whenever it sees something unfamiliar, it always licks the object because it memorizes things by texture and taste. It is somewhat put off by sour things.', '1', 'LICKILICKY,HasMove,ROLLOUT', '0108_Lickitung'),
(109, 'KOFFING', 'Koffing', 'POISON', NULL, 40, 65, 95, 60, 45, 35, 'Female50Percent', 'Medium', 68, 190, 50, 'LEVITATE', 'NEUTRALIZINGGAS', 'STENCH', 'Amorphous', 5120, 0.6, 1.0, 'Purple', 'Head', 'Urban', 'Poison Gas', 'Getting up close to a Koffing will give you a chance to observe, through its thin skin, the toxic gases swirling inside. It blows up at the slightest stimulation.', '1', 'WEEZING,Level,35', '0109_Koffing'),
(110, 'WEEZING', 'Weezing', 'POISON', NULL, 65, 90, 120, 85, 70, 60, 'Female50Percent', 'Medium', 172, 60, 50, 'LEVITATE', 'NEUTRALIZINGGAS', 'STENCH', 'Amorphous', 5120, 1.2, 9.5, 'Purple', 'MultiBody', 'Urban', 'Poison Gas', 'By diluting its toxic gases with a special process, the highest grade of perfume can be made. To Weezing, gases emanating from garbage are the ultimate feast.', '1', NULL, '0110_Weezing'),
(111, 'RHYHORN', 'Rhyhorn', 'GROUND', 'ROCK', 80, 85, 95, 30, 30, 25, 'Female50Percent', 'Slow', 69, 120, 50, 'LIGHTNINGROD', 'ROCKHEAD', 'RECKLESS', 'Monster,Field', 5120, 1.0, 115.0, 'Gray', 'Quadruped', 'RoughTerrain', 'Spikes', 'Once it starts running, it doesn''t stop. Its tiny brain makes it so stupid that it can''t remember why it started running in the first place.', '1', 'RHYDON,Level,42', '0111_Rhyhorn'),
(112, 'RHYDON', 'Rhydon', 'GROUND', 'ROCK', 105, 130, 120, 45, 45, 40, 'Female50Percent', 'Slow', 170, 60, 50, 'LIGHTNINGROD', 'ROCKHEAD', 'RECKLESS', 'Monster,Field', 5120, 1.9, 120.0, 'Gray', 'BipedalTail', 'RoughTerrain', 'Drill', 'Its horn, which rotates like a drill, destroys tall buildings with one strike. It stands on its hind legs, and its brain is well developed.', '1', 'RHYPERIOR,TradeItem,PROTECTOR', '0112_Rhydon'),
(113, 'CHANSEY', 'Chansey', 'NORMAL', NULL, 250, 5, 5, 35, 105, 50, 'AlwaysFemale', 'Fast', 395, 30, 140, 'NATURALCURE', 'SERENEGRACE', 'HEALER', 'Fairy', 10240, 1.1, 34.6, 'Pink', 'BipedalTail', 'Urban', 'Egg', 'Chansey lay nutritionally excellent eggs every day. The eggs are so delicious, they are eagerly devoured by even those who have lost their appetite.', '1', 'BLISSEY,Happiness,', '0113_Chansey'),
(114, 'TANGELA', 'Tangela', 'GRASS', NULL, 65, 55, 115, 100, 40, 60, 'Female50Percent', 'Medium', 87, 45, 50, 'CHLOROPHYLL', 'LEAFGUARD', 'REGENERATOR', 'Grass', 5120, 1.0, 35.0, 'Blue', 'HeadLegs', 'Grassland', 'Vine', 'Its vines snap off easily and painlessly if they are grabbed, allowing it to make a quick getaway. The lost vines are replaced by new growth the very next day.', '1', 'TANGROWTH,HasMove,ANCIENTPOWER', '0114_Tangela'),
(115, 'KANGASKHAN', 'Kangaskhan', 'NORMAL', NULL, 105, 95, 80, 40, 80, 90, 'AlwaysFemale', 'Medium', 172, 45, 50, 'EARLYBIRD', 'SCRAPPY', 'INNERFOCUS', 'Monster', 5120, 2.2, 80.0, 'Brown', 'BipedalTail', 'Grassland', 'Parent', 'If you come across a young Kangaskhan playing by itself, never try to catch it. The baby''s parent is sure to be in the area, and it will become violently enraged.', '1', NULL, '0115_Kangaskhan'),
(116, 'HORSEA', 'Horsea', 'WATER', NULL, 30, 40, 70, 70, 25, 60, 'Female50Percent', 'Medium', 59, 225, 50, 'SWIFTSWIM', 'SNIPER', 'DAMP', 'Water1,Dragon', 5120, 0.4, 8.0, 'Blue', 'HeadBase', 'Sea', 'Dragon', 'By cleverly flicking the fins on its back side to side, it moves in any direction while facing forward. It spits ink to escape if it senses danger.', '1', 'SEADRA,Level,32', '0116_Horsea'),
(117, 'SEADRA', 'Seadra', 'WATER', NULL, 55, 65, 95, 95, 45, 85, 'Female50Percent', 'Medium', 154, 75, 50, 'POISONPOINT', 'SNIPER', 'DAMP', 'Water1,Dragon', 5120, 1.2, 25.0, 'Blue', 'HeadBase', 'Sea', 'Dragon', 'The poisonous barbs all over its body are highly valued as ingredients for making traditional herbal medicine. It shows no mercy to anything approaching its nest.', '1', 'KINGDRA,TradeItem,DRAGONSCALE', '0117_Seadra'),
(118, 'GOLDEEN', 'Goldeen', 'WATER', NULL, 45, 67, 60, 35, 50, 63, 'Female50Percent', 'Medium', 64, 225, 50, 'SWIFTSWIM', 'WATERVEIL', 'LIGHTNINGROD', 'Water2', 5120, 0.6, 15.0, 'Red', 'Finned', 'WatersEdge', 'Goldfish', 'In the springtime, schools of Goldeen can be seen swimming up falls and rivers. It metes out staggering damage with its single horn.', '1', 'SEAKING,Level,33', '0118_Goldeen'),
(119, 'SEAKING', 'Seaking', 'WATER', NULL, 80, 92, 65, 65, 80, 68, 'Female50Percent', 'Medium', 158, 60, 50, 'SWIFTSWIM', 'WATERVEIL', 'LIGHTNINGROD', 'Water2', 5120, 1.3, 39.0, 'Red', 'Finned', 'WatersEdge', 'Goldfish', 'It punches holes in boulders on stream- beds. This is a clever innovation that prevents its eggs from being attacked or washed away by the current.', '1', NULL, '0119_Seaking'),
(120, 'STARYU', 'Staryu', 'WATER', NULL, 30, 45, 55, 70, 55, 85, 'Genderless', 'Slow', 68, 225, 50, 'ILLUMINATE', 'NATURALCURE', 'ANALYTIC', 'Water3', 5120, 0.8, 34.5, 'Brown', 'HeadBase', 'Sea', 'Star Shape', 'It gathers with others in the night and makes its red core glow on and off with the twinkling stars. It can regenerate limbs if they are severed from its body.', '1', 'STARMIE,Item,WATERSTONE', '0120_Staryu'),
(121, 'STARMIE', 'Starmie', 'WATER', 'PSYCHIC', 60, 75, 85, 100, 85, 115, 'Genderless', 'Slow', 182, 60, 50, 'ILLUMINATE', 'NATURALCURE', 'ANALYTIC', 'Water3', 5120, 1.1, 80.0, 'Purple', 'HeadBase', 'Sea', 'Mysterious', 'People in ancient times imagined that Starmie were transformed from the reflections of stars that twinkled on gentle waves at night.', '1', NULL, '0121_Starmie'),
(122, 'MRMIME', 'Mr. Mime', 'PSYCHIC', 'FAIRY', 40, 45, 65, 100, 120, 90, 'Female50Percent', 'Medium', 161, 45, 50, 'SOUNDPROOF', 'FILTER', 'TECHNICIAN', 'Humanlike', 6400, 1.3, 54.5, 'Pink', 'Bipedal', 'Urban', 'Barrier', 'A Mr. Mime is a master of pantomime. It can convince others that something unseeable actually exists. Once believed, the imaginary object does become real.', '1', 'MRRIME,None,', '0122_Mr_Mime'),
(123, 'SCYTHER', 'Scyther', 'BUG', 'FLYING', 70, 110, 80, 55, 80, 105, 'Female50Percent', 'Medium', 100, 45, 50, 'SWARM', 'TECHNICIAN', 'STEADFAST', 'Bug', 6400, 1.5, 56.0, 'Green', 'MultiWinged', 'Grassland', 'Mantis', 'Its blindingly fast speed adds to the sharpness of its twin forearm scythes. The scythes can slice through thick logs in one wicked stroke.', '1', 'SCIZOR,TradeItem,METALCOAT', '0123_Scyther'),
(124, 'JYNX', 'Jynx', 'ICE', 'PSYCHIC', 65, 50, 35, 115, 95, 95, 'AlwaysFemale', 'Medium', 159, 45, 50, 'OBLIVIOUS', 'FOREWARN', 'DRYSKIN', 'Humanlike', 6400, 1.4, 40.6, 'Red', 'Bipedal', 'Urban', 'Human Shape', 'A Jynx sashays rhythmically as if it were dancing. Its motions are so bouncingly alluring, people seeing it are compelled to shake their hips without noticing.', '1', NULL, '0124_Jynx'),
(125, 'ELECTABUZZ', 'Electabuzz', 'ELECTRIC', NULL, 65, 83, 57, 95, 85, 105, 'Female25Percent', 'Medium', 172, 45, 50, 'STATIC', NULL, 'VITALSPIRIT', 'Humanlike', 6400, 1.1, 30.0, 'Yellow', 'BipedalTail', 'Grassland', 'Electric', 'When a storm approaches, it competes with others to scale heights that are likely to be stricken by lightning. Some towns use Electabuzz as lightning rods.', '1', 'ELECTIVIRE,TradeItem,ELECTIRIZER', '0125_Electabuzz'),
(126, 'MAGMAR', 'Magmar', 'FIRE', NULL, 65, 95, 57, 100, 85, 93, 'Female25Percent', 'Medium', 173, 45, 50, 'FLAMEBODY', NULL, 'VITALSPIRIT', 'Humanlike', 6400, 1.3, 44.5, 'Red', 'BipedalTail', 'Mountain', 'Spitfire', 'In battle, it blows out intense flames from all over its body to intimidate its foe. These fiery bursts create heat waves that ignite grass and trees.', '1', 'MAGMORTAR,TradeItem,MAGMARIZER', '0126_Magmar'),
(127, 'PINSIR', 'Pinsir', 'BUG', NULL, 65, 125, 100, 55, 70, 85, 'Female50Percent', 'Slow', 175, 45, 50, 'HYPERCUTTER', 'MOLDBREAKER', 'MOXIE', 'Bug', 6400, 1.5, 55.0, 'Brown', 'Bipedal', 'Forest', 'Stag Beetle', 'Their pincers are strong enough to shatter thick logs. Because they dislike cold, Pinsir burrow and sleep under the ground on chilly nights.', '1', NULL, '0127_Pinsir'),
(128, 'TAUROS', 'Tauros', 'NORMAL', NULL, 75, 100, 95, 40, 70, 110, 'AlwaysMale', 'Slow', 172, 45, 50, 'INTIMIDATE', 'ANGERPOINT', 'SHEERFORCE', 'Field', 5120, 1.4, 88.4, 'Brown', 'Quadruped', 'Grassland', 'Wild Bull', 'It is not satisfied unless it is rampaging at all times. If there is no opponent for Tauros to battle, it will charge at thick trees and knock them down to calm itself.', '1', NULL, '0128_Tauros'),
(129, 'MAGIKARP', 'Magikarp', 'WATER', NULL, 20, 10, 55, 15, 20, 80, 'Female50Percent', 'Slow', 40, 255, 50, 'SWIFTSWIM', NULL, 'RATTLED', 'Water2,Dragon', 1280, 0.9, 10.0, 'Red', 'Finned', 'WatersEdge', 'Fish', 'Its swimming muscles are weak, so it is easily washed away by currents. In places where water pools, you can see many Magikarp deposited there by the flow.', '1', 'GYARADOS,Level,20', '0129_Magikarp'),
