(134, 'VAPOREON', 'Vaporeon', 'WATER', NULL, 130, 65, 60, 110, 95, 65, 'FemaleOneEighth', 'Medium', 184, 45, 50, 'WATERABSORB', NULL, 'HYDRATION', 'Field', 8960, 1.0, 29.0, 'Blue', 'Quadruped', 'Urban', 'Bubble Jet', 'Vaporeon underwent a spontaneous mutation and grew fins and gills that allow them to live underwater. They have the ability to freely control water.', '1', NULL, '0134_Vaporeon'),
