(142, 'AERODACTYL', 'Aerodactyl', 'ROCK', 'FLYING', 80, 105, 65, 60, 75, 130, 'FemaleOneEighth', 'Slow', 180, 45, 50, 'ROCKHEAD', 'PRESSURE', 'UNNERVE', 'Flying', 8960, 1.8, 59.0, 'Purple', 'Winged', 'Mountain', 'Fossil', 'Aerodactyl is a Pokémon from the age of dinosaurs. It was regenerated from DNA extracted from amber. It is imagined to have been the king of the skies.', '1', NULL, '0142_Aerodactyl'),
(143, 'SNORLAX', 'Snorlax', 'NORMAL', NULL, 160, 110, 65, 65, 110, 30, 'FemaleOneEighth', 'Slow', 189, 25, 50, 'IMMUNITY', 'THICKFAT', 'GLUTTONY', 'Monster', 10240, 2.1, 460.0, 'Black', 'Bipedal', 'Mountain', 'Sleeping', 'Snorlax''s typical day consists of nothing more than eating and sleeping. It is such a docile Pokémon that there are children who use its big belly as a place to play.', '1', NULL, '0143_Snorlax'),
