(152, 'CHIKORITA', 'Chikorita', 'GRASS', NULL, 45, 49, 65, 49, 65, 45, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'OVERGROW', NULL, 'LEAFGUARD', 'Monster,Grass', 5120, 0.9, 6.4, 'Green', 'Quadruped', 'Grassland', 'Leaf', 'It waves its leaf around to keep foes at bay. However, a sweet fragrance also wafts from the leaf, creating a friendly atmosphere that becalms the battlers.', '2', 'BAYLEEF,Level,16', '0152_Chikorita'),
(153, 'BAYLEEF', 'Bayleef', 'GRASS', NULL, 60, 62, 80, 63, 80, 60, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'OVERGROW', NULL, 'LEAFGUARD', 'Monster,Grass', 5120, 1.2, 15.8, 'Green', 'Quadruped', 'Grassland', 'Leaf', 'A Bayleef''s neck is ringed by curled-up leaves. Inside each leaf is a small tree shoot. The fragrance of this shoot makes people peppy.', '2', 'MEGANIUM,Level,32', '0153_Bayleef'),
(154, 'MEGANIUM', 'Meganium', 'GRASS', NULL, 80, 82, 100, 83, 100, 80, 'FemaleOneEighth', 'Parabolic', 263, 45, 50, 'OVERGROW', NULL, 'LEAFGUARD', 'Monster,Grass', 5120, 1.8, 100.5, 'Green', 'Quadruped', 'Grassland', 'Herb', 'The fragrance of a Meganium''s flower soothes and calms emotions. In battle, it gives off more of its becalming scent to blunt the foe''s fighting spirit.', '2', NULL, '0154_Meganium'),
(155, 'CYNDAQUIL', 'Cyndaquil', 'FIRE', NULL, 39, 52, 43, 60, 50, 65, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'FLASHFIRE', 'Field', 5120, 0.5, 7.9, 'Yellow', 'Bipedal', 'Grassland', 'Fire Mouse', 'It flares flames from its back to protect itself. The fire burns vigorously if the Pokémon is angry. When it is tired, it sputters with incomplete combustion.', '2', 'QUILAVA,Level,14', '0155_Cyndaquil'),
(156, 'QUILAVA', 'Quilava', 'FIRE', NULL, 58, 64, 58, 80, 65, 80, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'BLAZE', NULL, 'FLASHFIRE', 'Field', 5120, 0.9, 19.0, 'Yellow', 'Quadruped', 'Grassland', 'Volcano', 'It intimidates foes with intense gusts of flames and superheated air. Its quick nimbleness lets it dodge attacks even while scorching an enemy.', '2', 'TYPHLOSION,Level,36', '0156_Quilava'),
(157, 'TYPHLOSION', 'Typhlosion', 'FIRE', NULL, 78, 84, 78, 109, 85, 100, 'FemaleOneEighth', 'Parabolic', 267, 45, 50, 'BLAZE', NULL, 'FLASHFIRE', 'Field', 5120, 1.7, 79.5, 'Yellow', 'Quadruped', 'Grassland', 'Volcano', 'It can hide behind a shimmering heat haze that it creates using its intense flames. Typhlosion create blazing explosive blasts that burn everything to cinders.', '2', NULL, '0157_Typhlosion'),
(158, 'TOTODILE', 'Totodile', 'WATER', NULL, 50, 65, 64, 44, 48, 43, 'FemaleOneEighth', 'Parabolic', 63, 45, 50, 'TORRENT', NULL, 'SHEERFORCE', 'Monster,Water1', 5120, 0.6, 9.5, 'Blue', 'BipedalTail', 'WatersEdge', 'Big Jaw', 'Despite its small body, Totodile''s jaws are very powerful. While it may think it is just playfully nipping, its bite has enough strength to cause serious injury.', '2', 'CROCONAW,Level,18', '0158_Totodile'),
(159, 'CROCONAW', 'Croconaw', 'WATER', NULL, 65, 80, 80, 59, 63, 58, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'TORRENT', NULL, 'SHEERFORCE', 'Monster,Water1', 5120, 1.1, 25.0, 'Blue', 'BipedalTail', 'WatersEdge', 'Big Jaw', 'Once its jaws clamp down on its foe, it will absolutely not let go. Because the tips of its fangs are forked back like fishhooks, they become irremovably embedded.', '2', 'FERALIGATR,Level,30', '0159_Croconaw'),
(160, 'FERALIGATR', 'Feraligatr', 'WATER', NULL, 85, 105, 100, 79, 83, 78, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'SHEERFORCE', 'Monster,Water1', 5120, 2.3, 88.8, 'Blue', 'BipedalTail', 'WatersEdge', 'Big Jaw', 'It opens its huge mouth to intimidate enemies. In battle, it runs using its thick and powerful hind legs to charge the foe with incredible speed.', '2', NULL, '0160_Feraligatr');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(161, 'SENTRET', 'Sentret', 'NORMAL', NULL, 35, 46, 34, 35, 45, 20, 'Female50Percent', 'Medium', 43, 255, 50, 'RUNAWAY', 'KEENEYE', 'FRISK', 'Field', 3840, 0.8, 6.0, 'Brown', 'Quadruped', 'Grassland', 'Scout', 'They take turns standing guard when it is time to sleep. The sentry awakens the others if it senses danger. If one gets separated, it turns sleepless with fear.', '2', 'FURRET,Level,15', '0161_Sentret'),
(162, 'FURRET', 'Furret', 'NORMAL', NULL, 85, 76, 64, 45, 55, 90, 'Female50Percent', 'Medium', 145, 90, 50, 'RUNAWAY', 'KEENEYE', 'FRISK', 'Field', 3840, 1.8, 32.5, 'Brown', 'Quadruped', 'Grassland', 'Long Body', 'A Furret has a very slim build. When under attack, it can squirm through narrow spaces and get away. In spite of its short limbs, it is very nimble and fleet.', '2', NULL, '0162_Furret'),
(163, 'HOOTHOOT', 'Hoothoot', 'NORMAL', 'FLYING', 60, 30, 30, 36, 56, 50, 'Female50Percent', 'Medium', 52, 255, 50, 'INSOMNIA', 'KEENEYE', 'TINTEDLENS', 'Flying', 3840, 0.7, 21.2, 'Brown', 'Winged', 'Forest', 'Owl', 'It has an internal organ that senses the earth''s rotation. Using this special organ, a Hoothoot begins hooting at precisely the same time every day.', '2', 'NOCTOWL,Level,20', '0163_Hoothoot'),
(164, 'NOCTOWL', 'Noctowl', 'NORMAL', 'FLYING', 100, 50, 50, 86, 96, 70, 'Female50Percent', 'Medium', 158, 90, 50, 'INSOMNIA', 'KEENEYE', 'TINTEDLENS', 'Flying', 3840, 1.6, 40.8, 'Brown', 'Winged', 'Forest', 'Owl', 'It unfailingly catches prey in darkness. Noctowl owe their success to superior vision that allows them to see in minimal light, and to their supple and silent wings.', '2', NULL, '0164_Noctowl'),
(165, 'LEDYBA', 'Ledyba', 'BUG', 'FLYING', 40, 20, 30, 40, 80, 55, 'Female50Percent', 'Fast', 53, 255, 50, 'SWARM', 'EARLYBIRD', 'RATTLED', 'Bug', 3840, 1.0, 10.8, 'Red', 'Winged', 'Forest', 'Five Star', 'Ledyba communicate using a fluid that they secrete from where the legs join the body. They are said to convey feelings to others by altering the fluid''s scent.', '2', 'LEDIAN,Level,18', '0165_Ledyba'),
(166, 'LEDIAN', 'Ledian', 'BUG', 'FLYING', 55, 35, 50, 55, 110, 85, 'Female50Percent', 'Fast', 137, 90, 50, 'SWARM', 'EARLYBIRD', 'IRONFIST', 'Bug', 3840, 1.4, 35.6, 'Red', 'Winged', 'Forest', 'Five Star', 'It is said that in lands with clean air, where the stars fill the sky, there live many Ledian. For good reason, they use the light of the stars as energy.', '2', NULL, '0166_Ledian'),
(167, 'SPINARAK', 'Spinarak', 'BUG', 'POISON', 40, 60, 40, 40, 40, 30, 'Female50Percent', 'Fast', 50, 255, 50, 'SWARM', 'INSOMNIA', 'SNIPER', 'Bug', 3840, 0.5, 8.5, 'Green', 'Insectoid', 'Forest', 'String Spit', 'The web it spins can be considered its second nervous system. It is said that a Spinarak determines its prey by the tiny vibrations it feels through the web.', '2', 'ARIADOS,Level,22', '0167_Spinarak'),
(168, 'ARIADOS', 'Ariados', 'BUG', 'POISON', 70, 90, 70, 60, 70, 40, 'Female50Percent', 'Fast', 140, 90, 50, 'SWARM', 'INSOMNIA', 'SNIPER', 'Bug', 3840, 1.1, 33.5, 'Red', 'Insectoid', 'Forest', 'Long Leg', 'Its feet are tipped with tiny hooked claws that enable it to scuttle on ceilings and vertical walls. It constricts its foe with thin and strong silk webbing.', '2', NULL, '0168_Ariados'),
(169, 'CROBAT', 'Crobat', 'POISON', 'FLYING', 85, 90, 80, 70, 80, 130, 'Female50Percent', 'Medium', 268, 90, 50, 'INNERFOCUS', NULL, 'INFILTRATOR', 'Flying', 3840, 1.8, 75.0, 'Purple', 'MultiWinged', 'Cave', 'Bat', 'Over the course of evolution, its hind legs turned into wings. By alternately resting its front and rear wings, it can fly all day without having to stop.', '2', NULL, '0169_Crobat'),
(170, 'CHINCHOU', 'Chinchou', 'WATER', 'ELECTRIC', 75, 38, 38, 56, 56, 67, 'Female50Percent', 'Slow', 66, 190, 50, 'VOLTABSORB', 'ILLUMINATE', 'WATERABSORB', 'Water2', 5120, 0.5, 12.0, 'Blue', 'Finned', 'Sea', 'Angler', 'When it senses danger, it discharges positive and negative electricity from its two antennae. It lives in depths beyond sunlight''s reach.', '2', 'LANTURN,Level,27', '0170_Chinchou'),
(171, 'LANTURN', 'Lanturn', 'WATER', 'ELECTRIC', 125, 58, 58, 76, 76, 67, 'Female50Percent', 'Slow', 161, 75, 50, 'VOLTABSORB', 'ILLUMINATE', 'WATERABSORB', 'Water2', 5120, 1.2, 22.5, 'Blue', 'Finned', 'Sea', 'Light', 'The light-emitting orbs on its back are very bright. They are formed from a part of its dorsal fin. This Pokémon illuminates the inky darkness of deep seas.', '2', NULL, '0171_Lanturn'),
(172, 'PICHU', 'Pichu', 'ELECTRIC', NULL, 20, 40, 15, 35, 35, 60, 'Female50Percent', 'Medium', 41, 190, 50, 'STATIC', NULL, 'LIGHTNINGROD', 'Undiscovered', 2560, 0.3, 2.0, 'Yellow', 'Quadruped', 'Forest', 'Tiny Mouse', 'It is still inept at retaining electricity. When it is startled, it discharges power accidentally. It gets better at holding power as it grows older.', '2', 'PIKACHU,Happiness,', '0172_Pichu'),
(173, 'CLEFFA', 'Cleffa', 'FAIRY', NULL, 50, 25, 28, 45, 55, 15, 'Female75Percent', 'Fast', 44, 150, 140, 'CUTECHARM', 'MAGICGUARD', 'FRIENDGUARD', 'Undiscovered', 2560, 0.3, 3.0, 'Pink', 'BipedalTail', 'Mountain', 'Star Shape', 'On nights with many shooting stars, Cleffa can be seen dancing in a ring. They dance until daybreak, when they quench their thirst with the morning dew.', '2', 'CLEFAIRY,Happiness,', '0173_Cleffa'),
(174, 'IGGLYBUFF', 'Igglybuff', 'NORMAL', 'FAIRY', 90, 30, 15, 40, 20, 15, 'Female75Percent', 'Fast', 42, 170, 50, 'CUTECHARM', 'COMPETITIVE', 'FRIENDGUARD', 'Undiscovered', 2560, 0.3, 1.0, 'Pink', 'Bipedal', 'Grassland', 'Balloon', 'Its soft and pliable body is very bouncy. When it sings continuously with all its might, its body steadily turns a deepening pink color.', '2', 'JIGGLYPUFF,Happiness,', '0174_Igglybuff'),
(175, 'TOGEPI', 'Togepi', 'FAIRY', NULL, 35, 20, 65, 40, 65, 20, 'FemaleOneEighth', 'Fast', 49, 190, 50, 'HUSTLE', 'SERENEGRACE', 'SUPERLUCK', 'Undiscovered', 2560, 0.3, 1.5, 'White', 'Bipedal', 'Forest', 'Spike Ball', 'As its energy, it uses the feelings of compassion and pleasure exuded by people and Pokémon. It stores up happy feelings in its shell, then shares them out.', '2', 'TOGETIC,Happiness,', '0175_Togepi'),
(176, 'TOGETIC', 'Togetic', 'FAIRY', 'FLYING', 55, 40, 85, 80, 105, 40, 'FemaleOneEighth', 'Fast', 142, 75, 50, 'HUSTLE', 'SERENEGRACE', 'SUPERLUCK', 'Flying,Fairy', 2560, 0.6, 3.2, 'White', 'Bipedal', 'Forest', 'Happiness', 'It is said to be a Pokémon that brings good fortune. When it spots someone who is pure of heart, a Togetic appears and shares its happiness with that person.', '2', 'TOGEKISS,Item,SHINYSTONE', '0176_Togetic'),
(177, 'NATU', 'Natu', 'PSYCHIC', 'FLYING', 40, 50, 45, 70, 45, 70, 'Female50Percent', 'Medium', 64, 190, 50, 'SYNCHRONIZE', 'EARLYBIRD', 'MAGICBOUNCE', 'Flying', 5120, 0.2, 2.0, 'Green', 'Winged', 'Forest', 'Tiny Bird', 'It runs up short trees that grow on the savanna to peck at new shoots. A Natu''s eyes look as if they are always observing something.', '2', 'XATU,Level,25', '0177_Natu'),
(178, 'XATU', 'Xatu', 'PSYCHIC', 'FLYING', 65, 75, 70, 95, 70, 95, 'Female50Percent', 'Medium', 165, 75, 50, 'SYNCHRONIZE', 'EARLYBIRD', 'MAGICBOUNCE', 'Flying', 5120, 1.5, 15.0, 'Green', 'Winged', 'Forest', 'Mystic', 'It has the enigmatic power of foreseeing the future. Some people in different lands have long believed that Xatu are emissaries from another world.', '2', NULL, '0178_Xatu'),
(179, 'MAREEP', 'Mareep', 'ELECTRIC', NULL, 55, 40, 40, 65, 45, 35, 'Female50Percent', 'Parabolic', 56, 235, 50, 'STATIC', NULL, 'PLUS', 'Monster,Field', 5120, 0.6, 7.8, 'White', 'Quadruped', 'Grassland', 'Wool', 'Its fluffy wool rubs together and builds a static charge. The more energy is charged, the more brightly the lightbulb at the tip of its tail glows.', '2', 'FLAAFFY,Level,15', '0179_Mareep'),
(180, 'FLAAFFY', 'Flaaffy', 'ELECTRIC', NULL, 70, 55, 55, 80, 60, 45, 'Female50Percent', 'Parabolic', 128, 120, 50, 'STATIC', NULL, 'PLUS', 'Monster,Field', 5120, 0.8, 13.3, 'Pink', 'BipedalTail', 'Grassland', 'Wool', 'Its fleece quality changes to generate strong static electricity with a small amount of wool. The bare, slick parts of its hide are shielded against electricity.', '2', 'AMPHAROS,Level,30', '0180_Flaaffy'),
(181, 'AMPHAROS', 'Ampharos', 'ELECTRIC', NULL, 90, 75, 85, 115, 90, 55, 'Female50Percent', 'Parabolic', 255, 45, 50, 'STATIC', NULL, 'PLUS', 'Monster,Field', 5120, 1.4, 61.5, 'Yellow', 'BipedalTail', 'Grassland', 'Light', 'It gives off so much light that it can be seen even from space. People in the old days used its light to send signals back and forth with others far away.', '2', NULL, '0181_Ampharos'),
(182, 'BELLOSSOM', 'Bellossom', 'GRASS', NULL, 75, 80, 95, 90, 100, 50, 'Female50Percent', 'Parabolic', 245, 45, 50, 'CHLOROPHYLL', NULL, 'HEALER', 'Grass', 5120, 0.4, 5.8, 'Green', 'Bipedal', 'Grassland', 'Flower', 'Its flower petals deepen in color through exposure to sunlight. When cloudy weather persists, it does a dance that is thought to be a sun-summoning ritual.', '2', NULL, '0182_Bellossom'),
(183, 'MARILL', 'Marill', 'WATER', 'FAIRY', 70, 20, 50, 20, 50, 40, 'Female50Percent', 'Fast', 88, 190, 50, 'THICKFAT', 'HUGEPOWER', 'SAPSIPPER', 'Water1,Fairy', 2560, 0.4, 8.5, 'Blue', 'BipedalTail', 'WatersEdge', 'Aqua Mouse', 'Its body is covered with water-repellent fur. Because of the fur, it can swim through water at high speed without being slowed by the water''s resistance.', '2', 'AZUMARILL,Level,18', '0183_Marill'),
(184, 'AZUMARILL', 'Azumarill', 'WATER', 'FAIRY', 100, 50, 80, 60, 80, 50, 'Female50Percent', 'Fast', 210, 75, 50, 'THICKFAT', 'HUGEPOWER', 'SAPSIPPER', 'Water1,Fairy', 2560, 0.8, 28.5, 'Blue', 'BipedalTail', 'WatersEdge', 'Aqua Rabbit', 'It lives in water virtually all day long. Its body color and pattern act as camouflage that makes it tough for enemies to spot in water.', '2', NULL, '0184_Azumarill'),
(185, 'SUDOWOODO', 'Sudowoodo', 'ROCK', NULL, 70, 100, 115, 30, 65, 30, 'Female50Percent', 'Medium', 144, 65, 50, 'STURDY', 'ROCKHEAD', 'RATTLED', 'Mineral', 5120, 1.2, 38.0, 'Brown', 'Bipedal', 'Forest', 'Imitation', 'It mimics a tree to avoid being attacked by enemies. But since its forelegs remain green throughout the year, it is easily identified as a fake in the winter.', '2', NULL, '0185_Sudowoodo'),
(186, 'POLITOED', 'Politoed', 'WATER', NULL, 90, 75, 75, 90, 100, 70, 'Female50Percent', 'Parabolic', 250, 45, 50, 'WATERABSORB', 'DAMP', 'DRIZZLE', 'Water1', 5120, 1.1, 33.9, 'Green', 'Bipedal', 'WatersEdge', 'Frog', 'The curled hair on its head proves its status as a king. It is said that the longer and curlier the hair, the more respect it earns from its peers.', '2', NULL, '0186_Politoed'),
(187, 'HOPPIP', 'Hoppip', 'GRASS', 'FLYING', 35, 35, 40, 35, 55, 50, 'Female50Percent', 'Parabolic', 50, 255, 50, 'CHLOROPHYLL', 'LEAFGUARD', 'INFILTRATOR', 'Fairy,Grass', 5120, 0.4, 0.5, 'Pink', 'BipedalTail', 'Grassland', 'Cottonweed', 'This Pokémon drifts and floats with the wind. If it senses the approach of strong winds, a Hoppip links leaves with others to prepare against being blown away.', '2', 'SKIPLOOM,Level,18', '0187_Hoppip'),
(188, 'SKIPLOOM', 'Skiploom', 'GRASS', 'FLYING', 55, 45, 50, 45, 65, 80, 'Female50Percent', 'Parabolic', 119, 120, 50, 'CHLOROPHYLL', 'LEAFGUARD', 'INFILTRATOR', 'Fairy,Grass', 5120, 0.6, 1.0, 'Green', 'BipedalTail', 'Grassland', 'Cottonweed', 'It blossoms when the temperature rises above 64 degrees F. Because its flower''s blooming changes with the temperature, it is sometimes used as a thermometer.', '2', 'JUMPLUFF,Level,27', '0188_Skiploom'),
(189, 'JUMPLUFF', 'Jumpluff', 'GRASS', 'FLYING', 75, 55, 70, 55, 95, 110, 'Female50Percent', 'Parabolic', 230, 45, 50, 'CHLOROPHYLL', 'LEAFGUARD', 'INFILTRATOR', 'Fairy,Grass', 5120, 0.8, 3.0, 'Blue', 'BipedalTail', 'Grassland', 'Cottonweed', 'Jumpluff ride warm southern winds to cross the sea and fly to foreign lands. This Pokémon lands when it encounters cold air while it is floating.', '2', NULL, '0189_Jumpluff'),
(190, 'AIPOM', 'Aipom', 'NORMAL', NULL, 55, 70, 55, 40, 55, 85, 'Female50Percent', 'Fast', 72, 45, 50, 'RUNAWAY', 'PICKUP', 'SKILLLINK', 'Field', 5120, 0.8, 11.5, 'Purple', 'BipedalTail', 'Forest', 'Long Tail', 'Its tail ends with a dexterous, handlike appendage. However, because it uses the tail so much, Aipom''s real hands have become rather clumsy.', '2', 'AMBIPOM,HasMove,DOUBLEHIT', '0190_Aipom'),
(191, 'SUNKERN', 'Sunkern', 'GRASS', NULL, 30, 30, 30, 30, 30, 30, 'Female50Percent', 'Parabolic', 36, 235, 50, 'CHLOROPHYLL', 'SOLARPOWER', 'EARLYBIRD', 'Grass', 5120, 0.3, 1.8, 'Yellow', 'Head', 'Grassland', 'Seed', 'Sunkern try to minimize movement to conserve the nutrients they have stored in their bodies for evolution. They will not eat, subsisting only on morning dew.', '2', 'SUNFLORA,Item,SUNSTONE', '0191_Sunkern'),
(192, 'SUNFLORA', 'Sunflora', 'GRASS', NULL, 75, 75, 55, 105, 85, 30, 'Female50Percent', 'Parabolic', 149, 120, 50, 'CHLOROPHYLL', 'SOLARPOWER', 'EARLYBIRD', 'Grass', 5120, 0.8, 8.5, 'Yellow', 'Bipedal', 'Grassland', 'Sun', 'Sunflora convert solar energy into nutrition. They are highly active in the warm daytime but suddenly stop moving as soon as the sun sets.', '2', NULL, '0192_Sunflora'),
(193, 'YANMA', 'Yanma', 'BUG', 'FLYING', 65, 65, 45, 75, 45, 95, 'Female50Percent', 'Medium', 78, 75, 50, 'SPEEDBOOST', 'COMPOUNDEYES', 'FRISK', 'Bug', 5120, 1.2, 38.0, 'Red', 'MultiWinged', 'Forest', 'Clear Wing', 'It can see 360 degrees without moving its eyes. It is a great flier capable of making sudden stops and turning midair to quickly chase down targeted prey.', '2', 'YANMEGA,HasMove,ANCIENTPOWER', '0193_Yanma'),
(194, 'WOOPER', 'Wooper', 'WATER', 'GROUND', 55, 45, 45, 25, 25, 15, 'Female50Percent', 'Medium', 42, 255, 50, 'DAMP', 'WATERABSORB', 'UNAWARE', 'Water1,Field', 5120, 0.4, 8.5, 'Blue', 'HeadLegs', 'WatersEdge', 'Water Fish', 'Wooper usually live in water but come out onto land seeking food occasionally. On land, they coat their bodies with a gooey, toxic film.', '2', 'QUAGSIRE,Level,20', '0194_Wooper'),
(195, 'QUAGSIRE', 'Quagsire', 'WATER', 'GROUND', 95, 85, 85, 65, 65, 35, 'Female50Percent', 'Medium', 151, 90, 50, 'DAMP', 'WATERABSORB', 'UNAWARE', 'Water1,Field', 5120, 1.4, 75.0, 'Blue', 'BipedalTail', 'WatersEdge', 'Water Fish', 'A Quagsire hunts by leaving its mouth wide open in water and waiting for its prey to blunder in. Because it doesn''t move, it does not get very hungry.', '2', NULL, '0195_Quagsire'),
(196, 'ESPEON', 'Espeon', 'PSYCHIC', NULL, 65, 65, 60, 130, 95, 110, 'FemaleOneEighth', 'Medium', 184, 45, 50, 'SYNCHRONIZE', NULL, 'MAGICBOUNCE', 'Field', 8960, 0.9, 26.5, 'Purple', 'Quadruped', 'Urban', 'Sun', 'An Espeon is extremely loyal to any trainer it considers to be worthy. It is said to have developed precognitive powers to protect its trainer from harm.', '2', NULL, '0196_Espeon'),
(197, 'UMBREON', 'Umbreon', 'DARK', NULL, 95, 65, 110, 60, 130, 65, 'FemaleOneEighth', 'Medium', 184, 45, 35, 'SYNCHRONIZE', NULL, 'INNERFOCUS', 'Field', 8960, 1.0, 27.0, 'Black', 'Quadruped', 'Urban', 'Moonlight', 'Umbreon evolved from exposure to the moon''s energy pulses. It lurks in darkness and waits for its foes to move. The rings on its body glow when it leaps to attack.', '2', NULL, '0197_Umbreon'),
(198, 'MURKROW', 'Murkrow', 'DARK', 'FLYING', 60, 85, 42, 85, 42, 91, 'Female50Percent', 'Parabolic', 81, 30, 35, 'INSOMNIA', 'SUPERLUCK', 'PRANKSTER', 'Flying', 5120, 0.5, 2.1, 'Black', 'Winged', 'Forest', 'Darkness', 'Murkrow were feared as the alleged bearers of ill fortune. It shows strong interest in anything that sparkles. It will even try to steal rings from women.', '2', 'HONCHKROW,Item,DUSKSTONE', '0198_Murkrow'),
(199, 'SLOWKING', 'Slowking', 'WATER', 'PSYCHIC', 95, 75, 80, 100, 110, 30, 'Female50Percent', 'Medium', 172, 70, 50, 'OBLIVIOUS', 'OWNTEMPO', 'REGENERATOR', 'Monster,Water1', 5120, 2.0, 79.5, 'Pink', 'BipedalTail', 'WatersEdge', 'Royal', 'It undertakes research every day to solve the mysteries of the world. However, it apparently forgets everything if the Shellder on its head comes off.', '2', NULL, '0199_Slowking'),
(200, 'MISDREAVUS', 'Misdreavus', 'GHOST', NULL, 60, 60, 60, 85, 85, 85, 'Female50Percent', 'Fast', 87, 45, 35, 'LEVITATE', NULL, NULL, 'Amorphous', 6400, 0.7, 1.0, 'Gray', 'Head', 'Cave', 'Screech', 'A Misdreavus frightens people with a creepy, sobbing cry. It apparently uses its red spheres to absorb the fear of foes as its nutrition.', '2', 'MISMAGIUS,Item,DUSKSTONE', '0200_Misdreavus'),
(201, 'UNOWN', 'Unown', 'PSYCHIC', NULL, 48, 72, 48, 72, 48, 48, 'Genderless', 'Medium', 118, 225, 50, 'LEVITATE', NULL, NULL, 'Undiscovered', 10240, 0.5, 5.0, 'Black', 'Head', 'Rare', 'Symbol', 'This Pokémon is shaped like ancient text characters. Although research is ongoing, it is a mystery as to which came first, the ancient writings or the various Unown.', '2', NULL, '0201_Unown'),
(202, 'WOBBUFFET', 'Wobbuffet', 'PSYCHIC', NULL, 190, 33, 58, 33, 58, 33, 'Female50Percent', 'Medium', 142, 45, 50, 'SHADOWTAG', NULL, 'TELEPATHY', 'Amorphous', 5120, 1.3, 28.5, 'Blue', 'HeadBase', 'Cave', 'Patient', 'Usually docile, a Wobbuffet strikes back ferociously if its black tail is attacked. It makes its lair in caves where it waits for nightfall.', '2', NULL, '0202_Wobbuffet'),
(203, 'GIRAFARIG', 'Girafarig', 'NORMAL', 'PSYCHIC', 70, 80, 65, 90, 65, 85, 'Female50Percent', 'Medium', 159, 60, 50, 'INNERFOCUS', 'EARLYBIRD', 'SAPSIPPER', 'Field', 5120, 1.5, 41.5, 'Yellow', 'Quadruped', 'Grassland', 'Long Neck', 'A Girafarig is an herbivore--it eats grass and tree shoots. While it is eating, its tail makes chewing and swallowing motions as if it were also eating.', '2', NULL, '0203_Girafarig'),
(204, 'PINECO', 'Pineco', 'BUG', NULL, 50, 65, 90, 35, 35, 15, 'Female50Percent', 'Medium', 58, 190, 50, 'STURDY', NULL, 'OVERCOAT', 'Bug', 5120, 0.6, 7.2, 'Gray', 'Head', 'Forest', 'Bagworm', 'A Pineco hangs from a tree branch and waits for prey. While eating, if it is disturbed by someone shaking its tree, it falls on the ground and explodes.', '2', 'FORRETRESS,Level,31', '0204_Pineco'),
(205, 'FORRETRESS', 'Forretress', 'BUG', 'STEEL', 75, 90, 140, 60, 60, 40, 'Female50Percent', 'Medium', 163, 75, 50, 'STURDY', NULL, 'OVERCOAT', 'Bug', 5120, 1.2, 125.8, 'Purple', 'Head', 'Forest', 'Bagworm', 'It keeps itself inside its steel shell. The shell is opened when it is catching prey, but it is so quick that the shell''s inside cannot be seen.', '2', NULL, '0205_Forretress'),
(206, 'DUNSPARCE', 'Dunsparce', 'NORMAL', NULL, 100, 70, 70, 65, 65, 45, 'Female50Percent', 'Medium', 145, 190, 50, 'SERENEGRACE', 'RUNAWAY', 'RATTLED', 'Field', 5120, 1.5, 14.0, 'Yellow', 'Serpentine', 'Cave', 'Land Snake', 'Its drill-tipped tail is used to burrow into the ground backwards. This Pokémon is known to make its nest in complex shapes deep under the ground.', '2', NULL, '0206_Dunsparce'),
(207, 'GLIGAR', 'Gligar', 'GROUND', 'FLYING', 65, 75, 105, 35, 65, 85, 'Female50Percent', 'Parabolic', 86, 60, 50, 'HYPERCUTTER', 'SANDVEIL', 'IMMUNITY', 'Bug', 5120, 1.1, 64.8, 'Purple', 'Winged', 'Mountain', 'Fly Scorpion', 'It glides without making a single sound. It grasps the face of its foe using its hind and large front claws, then stabs with its poison barb.', '2', 'GLISCOR,NightHoldItem,RAZORFANG', '0207_Gligar'),
(208, 'STEELIX', 'Steelix', 'STEEL', 'GROUND', 75, 85, 200, 55, 65, 30, 'Female50Percent', 'Medium', 179, 25, 50, 'ROCKHEAD', 'STURDY', 'SHEERFORCE', 'Mineral', 6400, 9.2, 400.0, 'Gray', 'Serpentine', 'Cave', 'Iron Snake', 'Steelix live even further underground than Onix. This Pokémon is known to dig toward the earth''s core, reaching a depth of over six-tenths of a mile underground.', '2', NULL, '0208_Steelix'),
(209, 'SNUBBULL', 'Snubbull', 'FAIRY', NULL, 60, 80, 50, 40, 40, 30, 'Female75Percent', 'Fast', 60, 190, 50, 'INTIMIDATE', 'RUNAWAY', 'RATTLED', 'Field,Fairy', 5120, 0.6, 7.8, 'Pink', 'Bipedal', 'Urban', 'Fairy', 'By baring its fangs and making a scary face, it sends smaller Pokémon scurrying in terror. The Snubbull does seem a little sad at making its foes flee.', '2', 'GRANBULL,Level,23', '0209_Snubbull'),
(210, 'GRANBULL', 'Granbull', 'FAIRY', NULL, 90, 120, 75, 60, 60, 45, 'Female75Percent', 'Fast', 158, 75, 50, 'INTIMIDATE', 'QUICKFEET', 'RATTLED', 'Field,Fairy', 5120, 1.4, 48.7, 'Purple', 'BipedalTail', 'Urban', 'Fairy', 'It has a particularly well-developed lower jaw. The huge fangs are heavy, causing it to tilt its head. Unless it is startled, it will not try to bite.', '2', NULL, '0210_Granbull'),
(211, 'QWILFISH', 'Qwilfish', 'WATER', 'POISON', 65, 95, 85, 55, 55, 85, 'Female50Percent', 'Medium', 88, 45, 50, 'POISONPOINT', 'SWIFTSWIM', 'INTIMIDATE', 'Water2', 5120, 0.5, 3.9, 'Gray', 'Finned', 'Sea', 'Balloon', 'A Qwilfish uses the pressure of water it swallows to shoot toxic quills all at once from all over its body. It finds swimming to be somewhat challenging.', '2', NULL, '0211_Qwilfish'),
(212, 'SCIZOR', 'Scizor', 'BUG', 'STEEL', 70, 130, 100, 55, 80, 65, 'Female50Percent', 'Medium', 175, 25, 50, 'SWARM', 'TECHNICIAN', 'LIGHTMETAL', 'Bug', 6400, 1.8, 118.0, 'Red', 'MultiWinged', 'Grassland', 'Pincer', 'A Scizor has a body with the hardness of steel. It is not easily fazed by ordinary sorts of attacks. It flaps its wings to regulate its body temperature.', '2', NULL, '0212_Scizor'),
(213, 'SHUCKLE', 'Shuckle', 'BUG', 'ROCK', 20, 10, 230, 10, 230, 5, 'Female50Percent', 'Parabolic', 177, 190, 50, 'STURDY', 'GLUTTONY', 'CONTRARY', 'Bug', 5120, 0.6, 20.5, 'Yellow', 'Insectoid', 'Mountain', 'Mold', 'A Shuckle hides under rocks, keeping its body concealed inside its shell while eating stored berries. The berries mix with its body fluids to become a juice.', '2', NULL, '0213_Shuckle'),
(214, 'HERACROSS', 'Heracross', 'BUG', 'FIGHTING', 80, 125, 75, 40, 95, 85, 'Female50Percent', 'Slow', 175, 45, 50, 'SWARM', 'GUTS', 'MOXIE', 'Bug', 6400, 1.5, 54.0, 'Blue', 'Bipedal', 'Forest', 'Single Horn', 'They gather in forests seeking the sweet sap of trees. It is completely clad in a steel-hard shell. It is proud of its horn, which it uses to fling foes.', '2', NULL, '0214_Heracross'),
(215, 'SNEASEL', 'Sneasel', 'DARK', 'ICE', 55, 95, 55, 35, 75, 115, 'Female50Percent', 'Parabolic', 86, 60, 35, 'INNERFOCUS', 'KEENEYE', 'PICKPOCKET', 'Field', 5120, 0.9, 28.0, 'Black', 'BipedalTail', 'Forest', 'Sharp Claw', 'A Sneasel scales trees by punching its hooked claws into the bark. It seeks out unguarded nests and steals eggs for food while the parents are away.', '2', 'WEAVILE,NightHoldItem,RAZORCLAW', '0215_Sneasel'),
(216, 'TEDDIURSA', 'Teddiursa', 'NORMAL', NULL, 60, 80, 50, 50, 50, 40, 'Female50Percent', 'Medium', 66, 120, 50, 'PICKUP', 'QUICKFEET', 'HONEYGATHER', 'Field', 5120, 0.6, 8.8, 'Brown', 'BipedalTail', 'Mountain', 'Little Bear', 'It licks its palms that are sweetened by being soaked in honey. A Teddiursa makes its own honey by blending fruits and pollen collected by Beedrill.', '2', 'URSARING,Level,30', '0216_Teddiursa'),
(217, 'URSARING', 'Ursaring', 'NORMAL', NULL, 90, 130, 75, 75, 75, 55, 'Female50Percent', 'Medium', 175, 60, 50, 'GUTS', 'QUICKFEET', 'UNNERVE', 'Field', 5120, 1.8, 125.8, 'Brown', 'BipedalTail', 'Mountain', 'Hibernator', 'In forests, it is said that there are many streams and towering trees where an Ursaring gathers food. It walks through its forest collecting food every day.', '2', NULL, '0217_Ursaring'),
(218, 'SLUGMA', 'Slugma', 'FIRE', NULL, 40, 40, 40, 70, 40, 20, 'Female50Percent', 'Medium', 50, 190, 50, 'MAGMAARMOR', 'FLAMEBODY', 'WEAKARMOR', 'Amorphous', 5120, 0.7, 35.0, 'Red', 'Serpentine', 'Mountain', 'Lava', 'It is a species of Pokémon that lives in volcanic areas. If its body cools, its skin hardens and immobilizes it. To avoid that, it sleeps near magma.', '2', 'MAGCARGO,Level,38', '0218_Slugma'),
(219, 'MAGCARGO', 'Magcargo', 'FIRE', 'ROCK', 60, 50, 120, 90, 80, 30, 'Female50Percent', 'Medium', 151, 75, 50, 'MAGMAARMOR', 'FLAMEBODY', 'WEAKARMOR', 'Amorphous', 5120, 0.8, 55.0, 'Red', 'Serpentine', 'Mountain', 'Lava', 'The shell on its back is made of hardened magma. Tens of thousands of years spent living in volcanic craters have turned Magcargo''s bodies into magma.', '2', NULL, '0219_Magcargo'),
(220, 'SWINUB', 'Swinub', 'ICE', 'GROUND', 50, 50, 40, 30, 30, 50, 'Female50Percent', 'Slow', 50, 225, 50, 'OBLIVIOUS', 'SNOWCLOAK', 'THICKFAT', 'Field', 5120, 0.4, 6.5, 'Brown', 'Quadruped', 'Cave', 'Pig', 'It roots for food by rubbing its snout against the ground. Its favorite food is a mushroom that grows under dried grass. It occasionally roots out hot springs.', '2', 'PILOSWINE,Level,33', '0220_Swinub'),
(221, 'PILOSWINE', 'Piloswine', 'ICE', 'GROUND', 100, 100, 80, 60, 60, 50, 'Female50Percent', 'Slow', 158, 75, 50, 'OBLIVIOUS', 'SNOWCLOAK', 'THICKFAT', 'Field', 5120, 1.1, 55.8, 'Brown', 'Quadruped', 'Cave', 'Swine', 'A Piloswine is covered by a thick coat of long hair for enduring freezing cold. It uses its tusks to dig up food that has been buried under ice.', '2', 'MAMOSWINE,HasMove,ANCIENTPOWER', '0221_Piloswine'),
(222, 'CORSOLA', 'Corsola', 'WATER', 'ROCK', 65, 55, 95, 65, 95, 35, 'Female75Percent', 'Fast', 144, 60, 50, 'HUSTLE', 'NATURALCURE', 'REGENERATOR', 'Water1,Water3', 5120, 0.6, 5.0, 'Pink', 'Insectoid', 'Sea', 'Coral', 'Corsola live in warm southern seas. If the sea becomes polluted, the beautiful coral stalks become discolored and crumble away in tatters.', '2', 'CURSOLA,None,', '0222_Corsola'),
(223, 'REMORAID', 'Remoraid', 'WATER', NULL, 35, 65, 35, 65, 35, 65, 'Female50Percent', 'Medium', 60, 190, 50, 'HUSTLE', 'SNIPER', 'MOODY', 'Water1,Water2', 5120, 0.6, 12.0, 'Gray', 'Finned', 'Sea', 'Jet', 'A Remoraid uses its abdominal muscles to forcefully expel swallowed water, then shoot down flying prey. When evolution approaches, it travels down rivers.', '2', 'OCTILLERY,Level,25', '0223_Remoraid'),
(224, 'OCTILLERY', 'Octillery', 'WATER', NULL, 75, 105, 75, 105, 75, 45, 'Female50Percent', 'Medium', 168, 75, 50, 'SUCTIONCUPS', 'SNIPER', 'MOODY', 'Water1,Water2', 5120, 0.9, 28.5, 'Red', 'Multiped', 'Sea', 'Jet', 'It ensnares its foe with its suction- cupped tentacles before delivering the finishing blow. If the foe turns out to be too strong, it spews ink to escape.', '2', NULL, '0224_Octillery'),
(225, 'DELIBIRD', 'Delibird', 'ICE', 'FLYING', 45, 55, 45, 65, 45, 75, 'Female50Percent', 'Fast', 116, 45, 50, 'VITALSPIRIT', 'HUSTLE', 'INSOMNIA', 'Water1,Field', 5120, 0.9, 16.0, 'Red', 'Winged', 'Mountain', 'Delivery', 'It carries food bundled up in its tail. There was a famous explorer who managed to scale Mt. Everest thanks to a Delibird sharing its food.', '2', NULL, '0225_Delibird'),
(226, 'MANTINE', 'Mantine', 'WATER', 'FLYING', 85, 40, 70, 80, 140, 70, 'Female50Percent', 'Slow', 170, 25, 50, 'SWIFTSWIM', 'WATERABSORB', 'WATERVEIL', 'Water1', 6400, 2.1, 220.0, 'Purple', 'Winged', 'Sea', 'Kite', 'On sunny days, schools of Mantine can be seen elegantly leaping over the waves. It is not bothered by the Remoraid that hitches rides.', '2', NULL, '0226_Mantine'),
(227, 'SKARMORY', 'Skarmory', 'STEEL', 'FLYING', 65, 80, 140, 40, 70, 70, 'Female50Percent', 'Slow', 163, 25, 50, 'KEENEYE', 'STURDY', 'WEAKARMOR', 'Flying', 6400, 1.7, 50.5, 'Gray', 'Winged', 'RoughTerrain', 'Armor Bird', 'A Pokémon that has a body and wings of steel. People in the past used feathers fallen from Skarmory to make swords and knives.', '2', NULL, '0227_Skarmory'),
(228, 'HOUNDOUR', 'Houndour', 'DARK', 'FIRE', 45, 60, 30, 80, 50, 65, 'Female50Percent', 'Slow', 66, 120, 35, 'EARLYBIRD', 'FLASHFIRE', 'UNNERVE', 'Field', 5120, 0.6, 10.8, 'Black', 'Quadruped', 'RoughTerrain', 'Dark', 'Houndour communicate with each other using a variety of cries to corner their prey. This Pokémon''s remarkable teamwork is simply unparalleled.', '2', 'HOUNDOOM,Level,24', '0228_Houndour'),
(229, 'HOUNDOOM', 'Houndoom', 'DARK', 'FIRE', 75, 90, 50, 110, 80, 95, 'Female50Percent', 'Slow', 175, 45, 35, 'EARLYBIRD', 'FLASHFIRE', 'UNNERVE', 'Field', 5120, 1.4, 35.0, 'Black', 'Quadruped', 'RoughTerrain', 'Dark', 'In a Houndoom pack, the one with its horns raked sharply back serves a leadership role. They choose their leader by fighting among themselves.', '2', NULL, '0229_Houndoom'),
(230, 'KINGDRA', 'Kingdra', 'WATER', 'DRAGON', 75, 95, 95, 95, 95, 85, 'Female50Percent', 'Medium', 270, 45, 50, 'SWIFTSWIM', 'SNIPER', 'DAMP', 'Water1,Dragon', 5120, 1.8, 152.0, 'Blue', 'HeadBase', 'Sea', 'Dragon', 'It sleeps quietly, deep on the seafloor. When it comes up to the surface, it creates a huge whirlpool that can swallow even ships.', '2', NULL, '0230_Kingdra'),
(231, 'PHANPY', 'Phanpy', 'GROUND', NULL, 90, 60, 60, 40, 40, 40, 'Female50Percent', 'Medium', 66, 120, 50, 'PICKUP', NULL, 'SANDVEIL', 'Field', 5120, 0.5, 33.5, 'Blue', 'Quadruped', 'RoughTerrain', 'Long Nose', 'Phanpy''s big ears serve as broad fans. When it becomes hot, it flaps the ears busily to cool down. Even the young are very strong.', '2', 'DONPHAN,Level,25', '0231_Phanpy'),
(232, 'DONPHAN', 'Donphan', 'GROUND', NULL, 90, 120, 120, 60, 60, 50, 'Female50Percent', 'Medium', 175, 60, 50, 'STURDY', NULL, 'SANDVEIL', 'Field', 5120, 1.1, 120.0, 'Gray', 'Quadruped', 'RoughTerrain', 'Armor', 'A Donphan is so strong it can easily haul a dump truck. Its hide has toughened to a rock-hard state. An ordinary sort of attack won''t even leave a scratch.', '2', NULL, '0232_Donphan'),
(233, 'PORYGON2', 'Porygon2', 'NORMAL', NULL, 85, 80, 90, 105, 95, 60, 'Genderless', 'Medium', 180, 45, 50, 'TRACE', 'DOWNLOAD', 'ANALYTIC', 'Mineral', 5120, 0.6, 32.5, 'Red', 'HeadLegs', 'Urban', 'Virtual', 'It was created by humans using the power of science. It has been given artificial intelligence that enables it to learn new gestures and emotions on its own.', '2', 'PORYGONZ,TradeItem,DUBIOUSDISC', '0233_Porygon2'),
(234, 'STANTLER', 'Stantler', 'NORMAL', NULL, 73, 95, 62, 85, 65, 85, 'Female50Percent', 'Slow', 163, 45, 50, 'INTIMIDATE', 'FRISK', 'SAPSIPPER', 'Field', 5120, 1.4, 71.2, 'Brown', 'Quadruped', 'Forest', 'Big Horn', 'Stantler''s magnificent antlers were once traded at high prices as works of art. As a result, this Pokémon was hunted close to extinction.', '2', NULL, '0234_Stantler'),
(235, 'SMEARGLE', 'Smeargle', 'NORMAL', NULL, 55, 20, 35, 20, 45, 75, 'Female50Percent', 'Fast', 88, 45, 50, 'OWNTEMPO', 'TECHNICIAN', 'MOODY', 'Field', 5120, 1.2, 58.0, 'White', 'BipedalTail', 'Urban', 'Painter', 'A Smeargle marks its territory using a fluid that leaks out from the tip of its tail. About 5,000 different marks left by this Pokémon have been found.', '2', NULL, '0235_Smeargle'),
(236, 'TYROGUE', 'Tyrogue', 'FIGHTING', NULL, 35, 35, 35, 35, 35, 35, 'AlwaysMale', 'Medium', 42, 75, 50, 'GUTS', 'STEADFAST', 'VITALSPIRIT', 'Undiscovered', 6400, 0.7, 21.0, 'Purple', 'Bipedal', 'Urban', 'Scuffle', 'Tyrogue become stressed out if they do not get to train every day. When raising this Pokémon, the trainer must establish a regular training schedule.', '2', 'HITMONLEE,AttackGreater,20,HITMONCHAN,DefenseGreater,20,HITMONTOP,AtkDefEqual,20', '0236_Tyrogue'),
(237, 'HITMONTOP', 'Hitmontop', 'FIGHTING', NULL, 50, 95, 95, 35, 110, 70, 'AlwaysMale', 'Medium', 159, 45, 50, 'INTIMIDATE', 'TECHNICIAN', 'STEADFAST', 'Humanlike', 6400, 1.4, 48.0, 'Brown', 'BipedalTail', 'Urban', 'Handstand', 'Its technique of kicking while spinning is a remarkable mix of both offense and defense. Hitmontop travel faster spinning than they do walking.', '2', NULL, '0237_Hitmontop'),
(238, 'SMOOCHUM', 'Smoochum', 'ICE', 'PSYCHIC', 45, 30, 15, 85, 65, 65, 'AlwaysFemale', 'Medium', 61, 45, 50, 'OBLIVIOUS', 'FOREWARN', 'HYDRATION', 'Undiscovered', 6400, 0.4, 6.0, 'Pink', 'Bipedal', 'Urban', 'Kiss', 'It actively runs about, but also falls often. Whenever it falls, it will check its reflection on a lake''s surface to make sure its face hasn''t become dirty.', '2', 'JYNX,Level,30', '0238_Smoochum'),
(239, 'ELEKID', 'Elekid', 'ELECTRIC', NULL, 45, 63, 37, 65, 55, 95, 'Female25Percent', 'Medium', 72, 45, 50, 'STATIC', NULL, 'VITALSPIRIT', 'Undiscovered', 6400, 0.6, 23.5, 'Yellow', 'Bipedal', 'Grassland', 'Electric', 'If it touches metal and discharges the electricity it has stored in its body, an Elekid begins swinging its arms in circles to recharge itself.', '2', 'ELECTABUZZ,Level,30', '0239_Elekid'),
(240, 'MAGBY', 'Magby', 'FIRE', NULL, 45, 75, 37, 70, 55, 83, 'Female25Percent', 'Medium', 73, 45, 50, 'FLAMEBODY', NULL, 'VITALSPIRIT', 'Undiscovered', 6400, 0.7, 21.4, 'Red', 'BipedalTail', 'Mountain', 'Live Coal', 'If a Magby is spouting yellow flames from its mouth, it is in good health. When it is fatigued, black smoke will be mixed in with the flames.', '2', 'MAGMAR,Level,30', '0240_Magby');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(241, 'MILTANK', 'Miltank', 'NORMAL', NULL, 95, 80, 105, 40, 70, 100, 'AlwaysFemale', 'Slow', 172, 45, 50, 'THICKFAT', 'SCRAPPY', 'SAPSIPPER', 'Field', 5120, 1.2, 75.5, 'Pink', 'BipedalTail', 'Grassland', 'Milk Cow', 'It gives over five gallons of milk daily. Its sweet milk is enjoyed by children and adults alike. People who can''t drink milk turn it into yogurt and eat it instead.', '2', NULL, '0241_Miltank'),
(242, 'BLISSEY', 'Blissey', 'NORMAL', NULL, 255, 10, 10, 75, 135, 55, 'AlwaysFemale', 'Fast', 635, 30, 140, 'NATURALCURE', 'SERENEGRACE', 'HEALER', 'Fairy', 10240, 1.5, 46.8, 'Pink', 'Bipedal', 'Urban', 'Happiness', 'If it senses sadness with its fluffy fur, a Blissey will rush over to the sad person, however far away, to share an egg of happiness that brings a smile to any face.', '2', NULL, '0242_Blissey'),
(243, 'RAIKOU', 'Raikou', 'ELECTRIC', NULL, 90, 85, 75, 115, 100, 115, 'Genderless', 'Slow', 290, 3, 35, 'PRESSURE', NULL, 'INNERFOCUS', 'Undiscovered', 20480, 1.9, 178.0, 'Yellow', 'Quadruped', 'Grassland', 'Thunder', 'Raikou embodies the speed of lightning. Its roars send shock waves shuddering through the air and ground as if lightning bolts were crashing down.', '2', NULL, '0243_Raikou'),
(244, 'ENTEI', 'Entei', 'FIRE', NULL, 115, 115, 85, 90, 75, 100, 'Genderless', 'Slow', 290, 3, 35, 'PRESSURE', NULL, 'INNERFOCUS', 'Undiscovered', 20480, 2.1, 198.0, 'Brown', 'Quadruped', 'Grassland', 'Volcano', 'Entei embodies the passion of magma. It is thought to have been born in the eruption of a volcano. It blasts fire that consumes all that it touches.', '2', NULL, '0244_Entei'),
(245, 'SUICUNE', 'Suicune', 'WATER', NULL, 100, 75, 115, 90, 115, 85, 'Genderless', 'Slow', 290, 3, 35, 'PRESSURE', NULL, 'INNERFOCUS', 'Undiscovered', 20480, 2.0, 187.0, 'Blue', 'Quadruped', 'Grassland', 'Aurora', 'Suicune embodies the compassion of a pure spring of water. It runs across the land with gliding elegance. It has the power to purify dirty water.', '2', NULL, '0245_Suicune'),
(246, 'LARVITAR', 'Larvitar', 'ROCK', 'GROUND', 50, 64, 50, 45, 50, 41, 'Female50Percent', 'Slow', 60, 45, 35, 'GUTS', NULL, 'SANDVEIL', 'Monster', 10240, 0.6, 72.0, 'Green', 'BipedalTail', 'Mountain', 'Rock Skin', 'A Larvitar is born deep under the ground. It must eat its way through the soil above and reach the surface for it to see its parents'' faces.', '2', 'PUPITAR,Level,30', '0246_Larvitar'),
(247, 'PUPITAR', 'Pupitar', 'ROCK', 'GROUND', 70, 84, 70, 65, 70, 51, 'Female50Percent', 'Slow', 144, 45, 35, 'SHEDSKIN', NULL, NULL, 'Monster', 10240, 1.2, 152.0, 'Gray', 'Serpentine', 'Mountain', 'Hard Shell', 'A Pupitar creates a gas inside its body that it ejects under compression to propel itself like a jet. Its body can withstand a collision with solid steel.', '2', 'TYRANITAR,Level,55', '0247_Pupitar'),
(248, 'TYRANITAR', 'Tyranitar', 'ROCK', 'DARK', 100, 134, 110, 95, 100, 61, 'Female50Percent', 'Slow', 300, 45, 35, 'SANDSTREAM', NULL, 'UNNERVE', 'Monster', 10240, 2.0, 202.0, 'Green', 'BipedalTail', 'Mountain', 'Armor', 'A Tyranitar is so overwhelmingly powerful, it can bring down a whole mountain to make its nest. It roams in mountains seeking new opponents to fight.', '2', NULL, '0248_Tyranitar'),
(249, 'LUGIA', 'Lugia', 'PSYCHIC', 'FLYING', 106, 90, 130, 90, 154, 110, 'Genderless', 'Slow', 340, 3, 0, 'PRESSURE', NULL, 'MULTISCALE', 'Undiscovered', 30720, 5.2, 216.0, 'White', 'Winged', 'Rare', 'Diving', 'Lugia is so powerful even a light fluttering of its wings can blow apart houses. As a result, it chooses to live out of sight deep under the sea.', '2', NULL, '0249_Lugia'),
(250, 'HOOH', 'Ho-Oh', 'FIRE', 'FLYING', 106, 130, 90, 110, 154, 90, 'Genderless', 'Slow', 340, 3, 0, 'PRESSURE', NULL, 'REGENERATOR', 'Undiscovered', 30720, 3.8, 199.0, 'Red', 'Winged', 'Rare', 'Rainbow', 'Its feathers--which glow in seven colors depending on the angle at which light strikes them--are thought to bring joy. It is said to live at the foot of a rainbow.', '2', NULL, '0250_Ho-Oh'),
(251, 'CELEBI', 'Celebi', 'PSYCHIC', 'GRASS', 100, 100, 100, 100, 100, 100, 'Genderless', 'Parabolic', 300, 45, 100, 'NATURALCURE', NULL, NULL, 'Undiscovered', 30720, 0.6, 5.0, 'Green', 'Bipedal', 'Forest', 'Time Travel', 'This Pokémon came from the future by crossing over time. It is thought that so long as Celebi appears, a bright and shining future awaits us.', '2', NULL, '0251_Celebi'),
(252, 'TREECKO', 'Treecko', 'GRASS', NULL, 40, 45, 35, 65, 55, 70, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'OVERGROW', NULL, 'UNBURDEN', 'Monster,Dragon', 5120, 0.5, 5.0, 'Green', 'BipedalTail', 'Forest', 'Wood Gecko', 'It makes its nest in a giant tree in the forest. It ferociously guards against anything nearing its territory. It is said to be the protector of the trees.', '3', 'GROVYLE,Level,16', '0252_Treecko'),
(253, 'GROVYLE', 'Grovyle', 'GRASS', NULL, 50, 65, 45, 85, 65, 95, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'OVERGROW', NULL, 'UNBURDEN', 'Monster,Dragon', 5120, 0.9, 21.6, 'Green', 'BipedalTail', 'Forest', 'Wood Gecko', 'Leaves grow out of this Pokémon''s body. They help obscure a Grovyle from the eyes of its enemies while it is in a thickly overgrown forest.', '3', 'SCEPTILE,Level,36', '0253_Grovyle'),
(254, 'SCEPTILE', 'Sceptile', 'GRASS', NULL, 70, 85, 65, 105, 85, 120, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'OVERGROW', NULL, 'UNBURDEN', 'Monster,Dragon', 5120, 1.7, 52.2, 'Green', 'BipedalTail', 'Forest', 'Forest', 'In the jungle, its power is without equal. This Pokémon carefully grows trees and plants. It regulates its body temperature by basking in sunlight.', '3', NULL, '0254_Sceptile'),
(255, 'TORCHIC', 'Torchic', 'FIRE', NULL, 45, 60, 40, 70, 50, 45, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'SPEEDBOOST', 'Field', 5120, 0.4, 2.5, 'Red', 'HeadLegs', 'Grassland', 'Chick', 'If attacked, it strikes back by spitting balls of fire it forms in its stomach. A Torchic dislikes darkness because it can''t see its surroundings.', '3', 'COMBUSKEN,Level,16', '0255_Torchic'),
(256, 'COMBUSKEN', 'Combusken', 'FIRE', 'FIGHTING', 60, 85, 60, 85, 60, 55, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'BLAZE', NULL, 'SPEEDBOOST', 'Field', 5120, 0.9, 19.5, 'Red', 'BipedalTail', 'Grassland', 'Young Fowl', 'It lashes out with 10 kicks per second. Its strong fighting instinct compels it to keep up its offensive until the opponent gives up.', '3', 'BLAZIKEN,Level,36', '0256_Combusken'),
(257, 'BLAZIKEN', 'Blaziken', 'FIRE', 'FIGHTING', 80, 120, 70, 110, 70, 80, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'BLAZE', NULL, 'SPEEDBOOST', 'Field', 5120, 1.9, 52.0, 'Red', 'BipedalTail', 'Grassland', 'Blaze', 'It learns martial arts that use punches and kicks. Every several years, its old feathers burn off, and new, supple feathers grow back in their place.', '3', NULL, '0257_Blaziken'),
(258, 'MUDKIP', 'Mudkip', 'WATER', NULL, 50, 70, 50, 50, 50, 40, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'TORRENT', NULL, 'DAMP', 'Monster,Water1', 5120, 0.4, 7.6, 'Blue', 'Quadruped', 'WatersEdge', 'Mud Fish', 'On land, it can powerfully lift large boulders by planting its four feet and heaving. It sleeps by burying itself in soil at the water''s edge.', '3', 'MARSHTOMP,Level,16', '0258_Mudkip'),
(259, 'MARSHTOMP', 'Marshtomp', 'WATER', 'GROUND', 70, 85, 70, 60, 70, 50, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'TORRENT', NULL, 'DAMP', 'Monster,Water1', 5120, 0.7, 28.0, 'Blue', 'BipedalTail', 'WatersEdge', 'Mud Fish', 'Its toughened hind legs enable it to stand upright. Because it weakens if its skin dries out, it replenishes fluids by playing in mud.', '3', 'SWAMPERT,Level,36', '0259_Marshtomp'),
(260, 'SWAMPERT', 'Swampert', 'WATER', 'GROUND', 100, 110, 90, 85, 90, 60, 'FemaleOneEighth', 'Parabolic', 268, 45, 50, 'TORRENT', NULL, 'DAMP', 'Monster,Water1', 5120, 1.5, 81.9, 'Blue', 'BipedalTail', 'WatersEdge', 'Mud Fish', 'If it senses the approach of a storm and a tidal wave, it protects its seaside nest by piling up boulders. It swims as fast as a jet ski.', '3', NULL, '0260_Swampert'),
(261, 'POOCHYENA', 'Poochyena', 'DARK', NULL, 35, 55, 35, 30, 30, 35, 'Female50Percent', 'Medium', 56, 255, 50, 'RUNAWAY', 'QUICKFEET', 'RATTLED', 'Field', 3840, 0.5, 13.6, 'Gray', 'Quadruped', 'Grassland', 'Bite', 'It savagely threatens foes with bared fangs. It chases after fleeing targets tenaciously. It turns tail and runs, however, if the foe strikes back.', '3', 'MIGHTYENA,Level,18', '0261_Poochyena'),
(262, 'MIGHTYENA', 'Mightyena', 'DARK', NULL, 70, 90, 70, 60, 60, 70, 'Female50Percent', 'Medium', 147, 127, 50, 'INTIMIDATE', 'QUICKFEET', 'MOXIE', 'Field', 3840, 1.0, 37.0, 'Gray', 'Quadruped', 'Grassland', 'Bite', 'In the wild, Mightyena live in a pack. They never defy their leader''s orders. They defeat foes with perfectly coordinated teamwork.', '3', NULL, '0262_Mightyena'),
(263, 'ZIGZAGOON', 'Zigzagoon', 'NORMAL', NULL, 38, 30, 41, 30, 41, 60, 'Female50Percent', 'Medium', 56, 255, 50, 'PICKUP', 'GLUTTONY', 'QUICKFEET', 'Field', 3840, 0.4, 17.5, 'Brown', 'Quadruped', 'Grassland', 'Tiny Raccoon', 'Rubbing its nose against the ground, it always wanders about back and forth in search of something. It is distinguished by the zigzag footprints it leaves.', '3', 'LINOONE,Level,20', '0263_Zigzagoon'),
(264, 'LINOONE', 'Linoone', 'NORMAL', NULL, 78, 70, 61, 50, 61, 100, 'Female50Percent', 'Medium', 147, 90, 50, 'PICKUP', 'GLUTTONY', 'QUICKFEET', 'Field', 3840, 0.5, 32.5, 'White', 'Quadruped', 'Grassland', 'Rushing', 'It is exceedingly fast if it only has to run in a straight line. When it spots pond- dwelling prey underwater, it quickly leaps in and catches it with its sharp claws.', '3', 'OBSTAGOON,None,', '0264_Linoone'),
(265, 'WURMPLE', 'Wurmple', 'BUG', NULL, 45, 45, 35, 20, 30, 20, 'Female50Percent', 'Medium', 56, 255, 50, 'SHIELDDUST', NULL, 'RUNAWAY', 'Bug', 3840, 0.3, 3.6, 'Red', 'Insectoid', 'Forest', 'Worm', 'It sticks to tree branches and eats leaves. The thread it spits from its mouth becomes gooey when it touches air and slows the movement of its foes.', '3', 'SILCOON,Silcoon,7,CASCOON,Cascoon,7', '0265_Wurmple'),
(266, 'SILCOON', 'Silcoon', 'BUG', NULL, 50, 35, 55, 25, 25, 15, 'Female50Percent', 'Medium', 72, 120, 50, 'SHEDSKIN', NULL, NULL, 'Bug', 3840, 0.6, 10.0, 'White', 'Head', 'Forest', 'Cocoon', 'It prepares for evolution using the energy it stored while it was a Wurmple. It keeps watch over the surroundings with its two eyes.', '3', 'BEAUTIFLY,Level,10', '0266_Silcoon'),
(267, 'BEAUTIFLY', 'Beautifly', 'BUG', 'FLYING', 60, 70, 50, 100, 50, 65, 'Female50Percent', 'Medium', 198, 45, 50, 'SWARM', NULL, 'RIVALRY', 'Bug', 3840, 1.0, 28.4, 'Yellow', 'MultiWinged', 'Forest', 'Butterfly', 'Its colorfully patterned wings are its most prominent feature. It flies through flower-covered fields collecting pollen. It attacks ferociously when angered.', '3', NULL, '0267_Beautifly'),
(268, 'CASCOON', 'Cascoon', 'BUG', NULL, 50, 35, 55, 25, 25, 15, 'Female50Percent', 'Medium', 72, 120, 50, 'SHEDSKIN', NULL, NULL, 'Bug', 3840, 0.7, 11.5, 'Purple', 'Head', 'Forest', 'Cocoon', 'To avoid detection by its enemies, it hides motionlessly beneath large leaves and in the gaps of branches. It also attaches dead leaves to its body for camouflage.', '3', 'DUSTOX,Level,10', '0268_Cascoon'),
(269, 'DUSTOX', 'Dustox', 'BUG', 'POISON', 60, 50, 70, 50, 90, 65, 'Female50Percent', 'Medium', 193, 45, 50, 'SHIELDDUST', NULL, 'COMPOUNDEYES', 'Bug', 3840, 1.2, 31.6, 'Green', 'MultiWinged', 'Forest', 'Poison Moth', 'It is a nocturnal Pokémon that flies from fields and mountains to the attraction of streetlights at night. It looses highly toxic powder from its wings.', '3', NULL, '0269_Dustox'),
(270, 'LOTAD', 'Lotad', 'WATER', 'GRASS', 40, 30, 30, 40, 50, 30, 'Female50Percent', 'Parabolic', 44, 255, 50, 'SWIFTSWIM', 'RAINDISH', 'OWNTEMPO', 'Water1,Grass', 3840, 0.5, 2.6, 'Green', 'Insectoid', 'WatersEdge', 'Water Weed', 'This Pokémon lives in ponds with clean water. It is known to ferry small Pokémon across ponds by carrying them on the broad leaf on its head.', '3', 'LOMBRE,Level,14', '0270_Lotad'),
(271, 'LOMBRE', 'Lombre', 'WATER', 'GRASS', 60, 50, 50, 60, 70, 50, 'Female50Percent', 'Parabolic', 119, 120, 50, 'SWIFTSWIM', 'RAINDISH', 'OWNTEMPO', 'Water1,Grass', 3840, 1.2, 32.5, 'Green', 'Bipedal', 'WatersEdge', 'Jolly', 'In the evening, it takes great delight in popping out of rivers and startling people. It feeds on aquatic moss that grows on rocks in the riverbed.', '3', 'LUDICOLO,Item,WATERSTONE', '0271_Lombre'),
(272, 'LUDICOLO', 'Ludicolo', 'WATER', 'GRASS', 80, 70, 70, 90, 100, 70, 'Female50Percent', 'Parabolic', 240, 45, 50, 'SWIFTSWIM', 'RAINDISH', 'OWNTEMPO', 'Water1,Grass', 3840, 1.5, 55.0, 'Green', 'Bipedal', 'WatersEdge', 'Carefree', 'When it hears festive music, all the cells in its body become stimulated, and it begins moving in rhythm. It does not quail even when it faces a tough opponent.', '3', NULL, '0272_Ludicolo'),
(273, 'SEEDOT', 'Seedot', 'GRASS', NULL, 40, 40, 50, 30, 30, 30, 'Female50Percent', 'Parabolic', 44, 255, 50, 'CHLOROPHYLL', 'EARLYBIRD', 'PICKPOCKET', 'Field,Grass', 3840, 0.5, 4.0, 'Brown', 'HeadLegs', 'Forest', 'Acorn', 'It hangs off branches and absorbs nutrients. When it finishes eating, its body becomes so heavy that it drops to the ground with a thump.', '3', 'NUZLEAF,Level,14', '0273_Seedot'),
(274, 'NUZLEAF', 'Nuzleaf', 'GRASS', 'DARK', 70, 70, 40, 60, 40, 60, 'Female50Percent', 'Parabolic', 119, 120, 50, 'CHLOROPHYLL', 'EARLYBIRD', 'PICKPOCKET', 'Field,Grass', 3840, 1.0, 28.0, 'Brown', 'Bipedal', 'Forest', 'Wily', 'A forest-dwelling Pokémon that is skilled at climbing trees. Its long and pointed nose is its weak point. It loses power if the nose is gripped.', '3', 'SHIFTRY,Item,LEAFSTONE', '0274_Nuzleaf'),
(275, 'SHIFTRY', 'Shiftry', 'GRASS', 'DARK', 90, 100, 60, 90, 60, 80, 'Female50Percent', 'Parabolic', 240, 45, 50, 'CHLOROPHYLL', 'EARLYBIRD', 'PICKPOCKET', 'Field,Grass', 3840, 1.3, 59.6, 'Brown', 'Bipedal', 'Forest', 'Wicked', 'It is said to arrive on chilly, wintry winds. Feared from long ago as the guardian of forests, this Pokémon lives in a deep forest where people do not venture.', '3', NULL, '0275_Shiftry'),
(276, 'TAILLOW', 'Taillow', 'NORMAL', 'FLYING', 40, 55, 30, 30, 30, 85, 'Female50Percent', 'Parabolic', 54, 200, 50, 'GUTS', NULL, 'SCRAPPY', 'Flying', 3840, 0.3, 2.3, 'Blue', 'Winged', 'Grassland', 'Tiny Swallow', 'Although it is small, it is very courageous. It will take on a larger Skarmory on an equal footing. However, its will weakens if it becomes hungry.', '3', 'SWELLOW,Level,22', '0276_Taillow'),
(277, 'SWELLOW', 'Swellow', 'NORMAL', 'FLYING', 60, 85, 60, 75, 50, 125, 'Female50Percent', 'Parabolic', 159, 45, 50, 'GUTS', NULL, 'SCRAPPY', 'Flying', 3840, 0.7, 19.8, 'Blue', 'Winged', 'Grassland', 'Swallow', 'A Swellow dives upon prey from far above. It never misses its targets. It takes to the skies in search of lands with a warm climate.', '3', NULL, '0277_Swellow'),
(278, 'WINGULL', 'Wingull', 'WATER', 'FLYING', 40, 30, 30, 55, 30, 85, 'Female50Percent', 'Medium', 54, 190, 50, 'KEENEYE', 'HYDRATION', 'RAINDISH', 'Water1,Flying', 5120, 0.6, 9.5, 'White', 'Winged', 'Sea', 'Seagull', 'It makes its nest on a sheer cliff at the edge of the sea. It has trouble keeping its wings flapping in flight. Instead, it soars on updrafts.', '3', 'PELIPPER,Level,25', '0278_Wingull'),
(279, 'PELIPPER', 'Pelipper', 'WATER', 'FLYING', 60, 50, 100, 95, 70, 65, 'Female50Percent', 'Medium', 154, 45, 50, 'KEENEYE', 'DRIZZLE', 'RAINDISH', 'Water1,Flying', 5120, 1.2, 28.0, 'Yellow', 'Winged', 'Sea', 'Water Bird', 'It skims the tops of waves as it flies. When it spots prey, it uses its large beak to scoop up the victim with water. It protects its eggs in its beak.', '3', NULL, '0279_Pelipper'),
(280, 'RALTS', 'Ralts', 'PSYCHIC', 'FAIRY', 28, 25, 25, 45, 35, 40, 'Female50Percent', 'Slow', 40, 235, 35, 'SYNCHRONIZE', 'TRACE', 'TELEPATHY', 'Humanlike,Amorphous', 5120, 0.4, 6.6, 'White', 'Bipedal', 'Urban', 'Feeling', 'A Ralts has the power to sense the emotions of people and Pokémon with the horns on its head. It takes cover if it senses any hostility.', '3', 'KIRLIA,Level,20', '0280_Ralts'),
(281, 'KIRLIA', 'Kirlia', 'PSYCHIC', 'FAIRY', 38, 35, 35, 65, 55, 50, 'Female50Percent', 'Slow', 97, 120, 35, 'SYNCHRONIZE', 'TRACE', 'TELEPATHY', 'Humanlike,Amorphous', 5120, 0.8, 20.2, 'White', 'Bipedal', 'Urban', 'Emotion', 'A Kirlia has the psychic power to create a rip in the dimensions and see into the future. It is said to dance with pleasure on sunny mornings.', '3', 'GARDEVOIR,Level,30,GALLADE,ItemMale,DAWNSTONE', '0281_Kirlia'),
(282, 'GARDEVOIR', 'Gardevoir', 'PSYCHIC', 'FAIRY', 68, 65, 65, 125, 115, 80, 'Female50Percent', 'Slow', 259, 45, 35, 'SYNCHRONIZE', 'TRACE', 'TELEPATHY', 'Humanlike,Amorphous', 5120, 1.6, 48.4, 'White', 'Bipedal', 'Urban', 'Embrace', 'It apparently does not feel the pull of gravity because it supports itself with psychic power. It will give its life to protect its trainer.', '3', NULL, '0282_Gardevoir'),
(283, 'SURSKIT', 'Surskit', 'BUG', 'WATER', 40, 30, 32, 50, 52, 65, 'Female50Percent', 'Medium', 54, 200, 50, 'SWIFTSWIM', NULL, 'RAINDISH', 'Water1,Bug', 3840, 0.5, 1.7, 'Blue', 'Insectoid', 'WatersEdge', 'Pond Skater', 'They gather on puddles after evening downpours, gliding across the surface of water as if sliding. It secretes honey with a sweet aroma from its head.', '3', 'MASQUERAIN,Level,22', '0283_Surskit'),
(284, 'MASQUERAIN', 'Masquerain', 'BUG', 'FLYING', 70, 60, 62, 100, 82, 80, 'Female50Percent', 'Medium', 159, 75, 50, 'INTIMIDATE', NULL, 'UNNERVE', 'Water1,Bug', 3840, 0.8, 3.6, 'Blue', 'MultiWinged', 'WatersEdge', 'Eyeball', 'It intimidates foes with the large eyelike patterns on its antennae. Because it can''t fly if its wings get wet, it shelters from rain under large trees and eaves.', '3', NULL, '0284_Masquerain'),
(285, 'SHROOMISH', 'Shroomish', 'GRASS', NULL, 60, 40, 60, 40, 60, 35, 'Female50Percent', 'Fluctuating', 59, 255, 50, 'EFFECTSPORE', 'POISONHEAL', 'QUICKFEET', 'Fairy,Grass', 3840, 0.4, 4.5, 'Brown', 'HeadLegs', 'Forest', 'Mushroom', 'It loves to eat damp, composted soil in forests. If you enter a forest after a long rain, you can see many Shroomish feasting on composted soil.', '3', 'BRELOOM,Level,23', '0285_Shroomish'),
(286, 'BRELOOM', 'Breloom', 'GRASS', 'FIGHTING', 60, 130, 80, 60, 60, 70, 'Female50Percent', 'Fluctuating', 161, 90, 50, 'EFFECTSPORE', 'POISONHEAL', 'TECHNICIAN', 'Fairy,Grass', 3840, 1.2, 39.2, 'Green', 'BipedalTail', 'Forest', 'Mushroom', 'It scatters spores from holes in the cap on its head. It loves warm and humid climates. It feeds on trees and plants in fields and forests.', '3', NULL, '0286_Breloom'),
(287, 'SLAKOTH', 'Slakoth', 'NORMAL', NULL, 60, 60, 60, 35, 35, 30, 'Female50Percent', 'Slow', 56, 255, 50, 'TRUANT', NULL, NULL, 'Field', 3840, 0.8, 24.0, 'Brown', 'Quadruped', 'Forest', 'Slacker', 'It sleeps virtually all day and night long. It doesn''t change its nest its entire life, but it sometimes travels great distances by swimming in rivers.', '3', 'VIGOROTH,Level,18', '0287_Slakoth'),
(288, 'VIGOROTH', 'Vigoroth', 'NORMAL', NULL, 80, 80, 80, 55, 55, 90, 'Female50Percent', 'Slow', 154, 120, 50, 'VITALSPIRIT', NULL, NULL, 'Field', 3840, 1.4, 46.5, 'White', 'BipedalTail', 'Forest', 'Wild Monkey', 'It can''t keep still because its blood boils with energy. It runs through the fields and mountains all day to calm itself. If it doesn''t, it can''t sleep at night.', '3', 'SLAKING,Level,36', '0288_Vigoroth'),
(289, 'SLAKING', 'Slaking', 'NORMAL', NULL, 150, 160, 100, 95, 65, 100, 'Female50Percent', 'Slow', 285, 45, 50, 'TRUANT', NULL, NULL, 'Field', 3840, 2.0, 130.5, 'Brown', 'Bipedal', 'Forest', 'Lazy', 'Hordes of Slaking gather around trees when fruits come into season. They wait around patiently for ripened fruits to fall out of the trees.', '3', NULL, '0289_Slaking'),
(290, 'NINCADA', 'Nincada', 'BUG', 'GROUND', 31, 45, 90, 30, 30, 40, 'Female50Percent', 'Erratic', 53, 255, 50, 'COMPOUNDEYES', NULL, 'RUNAWAY', 'Bug', 3840, 0.5, 5.5, 'Gray', 'Insectoid', 'Forest', 'Trainee', 'It makes its nest at the roots of a mighty tree. Using its whiskerlike antennae, it probes its surroundings in the pitch-black darkness of soil.', '3', 'NINJASK,Ninjask,20,SHEDINJA,Shedinja,20', '0290_Nincada'),
(291, 'NINJASK', 'Ninjask', 'BUG', 'FLYING', 61, 90, 45, 50, 50, 160, 'Female50Percent', 'Erratic', 160, 120, 50, 'SPEEDBOOST', NULL, 'INFILTRATOR', 'Bug', 3840, 0.8, 12.0, 'Yellow', 'MultiWinged', 'Forest', 'Ninja', 'Because it darts about vigorously at high speed, it is very difficult to see. Hearing its distinctive cries for too long induces a headache.', '3', NULL, '0291_Ninjask'),
(292, 'SHEDINJA', 'Shedinja', 'BUG', 'GHOST', 1, 90, 45, 30, 30, 40, 'Genderless', 'Erratic', 83, 45, 50, 'WONDERGUARD', NULL, NULL, 'Mineral', 3840, 0.8, 1.2, 'Brown', 'HeadBase', 'Forest', 'Shed', 'A peculiar Pokémon that floats in air even though its wings remain completely still. The inside of its body is hollow and utterly dark.', '3', NULL, '0292_Shedinja'),
(293, 'WHISMUR', 'Whismur', 'NORMAL', NULL, 64, 51, 23, 51, 23, 28, 'Female50Percent', 'Parabolic', 48, 190, 50, 'SOUNDPROOF', NULL, 'RATTLED', 'Monster,Field', 5120, 0.6, 16.3, 'Pink', 'BipedalTail', 'Cave', 'Whisper', 'Its cries equal a jet plane in volume. It inhales through its ear canals. Because of this system, it can cry continually without having to catch its breath.', '3', 'LOUDRED,Level,20', '0293_Whismur'),
(294, 'LOUDRED', 'Loudred', 'NORMAL', NULL, 84, 71, 43, 71, 43, 48, 'Female50Percent', 'Parabolic', 126, 120, 50, 'SOUNDPROOF', NULL, 'SCRAPPY', 'Monster,Field', 5120, 1.0, 40.5, 'Blue', 'BipedalTail', 'Cave', 'Big Voice', 'It positions the round speakers on its head to assail foes with ultrasonic waves at massive volume. It builds power by stomping the ground.', '3', 'EXPLOUD,Level,40', '0294_Loudred'),
(295, 'EXPLOUD', 'Exploud', 'NORMAL', NULL, 104, 91, 63, 91, 73, 68, 'Female50Percent', 'Parabolic', 245, 45, 50, 'SOUNDPROOF', NULL, 'SCRAPPY', 'Monster,Field', 5120, 1.5, 84.0, 'Blue', 'BipedalTail', 'Cave', 'Loud Noise', 'It has sound-generating organs all over its body. It communicates with others by adjusting the tone and volume of the cries it emits.', '3', NULL, '0295_Exploud'),
(296, 'MAKUHITA', 'Makuhita', 'FIGHTING', NULL, 72, 60, 30, 20, 30, 25, 'Female25Percent', 'Fluctuating', 47, 180, 50, 'THICKFAT', 'GUTS', 'SHEERFORCE', 'Humanlike', 5120, 1.0, 86.4, 'Yellow', 'Bipedal', 'Mountain', 'Guts', 'It loves to toughen up its body above all else. If you hear quaking rumbles in a cave, it is the sound of Makuhita undertaking strenuous training.', '3', 'HARIYAMA,Level,24', '0296_Makuhita'),
(297, 'HARIYAMA', 'Hariyama', 'FIGHTING', NULL, 144, 120, 60, 40, 60, 50, 'Female25Percent', 'Fluctuating', 166, 200, 50, 'THICKFAT', 'GUTS', 'SHEERFORCE', 'Humanlike', 5120, 2.3, 253.8, 'Brown', 'Bipedal', 'Mountain', 'Arm Thrust', 'It has the habit of challenging others without hesitation to tests of strength. It''s been known to stand on train tracks and stop trains using forearm thrusts.', '3', NULL, '0297_Hariyama'),
(298, 'AZURILL', 'Azurill', 'NORMAL', 'FAIRY', 50, 20, 40, 20, 40, 20, 'Female75Percent', 'Fast', 38, 150, 50, 'THICKFAT', 'HUGEPOWER', 'SAPSIPPER', 'Undiscovered', 2560, 0.2, 2.0, 'Blue', 'HeadLegs', 'WatersEdge', 'Polka Dot', 'Its tail, which is packed with nutrition, is very bouncy like a rubber ball. On sunny days they gather at the edge of water and splash about for fun.', '3', 'MARILL,Happiness,', '0298_Azurill'),
(299, 'NOSEPASS', 'Nosepass', 'ROCK', NULL, 30, 45, 135, 45, 90, 30, 'Female50Percent', 'Medium', 75, 255, 50, 'STURDY', 'MAGNETPULL', 'SANDFORCE', 'Mineral', 5120, 1.0, 97.0, 'Gray', 'Bipedal', 'Cave', 'Compass', 'Its body emits a powerful magnetism. It feeds on prey that is pulled in by the force. Its magnetism is stronger in cold seasons.', '3', 'PROBOPASS,LocationFlag,Magnetic,PROBOPASS,Item,THUNDERSTONE', '0299_Nosepass'),
(300, 'SKITTY', 'Skitty', 'NORMAL', NULL, 50, 45, 45, 35, 35, 50, 'Female75Percent', 'Fast', 52, 255, 50, 'CUTECHARM', 'NORMALIZE', 'WONDERSKIN', 'Field,Fairy', 3840, 0.6, 11.0, 'Pink', 'Quadruped', 'Forest', 'Kitten', 'A Skitty''s adorably cute behavior makes it highly popular. In battle, it makes its tail puff out. It threatens foes with a sharp growl.', '3', 'DELCATTY,Item,MOONSTONE', '0300_Skitty'),
(301, 'DELCATTY', 'Delcatty', 'NORMAL', NULL, 70, 65, 65, 55, 55, 90, 'Female75Percent', 'Fast', 140, 60, 50, 'CUTECHARM', 'NORMALIZE', 'WONDERSKIN', 'Field,Fairy', 3840, 1.1, 32.6, 'Purple', 'Quadruped', 'Forest', 'Prim', 'Rather than keeping a permanent lair, it habitually seeks comfortable spots and sleeps there. It is nocturnal and becomes active at dusk.', '3', NULL, '0301_Delcatty'),
(302, 'SABLEYE', 'Sableye', 'DARK', 'GHOST', 50, 75, 75, 65, 65, 50, 'Female50Percent', 'Parabolic', 133, 45, 35, 'KEENEYE', 'STALL', 'PRANKSTER', 'Humanlike', 6400, 0.5, 11.0, 'Purple', 'Bipedal', 'Cave', 'Darkness', 'It digs branching holes in caves using its sharp claws in search of food--raw gems. A Sableye lurks in darkness and is seen only rarely.', '3', NULL, '0302_Sableye'),
(303, 'MAWILE', 'Mawile', 'STEEL', 'FAIRY', 50, 85, 85, 55, 55, 50, 'Female50Percent', 'Fast', 133, 45, 50, 'HYPERCUTTER', 'INTIMIDATE', 'SHEERFORCE', 'Field,Fairy', 5120, 0.6, 11.5, 'Black', 'Bipedal', 'Cave', 'Deceiver', 'Its giant jaws are actually steel horns that transformed. It fools foes into complacency with its adorable gestures, then chomps them with its huge jaws.', '3', NULL, '0303_Mawile'),
(304, 'ARON', 'Aron', 'STEEL', 'ROCK', 50, 70, 100, 40, 40, 30, 'Female50Percent', 'Slow', 66, 180, 35, 'STURDY', 'ROCKHEAD', 'HEAVYMETAL', 'Monster', 8960, 0.4, 60.0, 'Gray', 'Quadruped', 'Mountain', 'Iron Armor', 'A Pokémon that is clad in steel armor. A new suit of armor is made when it evolves. The old, discarded armor is salvaged as metal for making iron products.', '3', 'LAIRON,Level,32', '0304_Aron'),
(305, 'LAIRON', 'Lairon', 'STEEL', 'ROCK', 60, 90, 140, 50, 50, 40, 'Female50Percent', 'Slow', 151, 90, 35, 'STURDY', 'ROCKHEAD', 'HEAVYMETAL', 'Monster', 8960, 0.9, 120.0, 'Gray', 'Quadruped', 'Mountain', 'Iron Armor', 'When two Lairon meet in the wild, they fight for territory by bashing into each other with their steel bodies. The sound of their collision carries for miles.', '3', 'AGGRON,Level,42', '0305_Lairon'),
(306, 'AGGRON', 'Aggron', 'STEEL', 'ROCK', 70, 110, 180, 60, 60, 50, 'Female50Percent', 'Slow', 265, 45, 35, 'STURDY', 'ROCKHEAD', 'HEAVYMETAL', 'Monster', 8960, 2.1, 360.0, 'Gray', 'BipedalTail', 'Mountain', 'Iron Armor', 'Its iron horns grow longer a little at a time. They are used to determine the Aggron''s age. The gouges in its armor are worn with pride as mementos from battles.', '3', NULL, '0306_Aggron'),
(307, 'MEDITITE', 'Meditite', 'FIGHTING', 'PSYCHIC', 30, 40, 55, 40, 55, 60, 'Female50Percent', 'Medium', 56, 180, 50, 'PUREPOWER', NULL, 'TELEPATHY', 'Humanlike', 5120, 0.6, 11.2, 'Blue', 'Bipedal', 'Mountain', 'Meditate', 'It continually meditates for hours every day. As a result of rigorous and dedicated yoga training, it has tempered its spiritual power so much it can fly.', '3', 'MEDICHAM,Level,37', '0307_Meditite'),
(308, 'MEDICHAM', 'Medicham', 'FIGHTING', 'PSYCHIC', 60, 60, 75, 60, 75, 80, 'Female50Percent', 'Medium', 144, 90, 50, 'PUREPOWER', NULL, 'TELEPATHY', 'Humanlike', 5120, 1.3, 31.5, 'Red', 'Bipedal', 'Mountain', 'Meditate', 'Through crushingly harsh yoga training, it gained the power to foretell its foe''s actions. It battles with elegant, dance- like movement.', '3', NULL, '0308_Medicham'),
(309, 'ELECTRIKE', 'Electrike', 'ELECTRIC', NULL, 40, 45, 40, 65, 40, 65, 'Female50Percent', 'Slow', 59, 120, 50, 'STATIC', 'LIGHTNINGROD', 'MINUS', 'Field', 5120, 0.6, 15.2, 'Green', 'Quadruped', 'Grassland', 'Lightning', 'It generates electricity using friction from the atmosphere. In seasons with especially arid air, its entire body blazes with violent showers of sparks.', '3', 'MANECTRIC,Level,26', '0309_Electrike'),
(310, 'MANECTRIC', 'Manectric', 'ELECTRIC', NULL, 70, 75, 60, 105, 60, 105, 'Female50Percent', 'Slow', 166, 45, 50, 'STATIC', 'LIGHTNINGROD', 'MINUS', 'Field', 5120, 1.5, 40.2, 'Yellow', 'Quadruped', 'Grassland', 'Discharge', 'Because lightning falls in their vicinities, Manectric were thought to have been born from lightning. In battle, they create thunderclouds.', '3', NULL, '0310_Manectric'),
(311, 'PLUSLE', 'Plusle', 'ELECTRIC', NULL, 60, 50, 40, 85, 75, 95, 'Female50Percent', 'Medium', 142, 200, 50, 'PLUS', NULL, 'LIGHTNINGROD', 'Fairy', 5120, 0.4, 4.2, 'Yellow', 'BipedalTail', 'Grassland', 'Cheering', 'It has the trait of cheering on its fellow Pokémon. By shorting out the electricity it releases from its paws, it creates pom-poms for cheering.', '3', NULL, '0311_Plusle'),
(312, 'MINUN', 'Minun', 'ELECTRIC', NULL, 60, 40, 50, 75, 85, 95, 'Female50Percent', 'Medium', 142, 200, 50, 'MINUS', NULL, 'VOLTABSORB', 'Fairy', 5120, 0.4, 4.2, 'Yellow', 'BipedalTail', 'Grassland', 'Cheering', 'At a meeting of Pokémon academics, it was announced that simultaneous exposure to electricity from a Plusle and Minun will promote circulation and boost vitality.', '3', NULL, '0312_Minun'),
(313, 'VOLBEAT', 'Volbeat', 'BUG', NULL, 65, 73, 75, 47, 85, 85, 'AlwaysMale', 'Erratic', 151, 150, 50, 'ILLUMINATE', 'SWARM', 'PRANKSTER', 'Bug,Humanlike', 3840, 0.7, 17.7, 'Gray', 'BipedalTail', 'Forest', 'Firefly', 'With their taillights lit, Volbeat fly in a swarm, drawing geometric designs in the night sky. They move their nests if their pond water becomes dirty.', '3', NULL, '0313_Volbeat'),
(314, 'ILLUMISE', 'Illumise', 'BUG', NULL, 65, 47, 75, 73, 85, 85, 'AlwaysFemale', 'Fluctuating', 151, 150, 50, 'OBLIVIOUS', 'TINTEDLENS', 'PRANKSTER', 'Bug,Humanlike', 3840, 0.6, 17.7, 'Purple', 'Bipedal', 'Forest', 'Firefly', 'A nocturnal Pokémon that becomes active upon nightfall. It leads a Volbeat swarm to draw patterns in the night sky. Over 200 different patterns have been seen.', '3', NULL, '0314_Illumise'),
(315, 'ROSELIA', 'Roselia', 'GRASS', 'POISON', 50, 60, 45, 100, 80, 65, 'Female50Percent', 'Parabolic', 140, 150, 50, 'NATURALCURE', 'POISONPOINT', 'LEAFGUARD', 'Fairy,Grass', 5120, 0.3, 2.0, 'Green', 'Bipedal', 'Grassland', 'Thorn', 'A Roselia that drinks nutritionally rich springwater blooms with lovely flowers. The fragrance of its flowers has the effect of making its foes careless.', '3', 'ROSERADE,Item,SHINYSTONE', '0315_Roselia'),
(316, 'GULPIN', 'Gulpin', 'POISON', NULL, 70, 43, 53, 43, 53, 40, 'Female50Percent', 'Fluctuating', 60, 225, 50, 'LIQUIDOOZE', 'STICKYHOLD', 'GLUTTONY', 'Amorphous', 5120, 0.4, 10.3, 'Green', 'HeadArms', 'Grassland', 'Stomach', 'This Pokémon''s stomach fluid can even digest scrap iron. In one gulp, it can swallow something that is as large as itself.', '3', 'SWALOT,Level,26', '0316_Gulpin'),
(317, 'SWALOT', 'Swalot', 'POISON', NULL, 100, 73, 83, 73, 83, 55, 'Female50Percent', 'Fluctuating', 163, 75, 50, 'LIQUIDOOZE', 'STICKYHOLD', 'GLUTTONY', 'Amorphous', 5120, 1.7, 80.0, 'Purple', 'HeadArms', 'Grassland', 'Poison Bag', 'Its powerful stomach acid is capable of digesting almost anything. The one thing in the whole world a Swalot can''t digest is its own stomach.', '3', NULL, '0317_Swalot'),
(318, 'CARVANHA', 'Carvanha', 'WATER', 'DARK', 45, 90, 20, 65, 20, 65, 'Female50Percent', 'Slow', 61, 225, 35, 'ROUGHSKIN', NULL, 'SPEEDBOOST', 'Water2', 5120, 0.8, 20.8, 'Red', 'Finned', 'Sea', 'Savage', 'Carvanha attack ships in swarms, making them sink. Although it is said to be a very vicious Pokémon, it timidly flees as soon as it finds itself alone.', '3', 'SHARPEDO,Level,30', '0318_Carvanha'),
(319, 'SHARPEDO', 'Sharpedo', 'WATER', 'DARK', 70, 120, 40, 95, 40, 95, 'Female50Percent', 'Slow', 161, 60, 35, 'ROUGHSKIN', NULL, 'SPEEDBOOST', 'Water2', 5120, 1.8, 88.8, 'Blue', 'Finned', 'Sea', 'Brutal', 'The vicious and sly gangster of the sea. Its skin is specially textured to minimize drag in water. Its speed tops out at over 75 miles per hour.', '3', NULL, '0319_Sharpedo'),
(320, 'WAILMER', 'Wailmer', 'WATER', NULL, 130, 70, 35, 70, 35, 60, 'Female50Percent', 'Fluctuating', 80, 125, 50, 'WATERVEIL', 'OBLIVIOUS', 'PRESSURE', 'Field,Water2', 10240, 2.0, 130.0, 'Blue', 'Finned', 'Sea', 'Ball Whale', 'While this Pokémon usually lives in the sea, it can survive on land, although not too long. It loses vitality if its body becomes dried out.', '3', 'WAILORD,Level,40', '0320_Wailmer');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(321, 'WAILORD', 'Wailord', 'WATER', NULL, 170, 90, 45, 90, 45, 60, 'Female50Percent', 'Fluctuating', 175, 60, 50, 'WATERVEIL', 'OBLIVIOUS', 'PRESSURE', 'Field,Water2', 10240, 14.5, 398.0, 'Blue', 'Finned', 'Sea', 'Float Whale', 'It breathes through nostrils that it raises above the sea. By inhaling to its maximum capacity, a Wailord can dive close to 10,000 feet beneath the waves.', '3', NULL, '0321_Wailord'),
(322, 'NUMEL', 'Numel', 'FIRE', 'GROUND', 60, 60, 40, 65, 45, 35, 'Female50Percent', 'Medium', 61, 255, 50, 'OBLIVIOUS', 'SIMPLE', 'OWNTEMPO', 'Field', 5120, 0.7, 24.0, 'Yellow', 'Quadruped', 'Mountain', 'Numb', 'A Numel stores boiling magma in the hump on its back. It is a hardy Pokémon that can transport a 220-pound load. It has served humans at work since long ago.', '3', 'CAMERUPT,Level,33', '0322_Numel'),
(323, 'CAMERUPT', 'Camerupt', 'FIRE', 'GROUND', 70, 100, 70, 105, 75, 40, 'Female50Percent', 'Medium', 161, 150, 50, 'MAGMAARMOR', 'SOLIDROCK', 'ANGERPOINT', 'Field', 5120, 1.9, 220.0, 'Red', 'Quadruped', 'Mountain', 'Eruption', 'A Pokémon that lives in the crater of a volcano. Every 10 years, the volcanoes on its back erupt violently. Research is under way on the cause of eruption.', '3', NULL, '0323_Camerupt'),
(324, 'TORKOAL', 'Torkoal', 'FIRE', NULL, 70, 85, 140, 85, 70, 20, 'Female50Percent', 'Medium', 165, 90, 50, 'WHITESMOKE', 'DROUGHT', 'SHELLARMOR', 'Field', 5120, 0.5, 80.4, 'Brown', 'Quadruped', 'Mountain', 'Coal', 'It battles using energy it gets from burning coal. When loosing smoke from its nostrils, it lets off a sound that is similar to a locomotive''s horn.', '3', NULL, '0324_Torkoal'),
(325, 'SPOINK', 'Spoink', 'PSYCHIC', NULL, 60, 25, 35, 70, 80, 60, 'Female50Percent', 'Fast', 66, 255, 50, 'THICKFAT', 'OWNTEMPO', 'GLUTTONY', 'Field', 5120, 0.7, 30.6, 'Black', 'HeadArms', 'Mountain', 'Bounce', 'A Pokémon that manipulates psychic power at will. It doesn''t stop bouncing even when it is asleep. It loves eating mushrooms that grow underground.', '3', 'GRUMPIG,Level,32', '0325_Spoink'),
(326, 'GRUMPIG', 'Grumpig', 'PSYCHIC', NULL, 80, 45, 65, 90, 110, 80, 'Female50Percent', 'Fast', 165, 60, 50, 'THICKFAT', 'OWNTEMPO', 'GLUTTONY', 'Field', 5120, 0.9, 71.5, 'Purple', 'BipedalTail', 'Mountain', 'Manipulate', 'It stores power in the black pearls on its forehead. When it uses psychic power, it performs an odd dance step. Its style of dancing became hugely popular overseas.', '3', NULL, '0326_Grumpig'),
(327, 'SPINDA', 'Spinda', 'NORMAL', NULL, 60, 60, 60, 60, 60, 60, 'Female50Percent', 'Fast', 126, 255, 50, 'OWNTEMPO', 'TANGLEDFEET', 'CONTRARY', 'Field,Humanlike', 3840, 1.1, 5.0, 'Brown', 'BipedalTail', 'Mountain', 'Spot Panda', 'It is distinguished by a pattern of spots that is always different. Its unsteady, tottering walk has the effect of fouling its foe''s aim.', '3', NULL, '0327_Spinda'),
(328, 'TRAPINCH', 'Trapinch', 'GROUND', NULL, 45, 100, 45, 45, 45, 10, 'Female50Percent', 'Parabolic', 58, 255, 50, 'HYPERCUTTER', 'ARENATRAP', 'SHEERFORCE', 'Bug,Dragon', 5120, 0.7, 15.0, 'Brown', 'Insectoid', 'RoughTerrain', 'Ant Pit', 'Its big jaws crunch through boulders. Because its head is so big, it has a hard time getting back upright if it tips over onto its back.', '3', 'VIBRAVA,Level,35', '0328_Trapinch'),
(329, 'VIBRAVA', 'Vibrava', 'GROUND', 'DRAGON', 50, 70, 50, 50, 50, 70, 'Female50Percent', 'Parabolic', 119, 120, 50, 'LEVITATE', NULL, NULL, 'Bug,Dragon', 5120, 1.1, 15.3, 'Green', 'MultiWinged', 'RoughTerrain', 'Vibration', 'It looses ultrasonic waves by rubbing its wings together. Since a Vibrava''s wings are still in the process of growing, it can only fly short distances.', '3', 'FLYGON,Level,45', '0329_Vibrava'),
(330, 'FLYGON', 'Flygon', 'GROUND', 'DRAGON', 80, 100, 80, 80, 80, 100, 'Female50Percent', 'Parabolic', 260, 45, 50, 'LEVITATE', NULL, NULL, 'Bug,Dragon', 5120, 2.0, 82.0, 'Green', 'Winged', 'RoughTerrain', 'Mystic', 'The flapping of its wings sounds like singing. To prevent detection by enemies, it hides itself by flapping up a cloud of desert sand.', '3', NULL, '0330_Flygon'),
(331, 'CACNEA', 'Cacnea', 'GRASS', NULL, 50, 85, 40, 85, 40, 35, 'Female50Percent', 'Parabolic', 67, 190, 35, 'SANDVEIL', NULL, 'WATERABSORB', 'Grass,Humanlike', 5120, 0.4, 51.3, 'Green', 'Bipedal', 'RoughTerrain', 'Cactus', 'Cacnea live in deserts with virtually no rainfall. It battles by swinging its thick, spiked arms. Once a year, a yellow flower blooms.', '3', 'CACTURNE,Level,32', '0331_Cacnea'),
(332, 'CACTURNE', 'Cacturne', 'GRASS', 'DARK', 70, 115, 60, 115, 60, 55, 'Female50Percent', 'Parabolic', 166, 60, 35, 'SANDVEIL', NULL, 'WATERABSORB', 'Grass,Humanlike', 5120, 1.3, 77.4, 'Green', 'Bipedal', 'RoughTerrain', 'Scarecrow', 'After spending thousands of years in harsh deserts, its blood transformed into the same substances as sand. It is nocturnal, so it hunts at night.', '3', NULL, '0332_Cacturne'),
(333, 'SWABLU', 'Swablu', 'NORMAL', 'FLYING', 45, 40, 60, 40, 75, 50, 'Female50Percent', 'Erratic', 62, 255, 50, 'NATURALCURE', NULL, 'CLOUDNINE', 'Flying,Dragon', 5120, 0.4, 1.2, 'Blue', 'Winged', 'Forest', 'Cotton Bird', 'A Pokémon that has wings like cottony clouds. After enduring winter, in which little food is available, Swablu flocks move closer to towns in the spring.', '3', 'ALTARIA,Level,35', '0333_Swablu'),
(334, 'ALTARIA', 'Altaria', 'DRAGON', 'FLYING', 75, 70, 90, 70, 105, 80, 'Female50Percent', 'Erratic', 172, 45, 50, 'NATURALCURE', NULL, 'CLOUDNINE', 'Flying,Dragon', 5120, 1.1, 20.6, 'Blue', 'Winged', 'Forest', 'Humming', 'It hums in a beautiful soprano voice. It flies among white clouds in the blue sky. It launches intensely hot fireballs from its mouth.', '3', NULL, '0334_Altaria'),
(335, 'ZANGOOSE', 'Zangoose', 'NORMAL', NULL, 73, 115, 60, 60, 60, 90, 'Female50Percent', 'Erratic', 160, 90, 50, 'IMMUNITY', NULL, 'TOXICBOOST', 'Field', 5120, 1.3, 40.3, 'White', 'BipedalTail', 'Grassland', 'Cat Ferret', 'When it battles, it stands on its hind legs and attacks with its sharply clawed forelegs. Its fur bristles if it encounters any Seviper.', '3', NULL, '0335_Zangoose'),
(336, 'SEVIPER', 'Seviper', 'POISON', NULL, 73, 100, 60, 100, 60, 65, 'Female50Percent', 'Fluctuating', 160, 90, 50, 'SHEDSKIN', NULL, 'INFILTRATOR', 'Field,Dragon', 5120, 2.7, 52.5, 'Black', 'Serpentine', 'Grassland', 'Fang Snake', 'Seviper and Zangoose are eternal rivals. It counters a Zangoose''s dazzling agility with its swordlike tail, which also oozes a horrible poison.', '3', NULL, '0336_Seviper'),
(337, 'LUNATONE', 'Lunatone', 'ROCK', 'PSYCHIC', 90, 55, 65, 95, 85, 70, 'Genderless', 'Fast', 161, 45, 50, 'LEVITATE', NULL, NULL, 'Mineral', 6400, 1.0, 168.0, 'Yellow', 'Head', 'Cave', 'Meteorite', 'It becomes very active on the night of a full moon. This Pokémon was first discovered 40 years ago at the site of a meteor strike.', '3', NULL, '0337_Lunatone'),
(338, 'SOLROCK', 'Solrock', 'ROCK', 'PSYCHIC', 90, 95, 85, 55, 65, 70, 'Genderless', 'Fast', 161, 45, 50, 'LEVITATE', NULL, NULL, 'Mineral', 6400, 1.2, 154.0, 'Red', 'Head', 'Cave', 'Meteorite', 'Solar energy is the source of this Pokémon''s power. On sunny days, groups of Solrock line up facing the sun and absorb its light.', '3', NULL, '0338_Solrock'),
(339, 'BARBOACH', 'Barboach', 'WATER', 'GROUND', 50, 48, 43, 46, 41, 60, 'Female50Percent', 'Medium', 58, 190, 50, 'OBLIVIOUS', 'ANTICIPATION', 'HYDRATION', 'Water2', 5120, 0.4, 1.9, 'Gray', 'Finned', 'WatersEdge', 'Whiskers', 'Its body is covered with a slimy film. The film acts as a barrier to prevent germs in muddy water from entering the Barboach''s body.', '3', 'WHISCASH,Level,30', '0339_Barboach'),
(340, 'WHISCASH', 'Whiscash', 'WATER', 'GROUND', 110, 78, 73, 76, 71, 60, 'Female50Percent', 'Medium', 164, 75, 50, 'OBLIVIOUS', 'ANTICIPATION', 'HYDRATION', 'Water2', 5120, 0.9, 23.6, 'Blue', 'Finned', 'WatersEdge', 'Whiskers', 'Mysteriously, it can foretell earthquakes. In the daytime, it sleeps in mud at the bottom of a pond. When it awakens, it continually feeds throughout the night.', '3', NULL, '0340_Whiscash'),
(341, 'CORPHISH', 'Corphish', 'WATER', NULL, 43, 80, 65, 50, 35, 35, 'Female50Percent', 'Fluctuating', 62, 205, 50, 'HYPERCUTTER', 'SHELLARMOR', 'ADAPTABILITY', 'Water1,Water3', 3840, 0.6, 11.5, 'Red', 'Insectoid', 'WatersEdge', 'Ruffian', 'Once it grips prey with its large pincers, it will never let go, no matter what. It is a hardy Pokémon that can thrive in any environment.', '3', 'CRAWDAUNT,Level,30', '0341_Corphish'),
(342, 'CRAWDAUNT', 'Crawdaunt', 'WATER', 'DARK', 63, 120, 85, 90, 55, 55, 'Female50Percent', 'Fluctuating', 164, 155, 50, 'HYPERCUTTER', 'SHELLARMOR', 'ADAPTABILITY', 'Water1,Water3', 3840, 1.1, 32.8, 'Red', 'Insectoid', 'WatersEdge', 'Rogue', 'A brutish Pokémon that loves to battle. A veteran Crawdaunt that has prevailed in hundreds of battles has giant pincers marked with countless scars.', '3', NULL, '0342_Crawdaunt'),
(343, 'BALTOY', 'Baltoy', 'GROUND', 'PSYCHIC', 40, 40, 55, 40, 70, 55, 'Genderless', 'Medium', 60, 255, 50, 'LEVITATE', NULL, NULL, 'Mineral', 5120, 0.5, 21.5, 'Brown', 'HeadArms', 'RoughTerrain', 'Clay Doll', 'A Baltoy moves by spinning on its single foot. It has been depicted in murals adorning the walls of a once-bustling city in an ancient age.', '3', 'CLAYDOL,Level,36', '0343_Baltoy'),
(344, 'CLAYDOL', 'Claydol', 'GROUND', 'PSYCHIC', 60, 70, 105, 70, 120, 75, 'Genderless', 'Medium', 175, 90, 50, 'LEVITATE', NULL, NULL, 'Mineral', 5120, 1.5, 108.0, 'Black', 'HeadArms', 'RoughTerrain', 'Clay Doll', 'A Claydol sleeps while hovering in midair. Its arms are separate from its body. They are kept floating by the Pokémon''s manipulation of psychic power.', '3', NULL, '0344_Claydol'),
(345, 'LILEEP', 'Lileep', 'ROCK', 'GRASS', 66, 41, 77, 61, 87, 23, 'FemaleOneEighth', 'Erratic', 71, 45, 50, 'SUCTIONCUPS', NULL, 'STORMDRAIN', 'Water3', 7680, 1.0, 23.8, 'Purple', 'HeadBase', 'Sea', 'Sea Lily', 'It disguises itself as seaweed by making its tentacles sway. Unsuspecting prey that come too close are swallowed whole. It became extinct 100 million years ago.', '3', 'CRADILY,Level,40', '0345_Lileep'),
(346, 'CRADILY', 'Cradily', 'ROCK', 'GRASS', 86, 81, 97, 81, 107, 43, 'FemaleOneEighth', 'Erratic', 173, 45, 50, 'SUCTIONCUPS', NULL, 'STORMDRAIN', 'Water3', 7680, 1.5, 60.4, 'Green', 'HeadBase', 'Sea', 'Barnacle', 'It drags its heavy body along the seafloor. It makes its nest in the shallows of warm seas. Cradily can be seen on beaches when the tide goes out.', '3', NULL, '0346_Cradily'),
(347, 'ANORITH', 'Anorith', 'ROCK', 'BUG', 45, 95, 50, 40, 50, 75, 'FemaleOneEighth', 'Erratic', 71, 45, 50, 'BATTLEARMOR', NULL, 'SWIFTSWIM', 'Water3', 7680, 0.7, 12.5, 'Gray', 'Insectoid', 'WatersEdge', 'Old Shrimp', 'It was resurrected from a fossil using the power of science. It swims by undulating the wings at its sides. They were feet that adapted to life in the sea.', '3', 'ARMALDO,Level,40', '0347_Anorith'),
(348, 'ARMALDO', 'Armaldo', 'ROCK', 'BUG', 75, 125, 100, 70, 80, 45, 'FemaleOneEighth', 'Erratic', 173, 45, 50, 'BATTLEARMOR', NULL, 'SWIFTSWIM', 'Water3', 7680, 1.5, 68.2, 'Gray', 'BipedalTail', 'WatersEdge', 'Plate', 'Armaldo usually lives on land. However, when it hunts for prey, it dives beneath the ocean. It swims around using its two large wings.', '3', NULL, '0348_Armaldo'),
(349, 'FEEBAS', 'Feebas', 'WATER', NULL, 20, 15, 20, 10, 55, 80, 'Female50Percent', 'Erratic', 40, 255, 50, 'SWIFTSWIM', 'OBLIVIOUS', 'ADAPTABILITY', 'Water1,Dragon', 5120, 0.6, 7.4, 'Brown', 'Finned', 'WatersEdge', 'Fish', 'Feebas live in ponds that are heavily infested with weeds. Because of its hopelessly shabby appearance, it seems as if few trainers raise it.', '3', 'MILOTIC,TradeItem,PRISMSCALE,MILOTIC,Beauty,170', '0349_Feebas'),
(350, 'MILOTIC', 'Milotic', 'WATER', NULL, 95, 60, 79, 100, 125, 81, 'Female50Percent', 'Erratic', 189, 60, 50, 'MARVELSCALE', 'COMPETITIVE', 'CUTECHARM', 'Water1,Dragon', 5120, 6.2, 162.0, 'Pink', 'Serpentine', 'WatersEdge', 'Tender', 'It is said to live at the bottom of large lakes. Considered to be the most beautiful of all Pokémon, it has been depicted in paintings and statues.', '3', NULL, '0350_Milotic'),
(351, 'CASTFORM', 'Castform', 'NORMAL', NULL, 70, 70, 70, 70, 70, 70, 'Female50Percent', 'Medium', 147, 45, 50, 'FORECAST', NULL, NULL, 'Fairy,Amorphous', 6400, 0.3, 0.8, 'Gray', 'Head', 'Grassland', 'Weather', 'It alters its form depending on the weather. Changes in the climate such as the temperature and humidity appear to affect its cellular structure.', '3', NULL, '0351_Castform'),
(352, 'KECLEON', 'Kecleon', 'NORMAL', NULL, 60, 90, 70, 60, 120, 40, 'Female50Percent', 'Parabolic', 154, 200, 50, 'COLORCHANGE', NULL, 'PROTEAN', 'Field', 5120, 1.0, 22.0, 'Green', 'BipedalTail', 'Forest', 'Color Swap', 'A Pokémon that has the ability to alter its body colors to match its surroundings. A Kecleon reverts to its original colors if it is startled.', '3', NULL, '0352_Kecleon'),
(353, 'SHUPPET', 'Shuppet', 'GHOST', NULL, 44, 75, 35, 63, 33, 45, 'Female50Percent', 'Fast', 59, 225, 35, 'INSOMNIA', 'FRISK', 'CURSEDBODY', 'Amorphous', 6400, 0.6, 2.3, 'Black', 'Head', 'Urban', 'Puppet', 'This Pokémon roams about deep in the night seeking such negative emotions as grudges and envy. It retreats to its nest when the sun begins to rise.', '3', 'BANETTE,Level,37', '0353_Shuppet'),
(354, 'BANETTE', 'Banette', 'GHOST', NULL, 64, 115, 65, 83, 63, 65, 'Female50Percent', 'Fast', 159, 45, 35, 'INSOMNIA', 'FRISK', 'CURSEDBODY', 'Amorphous', 6400, 1.1, 12.5, 'Black', 'BipedalTail', 'Urban', 'Marionette', 'An abandoned plush doll became this Pokémon. They are said to live in garbage dumps and wander about in search of the children that threw them away.', '3', NULL, '0354_Banette'),
(355, 'DUSKULL', 'Duskull', 'GHOST', NULL, 20, 40, 90, 30, 90, 25, 'Female50Percent', 'Fast', 59, 190, 35, 'LEVITATE', NULL, 'FRISK', 'Amorphous', 6400, 0.8, 15.0, 'Black', 'HeadArms', 'Forest', 'Requiem', 'A glare from its single scarlet eye makes even burly grown-ups freeze in utter fear. It is a nocturnal Pokémon that roams about under the cloak of darkness.', '3', 'DUSCLOPS,Level,37', '0355_Duskull'),
(356, 'DUSCLOPS', 'Dusclops', 'GHOST', NULL, 40, 70, 130, 60, 130, 25, 'Female50Percent', 'Fast', 159, 90, 35, 'PRESSURE', NULL, 'FRISK', 'Amorphous', 6400, 1.6, 30.6, 'Black', 'Bipedal', 'Forest', 'Beckon', 'It is thought that its body is hollow with only a spectral ball of fire burning inside. However, no one has been able to confirm this theory as fact.', '3', 'DUSKNOIR,TradeItem,REAPERCLOTH', '0356_Dusclops'),
(357, 'TROPIUS', 'Tropius', 'GRASS', 'FLYING', 99, 68, 83, 72, 87, 51, 'Female50Percent', 'Slow', 161, 200, 50, 'CHLOROPHYLL', 'SOLARPOWER', 'HARVEST', 'Monster,Grass', 6400, 2.0, 100.0, 'Green', 'Quadruped', 'Forest', 'Fruit', 'It flies by flapping its broad leaves. The bunch of fruit that grows around its neck is deliciously sweet. In the spring, it scatters pollen from its neck.', '3', NULL, '0357_Tropius'),
(358, 'CHIMECHO', 'Chimecho', 'PSYCHIC', NULL, 75, 50, 80, 95, 90, 65, 'Female50Percent', 'Fast', 159, 45, 50, 'LEVITATE', NULL, NULL, 'Amorphous', 6400, 0.6, 1.0, 'Blue', 'HeadArms', 'Grassland', 'Wind Chime', 'They fly about very actively when the hot season arrives. They communicate among themselves using seven different and distinguishing cries.', '3', NULL, '0358_Chimecho'),
(359, 'ABSOL', 'Absol', 'DARK', NULL, 65, 130, 60, 75, 60, 75, 'Female50Percent', 'Parabolic', 163, 30, 35, 'PRESSURE', 'SUPERLUCK', 'JUSTIFIED', 'Field', 6400, 1.2, 47.0, 'White', 'Quadruped', 'Mountain', 'Disaster', 'It sharply senses even subtle changes in the sky and the land to predict natural disasters. It is a long-lived Pokémon that has a life-span of 100 years.', '3', NULL, '0359_Absol'),
(360, 'WYNAUT', 'Wynaut', 'PSYCHIC', NULL, 95, 23, 48, 23, 48, 23, 'Female50Percent', 'Medium', 52, 125, 50, 'SHADOWTAG', NULL, 'TELEPATHY', 'Undiscovered', 5120, 0.6, 14.0, 'Blue', 'BipedalTail', 'Cave', 'Bright', 'A Wynaut loves to eat sweet fruits. It cleverly picks fruits using its earlike arms. They gather in fruit gardens, drawn by the fragrance.', '3', 'WOBBUFFET,Level,15', '0360_Wynaut'),
(361, 'SNORUNT', 'Snorunt', 'ICE', NULL, 50, 50, 50, 50, 50, 50, 'Female50Percent', 'Medium', 60, 190, 50, 'INNERFOCUS', 'ICEBODY', 'MOODY', 'Fairy,Mineral', 5120, 0.7, 16.8, 'Gray', 'Bipedal', 'Cave', 'Snow Hat', 'They tend to move about in groups of around five Snorunt. In snowy regions, it is said that when they are seen late at night, snowfall will arrive by morning.', '3', 'GLALIE,Level,42,FROSLASS,ItemFemale,DAWNSTONE', '0361_Snorunt'),
(362, 'GLALIE', 'Glalie', 'ICE', NULL, 80, 80, 80, 80, 80, 80, 'Female50Percent', 'Medium', 168, 75, 50, 'INNERFOCUS', 'ICEBODY', 'MOODY', 'Fairy,Mineral', 5120, 1.5, 256.5, 'Gray', 'Head', 'Cave', 'Face', 'A Glalie has the power to instantaneously freeze moisture in the atmosphere. A dazzling cloud of diamondlike ice crystals forms around its body.', '3', NULL, '0362_Glalie'),
(363, 'SPHEAL', 'Spheal', 'ICE', 'WATER', 70, 40, 50, 55, 50, 25, 'Female50Percent', 'Parabolic', 58, 255, 50, 'THICKFAT', 'ICEBODY', 'OBLIVIOUS', 'Water1,Field', 5120, 0.8, 39.5, 'Blue', 'Finned', 'Sea', 'Clap', 'It is completely covered with plushy fur. As a result, it never feels the cold even when it is rolling about on ice floes or diving in the sea.', '3', 'SEALEO,Level,32', '0363_Spheal'),
(364, 'SEALEO', 'Sealeo', 'ICE', 'WATER', 90, 60, 70, 75, 70, 45, 'Female50Percent', 'Parabolic', 144, 120, 50, 'THICKFAT', 'ICEBODY', 'OBLIVIOUS', 'Water1,Field', 5120, 1.1, 87.6, 'Blue', 'Finned', 'Sea', 'Ball Roll', 'Sealeo live in herds on ice floes. Using its powerful flippers, it shatters ice. It dives into the sea to hunt prey five times a day.', '3', 'WALREIN,Level,44', '0364_Sealeo'),
(365, 'WALREIN', 'Walrein', 'ICE', 'WATER', 110, 80, 90, 95, 90, 65, 'Female50Percent', 'Parabolic', 265, 45, 50, 'THICKFAT', 'ICEBODY', 'OBLIVIOUS', 'Water1,Field', 5120, 1.4, 150.6, 'Blue', 'Quadruped', 'Sea', 'Ice Break', 'To protect its herd, the leader battles anything that invades its territory, even at the cost of its life. Its tusks may snap off in battle.', '3', NULL, '0365_Walrein'),
(366, 'CLAMPERL', 'Clamperl', 'WATER', NULL, 35, 64, 85, 74, 55, 32, 'Female50Percent', 'Erratic', 69, 255, 50, 'SHELLARMOR', NULL, 'RATTLED', 'Water1', 5120, 0.4, 52.5, 'Blue', 'Head', 'Sea', 'Bivalve', 'A Clamperl slams its shell closed on prey to prevent escape. The pearl it creates upon evolution is said to be infused with a mysterious energy.', '3', 'HUNTAIL,TradeItem,DEEPSEATOOTH,GOREBYSS,TradeItem,DEEPSEASCALE', '0366_Clamperl'),
(367, 'HUNTAIL', 'Huntail', 'WATER', NULL, 55, 104, 105, 94, 75, 52, 'Female50Percent', 'Erratic', 170, 60, 50, 'SWIFTSWIM', NULL, 'WATERVEIL', 'Water1', 5120, 1.7, 27.0, 'Blue', 'Serpentine', 'Sea', 'Deep Sea', 'To withstand the crushing water pressure deep under the sea, its spine is very thick and sturdy. Its tail, which is shaped like a small fish, has eyes that light up.', '3', NULL, '0367_Huntail'),
(368, 'GOREBYSS', 'Gorebyss', 'WATER', NULL, 55, 84, 105, 114, 75, 52, 'Female50Percent', 'Erratic', 170, 60, 50, 'SWIFTSWIM', NULL, 'HYDRATION', 'Water1', 5120, 1.8, 22.6, 'Pink', 'Serpentine', 'Sea', 'South Sea', 'A Gorebyss siphons the body fluids of prey through its thin, tubular mouth. Its light pink body color turns vivid when it finishes feeding.', '3', NULL, '0368_Gorebyss'),
(369, 'RELICANTH', 'Relicanth', 'WATER', 'ROCK', 100, 90, 130, 45, 65, 55, 'FemaleOneEighth', 'Slow', 170, 25, 50, 'SWIFTSWIM', 'ROCKHEAD', 'STURDY', 'Water1,Water2', 10240, 1.0, 23.4, 'Gray', 'Finned', 'Sea', 'Longevity', 'A Pokémon that was once believed to be extinct. The species has not changed its form for 100 million years. It walks on the seafloor using its pectoral fins.', '3', NULL, '0369_Relicanth'),
(370, 'LUVDISC', 'Luvdisc', 'WATER', NULL, 43, 30, 55, 40, 65, 97, 'Female75Percent', 'Fast', 116, 225, 50, 'SWIFTSWIM', NULL, 'HYDRATION', 'Water2', 5120, 0.6, 8.7, 'Pink', 'Finned', 'Sea', 'Rendezvous', 'Luvdisc make the branches of Corsola their nests. There is a custom from long ago of giving a Luvdisc as a gift to express one''s feelings of love.', '3', NULL, '0370_Luvdisc'),
(371, 'BAGON', 'Bagon', 'DRAGON', NULL, 45, 75, 60, 40, 30, 50, 'Female50Percent', 'Slow', 60, 45, 35, 'ROCKHEAD', NULL, 'SHEERFORCE', 'Dragon', 10240, 0.6, 42.1, 'Blue', 'Bipedal', 'RoughTerrain', 'Rock Head', 'Although it is small, this Pokémon is very powerful because its body is a bundle of muscles. It launches head-butts with its ironlike skull.', '3', 'SHELGON,Level,30', '0371_Bagon'),
(372, 'SHELGON', 'Shelgon', 'DRAGON', NULL, 65, 95, 100, 60, 50, 50, 'Female50Percent', 'Slow', 147, 45, 35, 'ROCKHEAD', NULL, 'OVERCOAT', 'Dragon', 10240, 1.1, 110.5, 'White', 'Quadruped', 'RoughTerrain', 'Endurance', 'It hardly eats while it awaits evolution. It becomes hardier by enduring hunger. Its shell peels off the instant it begins to evolve.', '3', 'SALAMENCE,Level,50', '0372_Shelgon'),
(373, 'SALAMENCE', 'Salamence', 'DRAGON', 'FLYING', 95, 135, 80, 110, 80, 100, 'Female50Percent', 'Slow', 300, 45, 35, 'INTIMIDATE', NULL, 'MOXIE', 'Dragon', 10240, 1.5, 102.6, 'Blue', 'Quadruped', 'RoughTerrain', 'Dragon', 'After many long years, its cellular structure underwent a sudden mutation to grow wings. When angered, it loses all thought and rampages out of control.', '3', NULL, '0373_Salamence'),
(374, 'BELDUM', 'Beldum', 'STEEL', 'PSYCHIC', 40, 55, 80, 35, 60, 30, 'Genderless', 'Slow', 60, 3, 35, 'CLEARBODY', NULL, 'LIGHTMETAL', 'Mineral', 10240, 0.6, 95.2, 'Blue', 'HeadBase', 'RoughTerrain', 'Iron Ball', 'When Beldum gather in a swarm, they move in perfect unison as if they were but one Pokémon. They communicate with each other using brain waves.', '3', 'METANG,Level,20', '0374_Beldum'),
(375, 'METANG', 'Metang', 'STEEL', 'PSYCHIC', 60, 75, 100, 55, 80, 50, 'Genderless', 'Slow', 147, 3, 35, 'CLEARBODY', NULL, 'LIGHTMETAL', 'Mineral', 10240, 1.2, 202.5, 'Blue', 'HeadArms', 'RoughTerrain', 'Iron Claw', 'The claws tipping its arms pack the destructive power to tear through thick iron sheets as if they were silk. It flies at over 60 miles per hour.', '3', 'METAGROSS,Level,45', '0375_Metang'),
(376, 'METAGROSS', 'Metagross', 'STEEL', 'PSYCHIC', 80, 135, 130, 95, 90, 70, 'Genderless', 'Slow', 300, 3, 35, 'CLEARBODY', NULL, 'LIGHTMETAL', 'Mineral', 10240, 1.6, 550.0, 'Blue', 'MultiBody', 'RoughTerrain', 'Iron Leg', 'Metagross has four brains that are joined by a complex neural network. As a result of integration, this Pokémon is smarter than a supercomputer.', '3', NULL, '0376_Metagross'),
(377, 'REGIROCK', 'Regirock', 'ROCK', NULL, 80, 100, 200, 50, 100, 50, 'Genderless', 'Slow', 290, 3, 35, 'CLEARBODY', NULL, 'STURDY', 'Undiscovered', 20480, 1.7, 230.0, 'Brown', 'Bipedal', 'Cave', 'Rock Peak', 'A Pokémon that is made entirely of rocks and boulders. If parts of its body chip off in battle, Regirock repairs itself by adding new rocks.', '3', NULL, '0377_Regirock'),
(378, 'REGICE', 'Regice', 'ICE', NULL, 80, 50, 100, 100, 200, 50, 'Genderless', 'Slow', 290, 3, 35, 'CLEARBODY', NULL, 'ICEBODY', 'Undiscovered', 20480, 1.8, 175.0, 'Blue', 'Bipedal', 'Cave', 'Iceberg', 'Its entire body is made of Antarctic ice. After extensive studies, researchers believe the ice was formed during an ice age.', '3', NULL, '0378_Regice'),
(379, 'REGISTEEL', 'Registeel', 'STEEL', NULL, 80, 75, 150, 75, 150, 50, 'Genderless', 'Slow', 290, 3, 35, 'CLEARBODY', NULL, 'LIGHTMETAL', 'Undiscovered', 20480, 1.9, 205.0, 'Gray', 'Bipedal', 'Cave', 'Iron', 'Its body is harder than any other kind of metal. The body metal is composed of a mysterious substance. Not only is it hard, it shrinks and stretches flexibly.', '3', NULL, '0379_Registeel'),
(380, 'LATIAS', 'Latias', 'DRAGON', 'PSYCHIC', 80, 80, 90, 110, 130, 110, 'AlwaysFemale', 'Slow', 300, 3, 90, 'LEVITATE', NULL, NULL, 'Undiscovered', 30720, 1.4, 40.0, 'Red', 'Winged', 'WatersEdge', 'Eon', 'They make a small herd of only several members. They rarely make contact with people or other Pokémon. They disappear if they sense enemies.', '3', NULL, '0380_Latias'),
(381, 'LATIOS', 'Latios', 'DRAGON', 'PSYCHIC', 80, 90, 80, 130, 110, 110, 'AlwaysMale', 'Slow', 300, 3, 90, 'LEVITATE', NULL, NULL, 'Undiscovered', 30720, 2.0, 60.0, 'Blue', 'Winged', 'WatersEdge', 'Eon', 'Even in hiding, it can detect the locations of others and sense their emotions since it has telepathy. Its intelligence allows it to understand human languages.', '3', NULL, '0381_Latios'),
(382, 'KYOGRE', 'Kyogre', 'WATER', NULL, 100, 100, 90, 150, 140, 90, 'Genderless', 'Slow', 335, 3, 0, 'DRIZZLE', NULL, NULL, 'Undiscovered', 30720, 4.5, 352.0, 'Blue', 'Finned', 'Sea', 'Sea Basin', 'Kyogre has appeared in mythology as the creator of the sea. After long years of feuding with Groudon, it took to sleep at the bottom of the sea.', '3', NULL, '0382_Kyogre'),
(383, 'GROUDON', 'Groudon', 'GROUND', NULL, 100, 150, 140, 100, 90, 90, 'Genderless', 'Slow', 335, 3, 0, 'DROUGHT', NULL, NULL, 'Undiscovered', 30720, 3.5, 950.0, 'Red', 'BipedalTail', 'RoughTerrain', 'Continent', 'Groudon has appeared in mythology as the creator of the land. It sleeps in magma underground and is said to make volcanoes erupt on awakening.', '3', NULL, '0383_Groudon'),
(384, 'RAYQUAZA', 'Rayquaza', 'DRAGON', 'FLYING', 105, 150, 90, 150, 90, 95, 'Genderless', 'Slow', 340, 45, 0, 'AIRLOCK', NULL, NULL, 'Undiscovered', 30720, 7.0, 206.5, 'Green', 'Serpentine', 'Rare', 'Sky High', 'A Pokémon that flies endlessly in the ozone layer. It is said it would descend to the ground if Kyogre and Groudon were to fight.', '3', NULL, '0384_Rayquaza'),
(385, 'JIRACHI', 'Jirachi', 'STEEL', 'PSYCHIC', 100, 100, 100, 100, 100, 100, 'Genderless', 'Slow', 300, 3, 100, 'SERENEGRACE', NULL, NULL, 'Undiscovered', 30720, 0.3, 1.1, 'Yellow', 'Bipedal', 'Mountain', 'Wish', 'Jirachi is said to make wishes come true. While it sleeps, a tough crystalline shell envelops the body to protect it from enemies.', '3', NULL, '0385_Jirachi'),
(386, 'DEOXYS', 'Deoxys', 'PSYCHIC', NULL, 50, 150, 50, 150, 50, 150, 'Genderless', 'Slow', 300, 3, 0, 'PRESSURE', NULL, NULL, 'Undiscovered', 30720, 1.7, 60.8, 'Red', 'Bipedal', 'Rare', 'DNA', 'A Pokémon that mutated from an extraterrestrial virus exposed to a laser beam. Its body is configured for superior agility and speed.', '3', NULL, '0386_Deoxys'),
(387, 'TURTWIG', 'Turtwig', 'GRASS', NULL, 55, 68, 64, 45, 55, 31, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'OVERGROW', NULL, 'SHELLARMOR', 'Monster,Grass', 5120, 0.4, 10.2, 'Green', 'Quadruped', NULL, 'Tiny Leaf', 'Made from soil, the shell on its back hardens when it drinks water. It lives along lakes.', '4', 'GROTLE,Level,18', '0387_Turtwig'),
(388, 'GROTLE', 'Grotle', 'GRASS', NULL, 75, 89, 85, 55, 65, 36, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'OVERGROW', NULL, 'SHELLARMOR', 'Monster,Grass', 5120, 1.1, 97.0, 'Green', 'Quadruped', NULL, 'Grove', 'It lives along water in forests. In the daytime, it leaves the forest to sunbathe its treed shell.', '4', 'TORTERRA,Level,32', '0388_Grotle'),
(389, 'TORTERRA', 'Torterra', 'GRASS', 'GROUND', 95, 109, 105, 75, 85, 56, 'FemaleOneEighth', 'Parabolic', 263, 45, 50, 'OVERGROW', NULL, 'SHELLARMOR', 'Monster,Grass', 5120, 2.2, 310.0, 'Green', 'Quadruped', NULL, 'Continent', 'Small Pokémon occasionally gather on its unmoving back to begin building their nests.', '4', NULL, '0389_Torterra'),
(390, 'CHIMCHAR', 'Chimchar', 'FIRE', NULL, 44, 58, 44, 58, 44, 61, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'IRONFIST', 'Field,Humanlike', 5120, 0.5, 6.2, 'Brown', 'BipedalTail', NULL, 'Chimp', 'It agilely scales sheer cliffs to live atop craggy mountains. Its fire is put out when it sleeps.', '4', 'MONFERNO,Level,14', '0390_Chimchar'),
(391, 'MONFERNO', 'Monferno', 'FIRE', 'FIGHTING', 64, 78, 52, 78, 52, 81, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'BLAZE', NULL, 'IRONFIST', 'Field,Humanlike', 5120, 0.9, 22.0, 'Brown', 'BipedalTail', NULL, 'Playful', 'To intimidate attackers, it stretches the fire on its tail to make itself appear bigger.', '4', 'INFERNAPE,Level,36', '0391_Monferno'),
(392, 'INFERNAPE', 'Infernape', 'FIRE', 'FIGHTING', 76, 104, 71, 104, 71, 108, 'FemaleOneEighth', 'Parabolic', 267, 45, 50, 'BLAZE', NULL, 'IRONFIST', 'Field,Humanlike', 5120, 1.2, 55.0, 'Brown', 'BipedalTail', NULL, 'Flame', 'It uses a special kind of martial arts involving all its limbs. Its fire never goes out.', '4', NULL, '0392_Infernape'),
(393, 'PIPLUP', 'Piplup', 'WATER', NULL, 53, 51, 53, 61, 56, 40, 'FemaleOneEighth', 'Parabolic', 63, 45, 50, 'TORRENT', NULL, 'DEFIANT', 'Water1,Field', 5120, 0.4, 5.2, 'Blue', 'Bipedal', NULL, 'Penguin', 'Because it is very proud, it hates accepting food from people. Its thick down guards it from cold.', '4', 'PRINPLUP,Level,16', '0393_Piplup'),
(394, 'PRINPLUP', 'Prinplup', 'WATER', NULL, 64, 66, 68, 81, 76, 50, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'TORRENT', NULL, 'DEFIANT', 'Water1,Field', 5120, 0.8, 23.0, 'Blue', 'BipedalTail', NULL, 'Penguin', 'It lives alone, away from others. Apparently, every one of them believes it is the most important.', '4', 'EMPOLEON,Level,36', '0394_Prinplup'),
(395, 'EMPOLEON', 'Empoleon', 'WATER', 'STEEL', 84, 86, 88, 111, 101, 60, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'DEFIANT', 'Water1,Field', 5120, 1.7, 84.5, 'Blue', 'BipedalTail', NULL, 'Emperor', 'The three horns that extend from its beak attest to its power. The leader has the biggest horns.', '4', NULL, '0395_Empoleon'),
(396, 'STARLY', 'Starly', 'NORMAL', 'FLYING', 40, 55, 30, 30, 30, 60, 'Female50Percent', 'Parabolic', 49, 255, 50, 'KEENEYE', NULL, 'RECKLESS', 'Flying', 3840, 0.3, 2.0, 'Brown', 'Winged', NULL, 'Starling', 'They flock in great numbers. Though small, they flap their wings with great power.', '4', 'STARAVIA,Level,14', '0396_Starly'),
(397, 'STARAVIA', 'Staravia', 'NORMAL', 'FLYING', 55, 75, 50, 40, 40, 80, 'Female50Percent', 'Parabolic', 119, 120, 50, 'INTIMIDATE', NULL, 'RECKLESS', 'Flying', 3840, 0.6, 15.5, 'Brown', 'Winged', NULL, 'Starling', 'It flies around forests and fields in search of bug Pokémon. It stays within a huge flock.', '4', 'STARAPTOR,Level,34', '0397_Staravia'),
(398, 'STARAPTOR', 'Staraptor', 'NORMAL', 'FLYING', 85, 120, 70, 50, 60, 100, 'Female50Percent', 'Parabolic', 243, 45, 50, 'INTIMIDATE', NULL, 'RECKLESS', 'Flying', 3840, 1.2, 24.9, 'Brown', 'Winged', NULL, 'Predator', 'It has a savage nature. It will courageously challenge foes that are much larger.', '4', NULL, '0398_Staraptor'),
(399, 'BIDOOF', 'Bidoof', 'NORMAL', NULL, 59, 45, 40, 35, 40, 31, 'Female50Percent', 'Medium', 50, 255, 50, 'SIMPLE', 'UNAWARE', 'MOODY', 'Water1,Field', 3840, 0.5, 20.0, 'Brown', 'Quadruped', NULL, 'Plump Mouse', 'With nerves of steel, nothing can perturb it. It is more agile and active than it appears.', '4', 'BIBAREL,Level,15', '0399_Bidoof'),
(400, 'BIBAREL', 'Bibarel', 'NORMAL', 'WATER', 79, 85, 60, 55, 60, 71, 'Female50Percent', 'Medium', 144, 127, 50, 'SIMPLE', 'UNAWARE', 'MOODY', 'Water1,Field', 3840, 1.0, 31.5, 'Brown', 'BipedalTail', NULL, 'Beaver', 'It makes its nest by damming streams with bark and mud. It is known as an industrious worker.', '4', NULL, '0400_Bibarel');
