(401, 'KRICKETOT', 'Kricketot', 'BUG', NULL, 37, 25, 41, 25, 41, 25, 'Female50Percent', 'Parabolic', 39, 255, 50, 'SHEDSKIN', NULL, 'RUNAWAY', 'Bug', 3840, 0.3, 2.2, 'Red', 'Bipedal', NULL, 'Cricket', 'It shakes its head back to front, causing its antennae to hit each other and sound like a xylophone.', '4', 'KRICKETUNE,Level,10', '0401_Kricketot'),
(402, 'KRICKETUNE', 'Kricketune', 'BUG', NULL, 77, 85, 51, 55, 51, 65, 'Female50Percent', 'Parabolic', 134, 45, 50, 'SWARM', NULL, 'TECHNICIAN', 'Bug', 3840, 1.0, 25.5, 'Red', 'MultiWinged', NULL, 'Cricket', 'It crosses its knifelike arms in front of its chest when it cries. It can compose melodies ad lib.', '4', NULL, '0402_Kricketune'),
(403, 'SHINX', 'Shinx', 'ELECTRIC', NULL, 45, 65, 34, 40, 34, 45, 'Female50Percent', 'Parabolic', 53, 235, 50, 'RIVALRY', 'INTIMIDATE', 'GUTS', 'Field', 5120, 0.5, 9.5, 'Blue', 'Quadruped', NULL, 'Flash', 'All of its fur dazzles if danger is sensed. It flees while the foe is momentarily blinded.', '4', 'LUXIO,Level,15', '0403_Shinx'),
(404, 'LUXIO', 'Luxio', 'ELECTRIC', NULL, 60, 85, 49, 60, 49, 60, 'Female50Percent', 'Parabolic', 127, 120, 100, 'RIVALRY', 'INTIMIDATE', 'GUTS', 'Field', 5120, 0.9, 30.5, 'Blue', 'Quadruped', NULL, 'Spark', 'Its claws loose electricity with enough amperage to cause fainting. They live in small groups.', '4', 'LUXRAY,Level,30', '0404_Luxio'),
(405, 'LUXRAY', 'Luxray', 'ELECTRIC', NULL, 80, 120, 79, 95, 79, 70, 'Female50Percent', 'Parabolic', 262, 45, 50, 'RIVALRY', 'INTIMIDATE', 'GUTS', 'Field', 5120, 1.4, 42.0, 'Blue', 'Quadruped', NULL, 'Gleam Eyes', 'It has eyes that can see through anything. It spots and captures prey hiding behind objects.', '4', NULL, '0405_Luxray'),
(406, 'BUDEW', 'Budew', 'GRASS', 'POISON', 40, 30, 35, 50, 70, 55, 'Female50Percent', 'Parabolic', 56, 255, 50, 'NATURALCURE', 'POISONPOINT', 'LEAFGUARD', 'Undiscovered', 5120, 0.2, 1.2, 'Green', 'Bipedal', NULL, 'Bud', 'Over the winter, it closes its bud and endures the cold. In spring, the bud opens and releases pollen.', '4', 'ROSELIA,HappinessDay,', '0406_Budew'),
(407, 'ROSERADE', 'Roserade', 'GRASS', 'POISON', 60, 70, 65, 125, 105, 90, 'Female50Percent', 'Parabolic', 258, 75, 50, 'NATURALCURE', 'POISONPOINT', 'TECHNICIAN', 'Fairy,Grass', 5120, 0.9, 14.5, 'Green', 'Bipedal', NULL, 'Bouquet', 'It attracts prey with a sweet aroma, then downs it with thorny whips hidden in its arms.', '4', NULL, '0407_Roserade'),
(408, 'CRANIDOS', 'Cranidos', 'ROCK', NULL, 67, 125, 40, 30, 30, 58, 'FemaleOneEighth', 'Erratic', 70, 45, 50, 'MOLDBREAKER', NULL, 'SHEERFORCE', 'Monster', 7680, 0.9, 31.5, 'Blue', 'BipedalTail', NULL, 'Head Butt', 'It lived in jungles around 100 million years ago. Its skull is as hard as iron.', '4', 'RAMPARDOS,Level,30', '0408_Cranidos'),
(409, 'RAMPARDOS', 'Rampardos', 'ROCK', NULL, 97, 165, 60, 65, 50, 58, 'FemaleOneEighth', 'Erratic', 173, 45, 50, 'MOLDBREAKER', NULL, 'SHEERFORCE', 'Monster', 7680, 1.6, 102.5, 'Blue', 'BipedalTail', NULL, 'Head Butt', 'Its powerful head butt has enough power to shatter even the most durable things upon impact.', '4', NULL, '0409_Rampardos'),
(410, 'SHIELDON', 'Shieldon', 'ROCK', 'STEEL', 30, 42, 118, 42, 88, 30, 'FemaleOneEighth', 'Erratic', 70, 45, 50, 'STURDY', NULL, 'SOUNDPROOF', 'Monster', 7680, 0.5, 57.0, 'Gray', 'Quadruped', NULL, 'Shield', 'A Pokémon that lived in jungles around 100 million years ago. Its facial hide is extremely hard.', '4', 'BASTIODON,Level,30', '0410_Shieldon'),
(411, 'BASTIODON', 'Bastiodon', 'ROCK', 'STEEL', 60, 52, 168, 47, 138, 30, 'FemaleOneEighth', 'Erratic', 173, 45, 50, 'STURDY', NULL, 'SOUNDPROOF', 'Monster', 7680, 1.3, 149.5, 'Gray', 'Quadruped', NULL, 'Shield', 'Any frontal attack is repulsed. It is a docile Pokémon that feeds on grass and berries.', '4', NULL, '0411_Bastiodon'),
