(529, 'DRILBUR', 'Drilbur', 'GROUND', NULL, 60, 85, 40, 30, 45, 68, 'Female50Percent', 'Medium', 66, 120, 50, 'SANDRUSH', 'SANDFORCE', 'MOLDBREAKER', 'Field', 5120, 0.3, 8.5, 'Gray', 'BipedalTail', NULL, 'Mole', 'It makes its way swiftly through the soil by putting both claws together and rotating at high speed.', '5', 'EXCADRILL,Level,31', '0529_Drilbur'),
(530, 'EXCADRILL', 'Excadrill', 'GROUND', 'STEEL', 110, 135, 60, 50, 65, 88, 'Female50Percent', 'Medium', 178, 60, 50, 'SANDRUSH', 'SANDFORCE', 'MOLDBREAKER', 'Field', 5120, 0.7, 40.4, 'Gray', 'Bipedal', NULL, 'Subterrene', 'More than 300 feet below the surface, they build mazelike nests. Their activity can be destructive to subway tunnels.', '5', NULL, '0530_Excadrill'),
(531, 'AUDINO', 'Audino', 'NORMAL', NULL, 103, 60, 86, 60, 86, 50, 'Female50Percent', 'Fast', 390, 255, 50, 'HEALER', 'REGENERATOR', 'KLUTZ', 'Fairy', 5120, 1.1, 31.0, 'Pink', 'BipedalTail', NULL, 'Hearing', 'Its auditory sense is astounding. It has a radar-like ability to understand its surrounding through slight sounds.', '5', NULL, '0531_Audino'),
(532, 'TIMBURR', 'Timburr', 'FIGHTING', NULL, 75, 80, 55, 25, 35, 35, 'Female25Percent', 'Parabolic', 61, 180, 50, 'GUTS', 'SHEERFORCE', 'IRONFIST', 'Humanlike', 5120, 0.6, 12.5, 'Gray', 'Bipedal', NULL, 'Muscular', 'These Pokémon appear at building sites and help out with construction. They always carry squared logs.', '5', 'GURDURR,Level,25', '0532_Timburr'),
(533, 'GURDURR', 'Gurdurr', 'FIGHTING', NULL, 85, 105, 85, 40, 50, 40, 'Female25Percent', 'Parabolic', 142, 90, 50, 'GUTS', 'SHEERFORCE', 'IRONFIST', 'Humanlike', 5120, 1.2, 40.0, 'Gray', 'Bipedal', NULL, 'Muscular', 'They strengthen their bodies by carrying steel beams. They show off their big muscles to their friends.', '5', 'CONKELDURR,Trade,', '0533_Gurdurr'),
(534, 'CONKELDURR', 'Conkeldurr', 'FIGHTING', NULL, 105, 140, 95, 55, 65, 45, 'Female25Percent', 'Parabolic', 253, 45, 50, 'GUTS', 'SHEERFORCE', 'IRONFIST', 'Humanlike', 5120, 1.4, 87.0, 'Brown', 'Bipedal', NULL, 'Muscular', 'They use concrete pillars as walking canes. They know moves that enable them to swing the pillars freely in battle.', '5', NULL, '0534_Conkeldurr'),
(535, 'TYMPOLE', 'Tympole', 'WATER', NULL, 50, 50, 40, 50, 40, 64, 'Female50Percent', 'Parabolic', 59, 255, 50, 'SWIFTSWIM', 'HYDRATION', 'WATERABSORB', 'Water1', 5120, 0.5, 4.5, 'Blue', 'Finned', NULL, 'Tadpole', 'By vibrating its cheeks, it emits sound waves imperceptible to humans. It uses the rhythm of these sounds to talk.', '5', 'PALPITOAD,Level,25', '0535_Tympole'),
(536, 'PALPITOAD', 'Palpitoad', 'WATER', 'GROUND', 75, 65, 55, 65, 55, 69, 'Female50Percent', 'Parabolic', 134, 120, 50, 'SWIFTSWIM', 'HYDRATION', 'WATERABSORB', 'Water1', 5120, 0.8, 17.0, 'Blue', 'BipedalTail', NULL, 'Vibration', 'It lives in the water and on land. It uses its long, sticky tongue to capture prey.', '5', 'SEISMITOAD,Level,36', '0536_Palpitoad'),
(537, 'SEISMITOAD', 'Seismitoad', 'WATER', 'GROUND', 105, 95, 75, 85, 75, 74, 'Female50Percent', 'Parabolic', 255, 45, 50, 'SWIFTSWIM', 'POISONTOUCH', 'WATERABSORB', 'Water1', 5120, 1.5, 62.0, 'Blue', 'Bipedal', NULL, 'Vibration', 'It increases the power of its punches by vibrating the bumps on its fists. It can turn a boulder to rubble with one punch.', '5', NULL, '0537_Seismitoad'),
(538, 'THROH', 'Throh', 'FIGHTING', NULL, 120, 100, 85, 30, 85, 45, 'AlwaysMale', 'Medium', 163, 45, 50, 'GUTS', 'INNERFOCUS', 'MOLDBREAKER', 'Humanlike', 5120, 1.3, 55.5, 'Red', 'Bipedal', NULL, 'Judo', 'When they encounter foes bigger than themselves, they try to throw them. They always travel in packs of five.', '5', NULL, '0538_Throh'),
(539, 'SAWK', 'Sawk', 'FIGHTING', NULL, 75, 125, 75, 30, 75, 85, 'AlwaysMale', 'Medium', 163, 45, 50, 'STURDY', 'INNERFOCUS', 'MOLDBREAKER', 'Humanlike', 5120, 1.4, 51.0, 'Blue', 'Bipedal', NULL, 'Karate', 'Tying their belts gets them pumped and makes their punches more destructive. Disturbing their training angers them.', '5', NULL, '0539_Sawk'),
(540, 'SEWADDLE', 'Sewaddle', 'BUG', 'GRASS', 45, 53, 70, 40, 60, 42, 'Female50Percent', 'Parabolic', 62, 255, 50, 'SWARM', 'CHLOROPHYLL', 'OVERCOAT', 'Bug', 3840, 0.3, 2.5, 'Yellow', 'Insectoid', NULL, 'Sewing', 'This Pokémon makes clothes for itself. It chews up leaves and sews them with sticky thread extruded from its mouth.', '5', 'SWADLOON,Level,20', '0540_Sewaddle'),
(541, 'SWADLOON', 'Swadloon', 'BUG', 'GRASS', 55, 63, 90, 50, 80, 42, 'Female50Percent', 'Parabolic', 133, 120, 50, 'LEAFGUARD', 'CHLOROPHYLL', 'OVERCOAT', 'Bug', 3840, 0.5, 7.3, 'Green', 'HeadArms', NULL, 'Leaf-Wrapped', 'It protects itself from the cold by wrapping up in leaves. It stays on the move, eating leaves in forests.', '5', 'LEAVANNY,Happiness,', '0541_Swadloon'),
(542, 'LEAVANNY', 'Leavanny', 'BUG', 'GRASS', 75, 103, 80, 70, 80, 92, 'Female50Percent', 'Parabolic', 250, 45, 50, 'SWARM', 'CHLOROPHYLL', 'OVERCOAT', 'Bug', 3840, 1.2, 20.5, 'Yellow', 'Bipedal', NULL, 'Nurturing', 'It keeps its eggs warm with heat from fermenting leaves. It also uses leaves to make warm wrappings for Sewaddle.', '5', NULL, '0542_Leavanny'),
(543, 'VENIPEDE', 'Venipede', 'BUG', 'POISON', 30, 45, 59, 30, 39, 57, 'Female50Percent', 'Parabolic', 52, 255, 50, 'POISONPOINT', 'SWARM', 'SPEEDBOOST', 'Bug', 3840, 0.4, 5.3, 'Red', 'Insectoid', NULL, 'Centipede', 'It discovers what is going on around it by using the feelers on its head and tail. It is brutally aggresive.', '5', 'WHIRLIPEDE,Level,22', '0543_Venipede'),
(544, 'WHIRLIPEDE', 'Whirlipede', 'BUG', 'POISON', 40, 55, 99, 40, 79, 47, 'Female50Percent', 'Parabolic', 126, 120, 50, 'POISONPOINT', 'SWARM', 'SPEEDBOOST', 'Bug', 3840, 1.2, 58.5, 'Gray', 'Head', NULL, 'Curlipede', 'It is usually motionless, but when attacked, it rotates at high speed and then crashes into its opponent.', '5', 'SCOLIPEDE,Level,30', '0544_Whirlipede'),
(545, 'SCOLIPEDE', 'Scolipede', 'BUG', 'POISON', 60, 100, 89, 55, 69, 112, 'Female50Percent', 'Parabolic', 243, 45, 50, 'POISONPOINT', 'SWARM', 'SPEEDBOOST', 'Bug', 5120, 2.5, 200.5, 'Red', 'Insectoid', NULL, 'Megapede', 'Highly aggressive, it uses the claws near its neck to dig into its opponents and poison them.', '5', NULL, '0545_Scolipede'),
(546, 'COTTONEE', 'Cottonee', 'GRASS', 'FAIRY', 40, 27, 60, 37, 50, 66, 'Female50Percent', 'Medium', 56, 190, 50, 'PRANKSTER', 'INFILTRATOR', 'CHLOROPHYLL', 'Grass,Fairy', 5120, 0.3, 0.6, 'Green', 'Head', NULL, 'Cotton Puff', 'They go wherever the wind takes them. On rainy days, their bodies are heavier, so they take shelter beneath big trees.', '5', 'WHIMSICOTT,Item,SUNSTONE', '0546_Cottonee'),
(547, 'WHIMSICOTT', 'Whimsicott', 'GRASS', 'FAIRY', 60, 67, 85, 77, 75, 116, 'Female50Percent', 'Medium', 168, 75, 50, 'PRANKSTER', 'INFILTRATOR', 'CHLOROPHYLL', 'Grass,Fairy', 5120, 0.7, 6.6, 'Green', 'Bipedal', NULL, 'Windveiled', 'Riding whirlwinds, they appear. These Pokémon sneak through gaps into houses and cause all sorts of mischief.', '5', NULL, '0547_Whimsicott'),
(548, 'PETILIL', 'Petilil', 'GRASS', NULL, 45, 35, 50, 70, 50, 30, 'AlwaysFemale', 'Medium', 56, 190, 50, 'CHLOROPHYLL', 'OWNTEMPO', 'LEAFGUARD', 'Grass', 5120, 0.5, 6.6, 'Green', 'HeadBase', NULL, 'Bulb', 'Since they prefer moist, nutrient-rich soil, the areas where Petilil live are known to be good for growing plants.', '5', 'LILLIGANT,Item,SUNSTONE', '0548_Petilil'),
