(550, 'BASCULIN', 'Basculin', 'WATER', NULL, 70, 92, 65, 80, 55, 98, 'Female50Percent', 'Medium', 161, 25, 50, 'RECKLESS', 'ADAPTABILITY', 'MOLDBREAKER', 'Water2', 10240, 1.0, 18.0, 'Green', 'Finned', NULL, 'Hostile', 'Savage, violent Pokémon, red and blue Basculin are always fighting each other over territory.', '5', NULL, '0550_Basculin'),
(551, 'SANDILE', 'Sandile', 'GROUND', 'DARK', 50, 72, 35, 35, 35, 65, 'Female50Percent', 'Parabolic', 58, 180, 50, 'INTIMIDATE', 'MOXIE', 'ANGERPOINT', 'Field', 5120, 0.7, 15.2, 'Brown', 'Quadruped', NULL, 'Desert Croc', 'It moves along below the sand''s surface, except for its nose and eyes. A dark membrane shields its eyes from the sun.', '5', 'KROKOROK,Level,29', '0551_Sandile'),
