(556, 'MARACTUS', 'Maractus', 'GRASS', NULL, 75, 86, 67, 106, 67, 60, 'Female50Percent', 'Medium', 161, 255, 50, 'WATERABSORB', 'CHLOROPHYLL', 'STORMDRAIN', 'Grass', 5120, 1.0, 28.0, 'Green', 'HeadBase', NULL, 'Cactus', 'Arid regions are their habitat. They move rhythmically, making a sound similar to maracas.', '5', NULL, '0556_Maractus'),
