(561, 'SIGILYPH', 'Sigilyph', 'PSYCHIC', 'FLYING', 72, 58, 80, 103, 80, 97, 'Female50Percent', 'Medium', 172, 45, 50, 'WONDERSKIN', 'MAGICGUARD', 'TINTEDLENS', 'Flying', 5120, 1.4, 14.0, 'Black', 'Winged', NULL, 'Avianoid', 'The guardians of an ancient city, they use their psychic power to attack enemies that invade their territory.', '5', NULL, '0561_Sigilyph'),
(562, 'YAMASK', 'Yamask', 'GHOST', NULL, 38, 30, 85, 55, 65, 30, 'Female50Percent', 'Medium', 61, 190, 50, 'MUMMY', NULL, NULL, 'Mineral,Amorphous', 6400, 0.5, 1.5, 'Black', 'HeadArms', NULL, 'Spirit', 'These Pokémon arose from the spirits of people interred in graves in past ages. Each retains memories of its former life.', '5', 'COFAGRIGUS,Level,34,RUNERIGUS,None,', '0562_Yamask'),
(563, 'COFAGRIGUS', 'Cofagrigus', 'GHOST', NULL, 58, 50, 145, 95, 105, 30, 'Female50Percent', 'Medium', 169, 90, 50, 'MUMMY', NULL, NULL, 'Mineral,Amorphous', 6400, 1.7, 76.5, 'Yellow', 'HeadBase', NULL, 'Coffin', 'They pretend to be elaborate coffins to teach lessons to grave robbers. Their bodies are covered in pure gold.', '5', NULL, '0563_Cofagrigus'),
(564, 'TIRTOUGA', 'Tirtouga', 'WATER', 'ROCK', 54, 78, 103, 53, 45, 22, 'FemaleOneEighth', 'Medium', 71, 45, 50, 'SOLIDROCK', 'STURDY', 'SWIFTSWIM', 'Water1,Water3', 7680, 0.7, 16.5, 'Blue', 'Quadruped', NULL, 'Prototurtle', 'About 100 million years ago, these Pokémon swam in oceans. It is thought they also went on land to attack prey.', '5', 'CARRACOSTA,Level,37', '0564_Tirtouga'),
(565, 'CARRACOSTA', 'Carracosta', 'WATER', 'ROCK', 74, 108, 133, 83, 65, 32, 'FemaleOneEighth', 'Medium', 173, 45, 50, 'SOLIDROCK', 'STURDY', 'SWIFTSWIM', 'Water1,Water3', 7680, 1.2, 81.0, 'Blue', 'BipedalTail', NULL, 'Prototurtle', 'Incredible jaw strength enables them to chew up steel beams and rocks along with their prey.', '5', NULL, '0565_Carracosta'),
(566, 'ARCHEN', 'Archen', 'ROCK', 'FLYING', 55, 112, 45, 74, 45, 70, 'FemaleOneEighth', 'Medium', 71, 45, 50, 'DEFEATIST', NULL, NULL, 'Flying,Water3', 7680, 0.5, 9.5, 'Yellow', 'Winged', NULL, 'First Bird', 'Revived from a fossil, this Pokémon is thought to be the ancestor of all bird Pokémon.', '5', 'ARCHEOPS,Level,37', '0566_Archen'),
