(570, 'ZORUA', 'Zorua', 'DARK', NULL, 40, 65, 40, 80, 40, 65, 'FemaleOneEighth', 'Parabolic', 66, 75, 50, 'ILLUSION', NULL, NULL, 'Field', 6400, 0.7, 12.5, 'Gray', 'Quadruped', NULL, 'Tricky Fox', 'To protect themselves from danger, they hide their true identities by transforming into people and Pokémon.', '5', 'ZOROARK,Level,30', '0570_Zorua'),
(571, 'ZOROARK', 'Zoroark', 'DARK', NULL, 60, 105, 60, 120, 60, 105, 'FemaleOneEighth', 'Parabolic', 179, 45, 50, 'ILLUSION', NULL, NULL, 'Field', 5120, 1.6, 81.1, 'Gray', 'BipedalTail', NULL, 'Illusion Fox', 'Each has the ability to fool a large group of people simultaneously. They protect their lair with illusory scenery.', '5', NULL, '0571_Zoroark'),
(572, 'MINCCINO', 'Minccino', 'NORMAL', NULL, 55, 50, 40, 40, 40, 75, 'Female75Percent', 'Fast', 60, 255, 50, 'CUTECHARM', 'TECHNICIAN', 'SKILLLINK', 'Field', 3840, 0.4, 5.8, 'Gray', 'Quadruped', NULL, 'Chinchilla', 'These Pokémon prefer a tidy habitat. They are always sweeping and dusting, using their tails as brooms.', '5', 'CINCCINO,Item,SHINYSTONE', '0572_Minccino'),
(573, 'CINCCINO', 'Cinccino', 'NORMAL', NULL, 75, 95, 60, 65, 60, 115, 'Female75Percent', 'Fast', 165, 60, 50, 'CUTECHARM', 'TECHNICIAN', 'SKILLLINK', 'Field', 3840, 0.5, 7.5, 'Gray', 'Quadruped', NULL, 'Scarf', 'Their white fur feels amazing to touch. Their fur repels dust and prevents static electricity from building up.', '5', NULL, '0573_Cinccino'),
(574, 'GOTHITA', 'Gothita', 'PSYCHIC', NULL, 45, 30, 50, 55, 65, 45, 'Female75Percent', 'Parabolic', 58, 200, 50, 'FRISK', 'COMPETITIVE', 'SHADOWTAG', 'Humanlike', 5120, 0.4, 5.8, 'Purple', 'Bipedal', NULL, 'Fixation', 'They intently observe both Trainers and Pokémon. Apparently, they are looking at something that only Gothita can see.', '5', 'GOTHORITA,Level,32', '0574_Gothita'),
(575, 'GOTHORITA', 'Gothorita', 'PSYCHIC', NULL, 60, 45, 70, 75, 85, 55, 'Female75Percent', 'Parabolic', 137, 100, 50, 'FRISK', 'COMPETITIVE', 'SHADOWTAG', 'Humanlike', 5120, 0.7, 18.0, 'Purple', 'Bipedal', NULL, 'Manipulate', 'Starlight is the source of their power. At night, they mark star positions by using psychic power to float stones.', '5', 'GOTHITELLE,Level,41', '0575_Gothorita'),
(576, 'GOTHITELLE', 'Gothitelle', 'PSYCHIC', NULL, 70, 55, 95, 95, 110, 65, 'Female75Percent', 'Parabolic', 245, 50, 50, 'FRISK', 'COMPETITIVE', 'SHADOWTAG', 'Humanlike', 5120, 1.5, 44.0, 'Purple', 'Bipedal', NULL, 'Astral Body', 'They can predict the future from the placement and movement of the stars. They can see Trainers'' life spans.', '5', NULL, '0576_Gothitelle'),
(577, 'SOLOSIS', 'Solosis', 'PSYCHIC', NULL, 45, 30, 40, 105, 50, 20, 'Female50Percent', 'Parabolic', 58, 200, 50, 'OVERCOAT', 'MAGICGUARD', 'REGENERATOR', 'Amorphous', 5120, 0.3, 1.0, 'Green', 'Head', NULL, 'Cell', 'Because their bodies are enveloped in a special liquid, they can survive in any environment.', '5', 'DUOSION,Level,32', '0577_Solosis'),
