(579, 'REUNICLUS', 'Reuniclus', 'PSYCHIC', NULL, 110, 65, 75, 125, 85, 30, 'Female50Percent', 'Parabolic', 245, 50, 50, 'OVERCOAT', 'MAGICGUARD', 'REGENERATOR', 'Amorphous', 5120, 1.0, 20.1, 'Green', 'HeadArms', NULL, 'Multiplying', 'These remarkably intelligent Pokémon fight by controlling arms that can grip with rock-crushing power.', '5', NULL, '0579_Reuniclus'),
(580, 'DUCKLETT', 'Ducklett', 'WATER', 'FLYING', 62, 44, 50, 44, 50, 55, 'Female50Percent', 'Medium', 61, 190, 50, 'KEENEYE', 'BIGPECKS', 'HYDRATION', 'Water1,Flying', 5120, 0.5, 5.5, 'Blue', 'Winged', NULL, 'Water Bird', 'When attacked, it uses its feathers to splash water, escaping under cover of the spray.', '5', 'SWANNA,Level,35', '0580_Ducklett'),
(581, 'SWANNA', 'Swanna', 'WATER', 'FLYING', 75, 87, 63, 87, 63, 98, 'Female50Percent', 'Medium', 166, 45, 50, 'KEENEYE', 'BIGPECKS', 'HYDRATION', 'Water1,Flying', 5120, 1.3, 24.2, 'White', 'Winged', NULL, 'White Bird', 'It administers sharp, powerful pecks with its bill. It whips its long neck to deliver forceful repeated strikes.', '5', NULL, '0581_Swanna'),
