(641, 'TORNADUS', 'Tornadus', 'FLYING', NULL, 79, 115, 70, 125, 80, 111, 'AlwaysMale', 'Slow', 290, 3, 90, 'PRANKSTER', NULL, 'DEFIANT', 'Undiscovered', 30720, 1.5, 63.0, 'Green', 'HeadArms', NULL, 'Cyclone', 'Tornadus expels massive energy from its tail, causing severe storms. Its power is great enough to blow houses away.', '5', NULL, '0641_Tornadus'),
(642, 'THUNDURUS', 'Thundurus', 'ELECTRIC', 'FLYING', 79, 115, 70, 125, 80, 111, 'AlwaysMale', 'Slow', 290, 3, 90, 'PRANKSTER', NULL, 'DEFIANT', 'Undiscovered', 30720, 1.5, 61.0, 'Blue', 'HeadArms', NULL, 'Bolt Strike', 'The spikes on its tail discharge immense bolts of lightning. It flies around the Unova region firing off lightning bolts.', '5', NULL, '0642_Thundurus'),
(643, 'RESHIRAM', 'Reshiram', 'DRAGON', 'FIRE', 100, 120, 100, 150, 120, 90, 'Genderless', 'Slow', 340, 3, 0, 'TURBOBLAZE', NULL, NULL, 'Undiscovered', 30720, 3.2, 330.0, 'White', 'Winged', NULL, 'Vast White', 'When Reshiram''s tail flares, the heat energy moves the atmosphere and changes the world''s weather.', '5', NULL, '0643_Reshiram'),
(644, 'ZEKROM', 'Zekrom', 'DRAGON', 'ELECTRIC', 100, 150, 120, 120, 100, 90, 'Genderless', 'Slow', 340, 3, 0, 'TERAVOLT', NULL, NULL, 'Undiscovered', 30720, 2.9, 345.0, 'Black', 'BipedalTail', NULL, 'Deep Black', 'This Pokémon appears in legends. In its tail, it has a giant generator that creates electricity.', '5', NULL, '0644_Zekrom'),
(645, 'LANDORUS', 'Landorus', 'GROUND', 'FLYING', 89, 125, 90, 115, 80, 101, 'AlwaysMale', 'Slow', 300, 3, 90, 'SANDFORCE', NULL, 'SHEERFORCE', 'Undiscovered', 30720, 1.5, 68.0, 'Brown', 'HeadArms', NULL, 'Abundance', 'The energy that comes pouring from its tail increases the nutrition in the soil, making crops grow to great size.', '5', NULL, '0645_Landorus'),
(646, 'KYUREM', 'Kyurem', 'DRAGON', 'ICE', 125, 130, 90, 130, 90, 95, 'Genderless', 'Slow', 330, 3, 0, 'PRESSURE', NULL, NULL, 'Undiscovered', 30720, 3.0, 325.0, 'Gray', 'BipedalTail', NULL, 'Boundary', 'It generates a powerful, freezing energy inside itself, but its body became frozen when the energy leaked out.', '5', NULL, '0646_Kyurem'),
(647, 'KELDEO', 'Keldeo', 'WATER', 'FIGHTING', 91, 72, 90, 129, 90, 108, 'Genderless', 'Slow', 290, 3, 35, 'JUSTIFIED', NULL, NULL, 'Undiscovered', 20480, 1.4, 48.5, 'Yellow', 'Quadruped', NULL, 'Colt', 'It crosses the world, running over the surfaces of oceans and rivers. It appears at scenic waterfronts.', '5', NULL, '0647_Keldeo'),
(648, 'MELOETTA', 'Meloetta', 'NORMAL', 'PSYCHIC', 100, 77, 77, 128, 128, 90, 'Genderless', 'Slow', 300, 3, 100, 'SERENEGRACE', NULL, NULL, 'Undiscovered', 30720, 0.6, 6.5, 'White', 'Bipedal', NULL, 'Melody', 'Many famous songs have been inspired by the melodies that Meloetta plays.', '5', NULL, '0648_Meloetta'),
(649, 'GENESECT', 'Genesect', 'BUG', 'STEEL', 71, 120, 95, 120, 95, 99, 'Genderless', 'Slow', 300, 3, 0, 'DOWNLOAD', NULL, NULL, 'Undiscovered', 30720, 1.5, 82.5, 'Purple', 'Bipedal', NULL, 'Paleozoic', 'This ancient bug Pokémon was altered by Team Plasma. They upgraded the cannon on its back.', '5', NULL, '0649_Genesect'),
(650, 'CHESPIN', 'Chespin', 'GRASS', NULL, 56, 61, 65, 48, 45, 38, 'FemaleOneEighth', 'Parabolic', 63, 45, 50, 'OVERGROW', NULL, 'BULLETPROOF', 'Field', 5120, 0.4, 9.0, 'Green', 'BipedalTail', NULL, 'Spiny Nut', 'The quills on its head are usually soft. When it flexes them, the points become so hard and sharp that they can pierce rock.', '6', 'QUILLADIN,Level,16', '0650_Chespin'),
(651, 'QUILLADIN', 'Quilladin', 'GRASS', NULL, 61, 78, 95, 56, 58, 57, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'OVERGROW', NULL, 'BULLETPROOF', 'Field', 5120, 0.7, 29.0, 'Green', 'BipedalTail', NULL, 'Spiny Armor', 'They strengthen their lower bodies by running into one another. They are very kind and won''t start fights.', '6', 'CHESNAUGHT,Level,36', '0651_Quilladin'),
(652, 'CHESNAUGHT', 'Chesnaught', 'GRASS', 'FIGHTING', 88, 107, 122, 74, 75, 64, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'OVERGROW', NULL, 'BULLETPROOF', 'Field', 5120, 1.6, 90.0, 'Green', 'BipedalTail', NULL, 'Spiny Armor', 'Its Tackle is forceful enough to flip a 50-ton tank. It shields its allies from danger with its own body.', '6', NULL, '0652_Chesnaught'),
(653, 'FENNEKIN', 'Fennekin', 'FIRE', NULL, 40, 45, 40, 62, 60, 60, 'FemaleOneEighth', 'Parabolic', 61, 45, 50, 'BLAZE', NULL, 'MAGICIAN', 'Field', 5120, 0.4, 9.4, 'Red', 'Quadruped', NULL, 'Fox', 'As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.', '6', 'BRAIXEN,Level,16', '0653_Fennekin'),
(654, 'BRAIXEN', 'Braixen', 'FIRE', NULL, 59, 59, 58, 90, 70, 73, 'FemaleOneEighth', 'Parabolic', 143, 45, 50, 'BLAZE', NULL, 'MAGICIAN', 'Field', 5120, 1.0, 14.5, 'Red', 'BipedalTail', NULL, 'Fox', 'When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.', '6', 'DELPHOX,Level,36', '0654_Braixen'),
(655, 'DELPHOX', 'Delphox', 'FIRE', 'PSYCHIC', 75, 69, 72, 114, 100, 104, 'FemaleOneEighth', 'Parabolic', 267, 45, 50, 'BLAZE', NULL, 'MAGICIAN', 'Field', 5120, 1.5, 39.0, 'Red', 'BipedalTail', NULL, 'Fox', 'It gazes into the flame at the tip of its branch to achieve a focused state, which allows it to see into the future.', '6', NULL, '0655_Delphox'),
(656, 'FROAKIE', 'Froakie', 'WATER', NULL, 41, 56, 40, 62, 44, 71, 'FemaleOneEighth', 'Parabolic', 63, 45, 50, 'TORRENT', NULL, 'PROTEAN', 'Water1', 5120, 0.3, 7.0, 'Blue', 'Quadruped', NULL, 'Bubble Frog', 'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.', '6', 'FROGADIER,Level,16', '0656_Froakie'),
(657, 'FROGADIER', 'Frogadier', 'WATER', NULL, 54, 63, 52, 83, 56, 97, 'FemaleOneEighth', 'Parabolic', 142, 45, 50, 'TORRENT', NULL, 'PROTEAN', 'Water1', 5120, 0.6, 10.9, 'Blue', 'Bipedal', NULL, 'Bubble Frog', 'It can throw bubble-covered pebbles with precise control, hitting empty cans up to a hundred feet away.', '6', 'GRENINJA,Level,36', '0657_Frogadier'),
(658, 'GRENINJA', 'Greninja', 'WATER', 'DARK', 72, 95, 67, 103, 71, 122, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'PROTEAN', 'Water1', 5120, 1.5, 40.0, 'Blue', 'Bipedal', NULL, 'Ninja', 'It appears and vanishes with a ninja''s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.', '6', NULL, '0658_Greninja'),
(659, 'BUNNELBY', 'Bunnelby', 'NORMAL', NULL, 38, 36, 38, 32, 36, 57, 'Female50Percent', 'Medium', 47, 255, 50, 'PICKUP', 'CHEEKPOUCH', 'HUGEPOWER', 'Field', 3840, 0.4, 5.0, 'Brown', 'BipedalTail', NULL, 'Digging', 'It has ears like shovels. Digging holes strengthens its ears so much that they can sever thick roots effortlessly.', '6', 'DIGGERSBY,Level,20', '0659_Bunnelby'),
(660, 'DIGGERSBY', 'Diggersby', 'NORMAL', 'GROUND', 85, 56, 77, 50, 77, 78, 'Female50Percent', 'Medium', 148, 127, 50, 'PICKUP', 'CHEEKPOUCH', 'HUGEPOWER', 'Field', 3840, 1.0, 42.4, 'Brown', 'BipedalTail', NULL, 'Digging', 'As powerful as an excavator, its ears can reduce dense bedrock to rubble. When it''s finished digging, it lounges lazily.', '6', NULL, '0660_Diggersby'),
(661, 'FLETCHLING', 'Fletchling', 'NORMAL', 'FLYING', 45, 50, 43, 40, 38, 62, 'Female50Percent', 'Parabolic', 56, 255, 50, 'BIGPECKS', NULL, 'GALEWINGS', 'Flying', 3840, 0.3, 1.7, 'Red', 'Winged', NULL, 'Tiny Robin', 'These friendly Pokémon send signals to one another with beautiful chirps and tail-feather movements.', '6', 'FLETCHINDER,Level,17', '0661_Fletchling'),
(662, 'FLETCHINDER', 'Fletchinder', 'FIRE', 'FLYING', 62, 73, 55, 56, 52, 84, 'Female50Percent', 'Parabolic', 134, 120, 50, 'FLAMEBODY', NULL, 'GALEWINGS', 'Flying', 3840, 0.7, 16.0, 'Red', 'Winged', NULL, 'Ember', 'From its beak, it expels embers that set the tall grass on fire. Then it pounces on the bewildered prey that pop out of the grass.', '6', 'TALONFLAME,Level,35', '0662_Fletchinder'),
(663, 'TALONFLAME', 'Talonflame', 'FIRE', 'FLYING', 78, 81, 71, 74, 69, 126, 'Female50Percent', 'Parabolic', 175, 45, 50, 'FLAMEBODY', NULL, 'GALEWINGS', 'Flying', 3840, 1.2, 24.5, 'Red', 'Winged', NULL, 'Scorching', 'In the fever of an exciting battle, it showers embers from the gaps between its feathers and takes to the air.', '6', NULL, '0663_Talonflame'),
(664, 'SCATTERBUG', 'Scatterbug', 'BUG', NULL, 38, 35, 40, 27, 25, 35, 'Female50Percent', 'Medium', 40, 255, 50, 'SHIELDDUST', 'COMPOUNDEYES', 'FRIENDGUARD', 'Bug', 3840, 0.3, 2.5, 'Black', 'Insectoid', NULL, 'Scatterdust', 'When under attack from bird Pokémon, it spews a poisonous black powder that causes paralysis on contact.', '6', 'SPEWPA,Level,9', '0664_Scatterbug'),
(665, 'SPEWPA', 'Spewpa', 'BUG', NULL, 45, 22, 60, 27, 30, 29, 'Female50Percent', 'Medium', 75, 120, 50, 'SHEDSKIN', NULL, 'FRIENDGUARD', 'Bug', 3840, 0.3, 8.4, 'Black', 'HeadBase', NULL, 'Scatterdust', 'It lives hidden within thicket shadows. When predators attack, it quickly bristles the fur covering its body in an effort to threaten them.', '6', 'VIVILLON,Level,12', '0665_Spewpa'),
(666, 'VIVILLON', 'Vivillon', 'BUG', 'FLYING', 80, 52, 50, 90, 50, 89, 'Female50Percent', 'Medium', 206, 45, 50, 'SHIELDDUST', 'COMPOUNDEYES', 'FRIENDGUARD', 'Bug', 3840, 1.2, 17.0, 'White', 'MultiWinged', NULL, 'Scale', 'Vivillon with many different patterns are found all over the world. These patterns are affected by the climate of their habitat.', '6', NULL, '0666_Vivillon'),
(667, 'LITLEO', 'Litleo', 'FIRE', 'NORMAL', 62, 50, 58, 73, 54, 72, 'FemaleSevenEighths', 'Parabolic', 74, 220, 50, 'RIVALRY', 'UNNERVE', 'MOXIE', 'Field', 5120, 0.6, 13.5, 'Brown', 'Quadruped', NULL, 'Lion Cub', 'They set off on their own from their pride and live by themselves to become stronger. These hot-blooded Pokémon are quick to fight.', '6', 'PYROAR,Level,35', '0667_Litleo'),
(668, 'PYROAR', 'Pyroar', 'FIRE', 'NORMAL', 86, 68, 72, 109, 66, 106, 'FemaleSevenEighths', 'Parabolic', 177, 65, 50, 'RIVALRY', 'UNNERVE', 'MOXIE', 'Field', 5120, 1.5, 81.5, 'Brown', 'Quadruped', NULL, 'Royal', 'With fiery breath of more than 6,000 degrees Celsius, they viciously threaten any challenger. The females protect the pride''s cubs.', '6', NULL, '0668_Pyroar'),
(669, 'FLABEBE', 'Flabébé', 'FAIRY', NULL, 44, 38, 39, 61, 79, 42, 'AlwaysFemale', 'Medium', 61, 225, 50, 'FLOWERVEIL', NULL, 'SYMBIOSIS', 'Fairy', 5120, 0.1, 0.1, 'White', 'HeadArms', NULL, 'Single Bloom', 'When it finds a flower it likes, it dwells on that flower its whole life long. It floats in the wind''s embrace with an untroubled heart.', '6', 'FLOETTE,Level,19', '0669_Flabébé'),
(670, 'FLOETTE', 'Floette', 'FAIRY', NULL, 54, 45, 47, 75, 98, 52, 'AlwaysFemale', 'Medium', 130, 120, 50, 'FLOWERVEIL', NULL, 'SYMBIOSIS', 'Fairy', 5120, 0.2, 0.9, 'White', 'HeadArms', NULL, 'Single Bloom', 'It flutters around fields of flowers and cares for flowers that are starting to wilt. It draws out the power of flowers to battle.', '6', 'FLORGES,Item,SHINYSTONE', '0670_Floette'),
(671, 'FLORGES', 'Florges', 'FAIRY', NULL, 78, 65, 68, 112, 154, 75, 'AlwaysFemale', 'Medium', 276, 45, 50, 'FLOWERVEIL', NULL, 'SYMBIOSIS', 'Fairy', 5120, 1.1, 10.0, 'White', 'HeadArms', NULL, 'Garden', 'It claims exquisite flower gardens as its territory, and it obtains power from basking in the energy emitted by flowering plants.', '6', NULL, '0671_Florges'),
(672, 'SKIDDO', 'Skiddo', 'GRASS', NULL, 66, 65, 48, 62, 57, 52, 'Female50Percent', 'Medium', 70, 200, 50, 'SAPSIPPER', NULL, 'GRASSPELT', 'Field', 5120, 0.9, 31.0, 'Brown', 'Quadruped', NULL, 'Mount', 'If it has sunshine and water, it doesn''t need to eat, because it can generate energy from the leaves on its back.', '6', 'GOGOAT,Level,32', '0672_Skiddo'),
(673, 'GOGOAT', 'Gogoat', 'GRASS', NULL, 123, 100, 62, 97, 81, 68, 'Female50Percent', 'Medium', 186, 45, 50, 'SAPSIPPER', NULL, 'GRASSPELT', 'Field', 5120, 1.7, 91.0, 'Brown', 'Quadruped', NULL, 'Mount', 'It can tell how its trainer is feeling by subtle shifts in the grip on its horns. This empathetic sense lets them run as if one being.', '6', NULL, '0673_Gogoat'),
(674, 'PANCHAM', 'Pancham', 'FIGHTING', NULL, 67, 82, 62, 46, 48, 43, 'Female50Percent', 'Medium', 70, 220, 50, 'IRONFIST', 'MOLDBREAKER', 'SCRAPPY', 'Field,Humanlike', 6400, 0.6, 8.0, 'White', 'BipedalTail', NULL, 'Playful', 'It does its best to be taken seriously by its enemies, but its glare is not sufficiently intimidating. Chewing on a leaf is its trademark.', '6', 'PANGORO,LevelDarkInParty,32', '0674_Pancham'),
(675, 'PANGORO', 'Pangoro', 'FIGHTING', 'DARK', 95, 124, 78, 69, 71, 58, 'Female50Percent', 'Medium', 173, 65, 50, 'IRONFIST', 'MOLDBREAKER', 'SCRAPPY', 'Field,Humanlike', 6400, 2.1, 136.0, 'White', 'Bipedal', NULL, 'Daunting', 'It charges ahead and bashes its opponents like a berserker, uncaring about any hits it might take. Its arms are mighty enough to snap a telephone pole.', '6', NULL, '0675_Pangoro'),
(676, 'FURFROU', 'Furfrou', 'NORMAL', NULL, 75, 80, 60, 65, 90, 102, 'Female50Percent', 'Medium', 165, 160, 50, 'FURCOAT', NULL, NULL, 'Field', 5120, 1.2, 28.0, 'White', 'Quadruped', NULL, 'Poodle', 'Trimming its fluffy fur not only makes it more elegant but also increases the swiftness of its movements.', '6', NULL, '0676_Furfrou'),
(677, 'ESPURR', 'Espurr', 'PSYCHIC', NULL, 62, 48, 54, 63, 60, 68, 'Female50Percent', 'Medium', 71, 190, 50, 'KEENEYE', 'INFILTRATOR', 'OWNTEMPO', 'Field', 5120, 0.3, 3.5, 'Gray', 'BipedalTail', NULL, 'Restraint', 'The organ that emits its intense psychic power is sheltered by its ears to keep power from leaking out.', '6', 'MEOWSTIC,Level,25', '0677_Espurr'),
(678, 'MEOWSTIC', 'Meowstic', 'PSYCHIC', NULL, 74, 48, 76, 83, 81, 104, 'Female50Percent', 'Medium', 163, 75, 50, 'KEENEYE', 'INFILTRATOR', 'PRANKSTER', 'Field', 5120, 0.6, 8.5, 'Blue', 'BipedalTail', NULL, 'Constraint', 'Revealing the eyelike patterns on the insides of its ears will unleash its psychic powers. It normally keeps the patterns hidden, however.', '6', NULL, '0678_Meowstic'),
(679, 'HONEDGE', 'Honedge', 'STEEL', 'GHOST', 45, 80, 100, 35, 37, 28, 'Female50Percent', 'Medium', 65, 180, 50, 'NOGUARD', NULL, NULL, 'Mineral', 5120, 0.8, 2.0, 'Brown', 'HeadBase', NULL, 'Sword', 'Apparently this Pokémon is born when a departed spirit inhabits a sword. It attaches itself to people and drinks their life force.', '6', 'DOUBLADE,Level,35', '0679_Honedge'),
(680, 'DOUBLADE', 'Doublade', 'STEEL', 'GHOST', 59, 110, 150, 45, 49, 35, 'Female50Percent', 'Medium', 157, 90, 50, 'NOGUARD', NULL, NULL, 'Mineral', 5120, 0.8, 4.5, 'Brown', 'MultiBody', NULL, 'Sword', 'The complex attack patterns of its two swords are unstoppable, even for an opponent greatly accomplished at swordplay.', '6', 'AEGISLASH,Item,DUSKSTONE', '0680_Doublade'),
(681, 'AEGISLASH', 'Aegislash', 'STEEL', 'GHOST', 60, 50, 140, 50, 140, 60, 'Female50Percent', 'Medium', 250, 45, 50, 'STANCECHANGE', NULL, NULL, 'Mineral', 5120, 1.7, 53.0, 'Brown', 'HeadBase', NULL, 'Royal Sword', 'In this defensive stance, Aegislash uses its steel body and a force field of spectral power to reduce the damage of any attack.', '6', NULL, '0681_Aegislash'),
(682, 'SPRITZEE', 'Spritzee', 'FAIRY', NULL, 78, 52, 60, 63, 65, 23, 'Female50Percent', 'Medium', 68, 200, 50, 'HEALER', NULL, 'AROMAVEIL', 'Fairy', 5120, 0.2, 0.5, 'Pink', 'HeadArms', NULL, 'Perfume', 'It emits a scent that enraptures those who smell it. This fragrance changes depending on what it has eaten.', '6', 'AROMATISSE,TradeItem,SACHET', '0682_Spritzee'),
(683, 'AROMATISSE', 'Aromatisse', 'FAIRY', NULL, 101, 72, 72, 99, 89, 29, 'Female50Percent', 'Medium', 162, 140, 50, 'HEALER', NULL, 'AROMAVEIL', 'Fairy', 5120, 0.8, 15.5, 'Pink', 'Bipedal', NULL, 'Fragrance', 'It devises various scents, pleasant and unpleasant, and emits scents that its enemies dislike in order to gain an edge in battle.', '6', NULL, '0683_Aromatisse'),
(684, 'SWIRLIX', 'Swirlix', 'FAIRY', NULL, 62, 48, 66, 59, 57, 49, 'Female50Percent', 'Medium', 68, 200, 50, 'SWEETVEIL', NULL, 'UNBURDEN', 'Fairy', 5120, 0.4, 3.5, 'White', 'HeadLegs', NULL, 'Cotton Candy', 'To entangle its opponents in battle, it extrudes white threads as sweet and sticky as cotton candy.', '6', 'SLURPUFF,TradeItem,WHIPPEDDREAM', '0684_Swirlix'),
(685, 'SLURPUFF', 'Slurpuff', 'FAIRY', NULL, 82, 80, 86, 85, 75, 72, 'Female50Percent', 'Medium', 168, 140, 50, 'SWEETVEIL', NULL, 'UNBURDEN', 'Fairy', 5120, 0.8, 5.0, 'White', 'Bipedal', NULL, 'Meringue', 'It can distinguish the faintest of scents. It puts its sensitive sense of smell to use by helping pastry chefs in their work.', '6', NULL, '0685_Slurpuff'),
(686, 'INKAY', 'Inkay', 'DARK', 'PSYCHIC', 53, 54, 53, 37, 46, 45, 'Female50Percent', 'Medium', 58, 190, 50, 'CONTRARY', 'SUCTIONCUPS', 'INFILTRATOR', 'Water1,Water2', 5120, 0.4, 3.5, 'Blue', 'Multiped', NULL, 'Revolving', 'It flashes the light-emitting spots on its body, which drains its opponent''s will to fight. It takes the opportunity to scuttle away and hide.', '6', 'MALAMAR,Level,30', '0686_Inkay'),
(687, 'MALAMAR', 'Malamar', 'DARK', 'PSYCHIC', 86, 92, 88, 68, 75, 73, 'Female50Percent', 'Medium', 169, 80, 50, 'CONTRARY', 'SUCTIONCUPS', 'INFILTRATOR', 'Water1,Water2', 5120, 1.5, 47.0, 'Blue', 'HeadBase', NULL, 'Overturning', 'It lures prey close with hypnotic motions, then wraps its tentacles around it before finishing it off with digestive fluids.', '6', NULL, '0687_Malamar'),
(688, 'BINACLE', 'Binacle', 'ROCK', 'WATER', 42, 52, 67, 39, 56, 50, 'Female50Percent', 'Medium', 61, 120, 50, 'TOUGHCLAWS', 'SNIPER', 'PICKPOCKET', 'Water3', 5120, 0.5, 31.0, 'Brown', 'MultiBody', NULL, 'Two-Handed', 'They stretch and then contract, yanking their rocks along with them in bold hops. They eat seaweed that washes up on the shoreline.', '6', 'BARBARACLE,Level,39', '0688_Binacle'),
(689, 'BARBARACLE', 'Barbaracle', 'ROCK', 'WATER', 72, 105, 115, 54, 86, 68, 'Female50Percent', 'Medium', 175, 45, 50, 'TOUGHCLAWS', 'SNIPER', 'PICKPOCKET', 'Water3', 5120, 1.3, 96.0, 'Brown', 'MultiBody', NULL, 'Collective', 'Barbaracle''s legs and hands have minds of their own, and they will move independently. But they usually follow the head''s orders.', '6', NULL, '0689_Barbaracle'),
(690, 'SKRELP', 'Skrelp', 'POISON', 'WATER', 50, 60, 60, 60, 60, 30, 'Female50Percent', 'Medium', 64, 225, 50, 'POISONPOINT', 'POISONTOUCH', 'ADAPTABILITY', 'Water1,Dragon', 5120, 0.5, 7.3, 'Brown', 'HeadBase', NULL, 'Mock Kelp', 'Camouflaged as rotten kelp, they spray liquid poison on prey that approaches unawares and then finish it off.', '6', 'DRAGALGE,Level,48', '0690_Skrelp'),
(691, 'DRAGALGE', 'Dragalge', 'POISON', 'DRAGON', 65, 75, 90, 97, 123, 44, 'Female50Percent', 'Medium', 173, 55, 50, 'POISONPOINT', 'POISONTOUCH', 'ADAPTABILITY', 'Water1,Dragon', 5120, 1.8, 81.5, 'Brown', 'HeadBase', NULL, 'Mock Kelp', 'Their poison is strong enough to eat through the hull of a tanker, and they spit it indiscriminately at anything that enters their territory.', '6', NULL, '0691_Dragalge'),
(692, 'CLAUNCHER', 'Clauncher', 'WATER', NULL, 50, 53, 62, 58, 63, 44, 'Female50Percent', 'Slow', 66, 225, 50, 'MEGALAUNCHER', NULL, NULL, 'Water1,Water3', 3840, 0.5, 8.3, 'Blue', 'Insectoid', NULL, 'Water Gun', 'Through controlled expulsions of internal gas, it can expel water like a pistol shot. At close distances, it can shatter rock.', '6', 'CLAWITZER,Level,37', '0692_Clauncher'),
(693, 'CLAWITZER', 'Clawitzer', 'WATER', NULL, 71, 73, 88, 120, 89, 59, 'Female50Percent', 'Slow', 100, 55, 50, 'MEGALAUNCHER', NULL, NULL, 'Water1,Water3', 3840, 1.3, 35.3, 'Blue', 'Serpentine', NULL, 'Howitzer', 'By expelling water from the nozzle in the back of its claw, it can move at a speed of 60 knots.', '6', NULL, '0693_Clawitzer'),
(694, 'HELIOPTILE', 'Helioptile', 'ELECTRIC', 'NORMAL', 44, 38, 33, 61, 43, 70, 'Female50Percent', 'Medium', 58, 190, 50, 'DRYSKIN', 'SANDVEIL', 'SOLARPOWER', 'Monster,Dragon', 5120, 0.5, 6.0, 'Yellow', 'BipedalTail', NULL, 'Generator', 'They make their home in deserts. They can generate their energy from basking in the sun, so eating food is not a requirement.', '6', 'HELIOLISK,Item,SUNSTONE', '0694_Helioptile'),
(695, 'HELIOLISK', 'Heliolisk', 'ELECTRIC', 'NORMAL', 62, 55, 52, 109, 94, 109, 'Female50Percent', 'Medium', 168, 75, 50, 'DRYSKIN', 'SANDVEIL', 'SOLARPOWER', 'Monster,Dragon', 5120, 1.0, 21.0, 'Yellow', 'BipedalTail', NULL, 'Generator', 'They flare their frills and generate energy. A single Heliolisk can generate sufficient electricity to power a skyscraper.', '6', NULL, '0695_Heliolisk'),
(696, 'TYRUNT', 'Tyrunt', 'ROCK', 'DRAGON', 58, 89, 77, 45, 45, 48, 'FemaleOneEighth', 'Medium', 72, 45, 50, 'STRONGJAW', NULL, 'STURDY', 'Monster,Dragon', 7680, 0.8, 26.0, 'Brown', 'BipedalTail', NULL, 'Royal Heir', 'Its immense jaws have enough destructive force that it can chew up an automobile. It lived 100 million years ago.', '6', 'TYRANTRUM,LevelDay,39', '0696_Tyrunt'),
(697, 'TYRANTRUM', 'Tyrantrum', 'ROCK', 'DRAGON', 82, 121, 119, 69, 59, 71, 'FemaleOneEighth', 'Medium', 182, 45, 50, 'STRONGJAW', NULL, 'ROCKHEAD', 'Monster,Dragon', 7680, 2.5, 270.0, 'Red', 'BipedalTail', NULL, 'Despot', 'Thanks to its gargantuan jaws, which could shred thick metal plates as if they were paper, it was invincible in the ancient world it once inhabited.', '6', NULL, '0697_Tyrantrum'),
(698, 'AMAURA', 'Amaura', 'ROCK', 'ICE', 77, 59, 50, 67, 63, 46, 'FemaleOneEighth', 'Medium', 72, 45, 50, 'REFRIGERATE', NULL, 'SNOWWARNING', 'Monster', 7680, 1.3, 25.2, 'Blue', 'Quadruped', NULL, 'Tundra', 'This ancient Pokémon was restored from part of its body that had been frozen in ice for over 100 million years.', '6', 'AURORUS,LevelNight,39', '0698_Amaura'),
(699, 'AURORUS', 'Aurorus', 'ROCK', 'ICE', 123, 77, 72, 99, 92, 58, 'FemaleOneEighth', 'Medium', 104, 45, 50, 'REFRIGERATE', NULL, 'SNOWWARNING', 'Monster', 7680, 2.7, 225.0, 'Blue', 'Quadruped', NULL, 'Tundra', 'Using its diamond-shaped crystals, it can instantly create a wall of ice to block an opponent''s attack.', '6', NULL, '0699_Aurorus'),
(700, 'SYLVEON', 'Sylveon', 'FAIRY', NULL, 95, 65, 65, 110, 130, 60, 'FemaleOneEighth', 'Medium', 184, 45, 50, 'CUTECHARM', NULL, 'PIXILATE', 'Field', 8960, 1.0, 23.5, 'Pink', 'Quadruped', NULL, 'Intertwining', 'Its ribbonlike feelers give off an aura that weakens hostility in its prey, causing them to let down their guard. Then it attacks.', '6', NULL, '0700_Sylveon'),
(701, 'HAWLUCHA', 'Hawlucha', 'FIGHTING', 'FLYING', 78, 92, 75, 74, 63, 118, 'Female50Percent', 'Medium', 175, 100, 50, 'LIMBER', 'UNBURDEN', 'MOLDBREAKER', 'Flying,Humanlike', 5120, 0.8, 21.5, 'Green', 'Bipedal', NULL, 'Wrestling', 'With its wings, it controls its position in the air. It likes to attack from above, a maneuver that is difficult to defend against.', '6', NULL, '0701_Hawlucha'),
(702, 'DEDENNE', 'Dedenne', 'ELECTRIC', 'FAIRY', 67, 58, 57, 81, 67, 101, 'Female50Percent', 'Medium', 151, 180, 50, 'CHEEKPOUCH', 'PICKUP', 'PLUS', 'Field,Fairy', 5120, 0.2, 2.2, 'Yellow', 'BipedalTail', NULL, 'Antenna', 'Its whiskers serve as antennas. By sending and receiving electrical waves, it can communicate with others over vast distances.', '6', NULL, '0702_Dedenne'),
(703, 'CARBINK', 'Carbink', 'ROCK', 'FAIRY', 50, 50, 150, 50, 150, 50, 'Genderless', 'Slow', 100, 60, 50, 'CLEARBODY', NULL, 'STURDY', 'Fairy,Mineral', 6400, 0.3, 5.7, 'Gray', 'Head', NULL, 'Jewel', 'Born from the high temperatures and pressures deep underground, it defends itself by firing beams from the jewel part of its body.', '6', NULL, '0703_Carbink'),
(704, 'GOOMY', 'Goomy', 'DRAGON', NULL, 45, 50, 35, 55, 75, 40, 'Female50Percent', 'Slow', 60, 45, 35, 'SAPSIPPER', 'HYDRATION', 'GOOEY', 'Dragon', 10240, 0.3, 2.8, 'Purple', 'Serpentine', NULL, 'Soft Tissue', 'Its source of protection is its slimy, germ-laden mucous membrane. Anyone who touches it needs some thorough hand-washing.', '6', 'SLIGGOO,Level,40', '0704_Goomy'),
(705, 'SLIGGOO', 'Sliggoo', 'DRAGON', NULL, 68, 75, 53, 83, 113, 60, 'Female50Percent', 'Slow', 158, 45, 35, 'SAPSIPPER', 'HYDRATION', 'GOOEY', 'Dragon', 10240, 0.8, 17.5, 'Purple', 'Serpentine', NULL, 'Soft Tissue', 'This Pokémon''s mucous can dissolve anything. Toothless, it sprays mucous on its prey. Once they''re nicely dissolved, it slurps them up.', '6', 'GOODRA,LevelRain,50', '0705_Sliggoo'),
(706, 'GOODRA', 'Goodra', 'DRAGON', NULL, 90, 100, 70, 110, 150, 80, 'Female50Percent', 'Slow', 300, 45, 35, 'SAPSIPPER', 'HYDRATION', 'GOOEY', 'Dragon', 10240, 2.0, 150.5, 'Purple', 'BipedalTail', NULL, 'Dragon', 'It gets picked on because it''s meek. But then, whoever teased it gets to feel the full force of its horns and a good swatting from its thick tail.', '6', NULL, '0706_Goodra'),
(707, 'KLEFKI', 'Klefki', 'STEEL', 'FAIRY', 57, 80, 91, 80, 87, 75, 'Female50Percent', 'Fast', 165, 75, 50, 'PRANKSTER', NULL, 'MAGICIAN', 'Mineral', 5120, 0.2, 3.0, 'Gray', 'Head', NULL, 'Key Ring', 'It never lets go of a key that it likes, so people give it the keys to vaults and safes as a way to prevent crime.', '6', NULL, '0707_Klefki'),
(708, 'PHANTUMP', 'Phantump', 'GHOST', 'GRASS', 43, 70, 48, 50, 60, 38, 'Female50Percent', 'Medium', 62, 120, 50, 'NATURALCURE', 'FRISK', 'HARVEST', 'Grass,Amorphous', 5120, 0.4, 7.0, 'Brown', 'HeadArms', NULL, 'Stump', 'These Pokémon are stumps possessed by the spirits of children who died in the forest. Their cries sound like eerie screams.', '6', 'TREVENANT,Trade,', '0708_Phantump'),
(709, 'TREVENANT', 'Trevenant', 'GHOST', 'GRASS', 85, 110, 76, 65, 82, 56, 'Female50Percent', 'Medium', 166, 60, 50, 'NATURALCURE', 'FRISK', 'HARVEST', 'Grass,Amorphous', 5120, 1.5, 71.0, 'Brown', 'Multiped', NULL, 'Elder Tree', 'Through its roots, it exerts control over other trees. A deadly curse falls upon anyone cutting down trees in forests where Trevenant dwell.', '6', NULL, '0709_Trevenant'),
(710, 'PUMPKABOO', 'Pumpkaboo', 'GHOST', 'GRASS', 44, 66, 70, 44, 55, 56, 'Female50Percent', 'Medium', 67, 120, 50, 'PICKUP', 'FRISK', NULL, 'Amorphous', 5120, 0.3, 3.5, 'Brown', 'Head', NULL, 'Pumpkin', 'When taking spirits to the afterlife, small Pumpkaboo prefer the spirits of children to those of adults.', '6', 'GOURGEIST,Trade,', '0710_Pumpkaboo'),
(711, 'GOURGEIST', 'Gourgeist', 'GHOST', 'GRASS', 55, 85, 122, 58, 75, 99, 'Female50Percent', 'Medium', 173, 60, 50, 'PICKUP', 'FRISK', NULL, 'Amorphous', 5120, 0.7, 9.5, 'Brown', 'HeadBase', NULL, 'Pumpkin', 'Small Gourgeist pretend to be children to fool adults. Anyone who falls for the act gets carried away to the hereafter.', '6', NULL, '0711_Gourgeist'),
(712, 'BERGMITE', 'Bergmite', 'ICE', NULL, 55, 69, 85, 32, 35, 28, 'Female50Percent', 'Medium', 61, 190, 50, 'OWNTEMPO', 'ICEBODY', 'STURDY', 'Monster,Mineral', 5120, 1.0, 99.5, 'Blue', 'Quadruped', NULL, 'Ice Chunk', 'It blocks opponents'' attacks with the ice that shields its body. It uses cold air to repair any cracks with new ice.', '6', 'AVALUGG,Level,37', '0712_Bergmite'),
(713, 'AVALUGG', 'Avalugg', 'ICE', NULL, 95, 117, 184, 44, 46, 28, 'Female50Percent', 'Medium', 180, 55, 50, 'OWNTEMPO', 'ICEBODY', 'STURDY', 'Monster,Mineral', 5120, 2.0, 505.0, 'Blue', 'Quadruped', NULL, 'Iceberg', 'Its ice-covered body is as hard as steel. Its cumbersome frame crushes anything that stands in its way.', '6', NULL, '0713_Avalugg'),
(714, 'NOIBAT', 'Noibat', 'FLYING', 'DRAGON', 40, 30, 35, 45, 40, 55, 'Female50Percent', 'Medium', 49, 190, 50, 'FRISK', 'INFILTRATOR', 'TELEPATHY', 'Flying,Dragon', 5120, 0.5, 8.0, 'Purple', 'Winged', NULL, 'Sound Wave', 'Even a robust wrestler will become dizzy and unable to stand when exposed to its 200,000-hertz ultrasonic waves.', '6', 'NOIVERN,Level,48', '0714_Noibat'),
(715, 'NOIVERN', 'Noivern', 'FLYING', 'DRAGON', 85, 70, 80, 97, 80, 123, 'Female50Percent', 'Medium', 187, 45, 50, 'FRISK', 'INFILTRATOR', 'TELEPATHY', 'Flying,Dragon', 5120, 1.5, 85.0, 'Purple', 'Winged', NULL, 'Sound Wave', 'They fly around on moonless nights and attack careless prey. Nothing can beat them in a battle in the dark.', '6', NULL, '0715_Noivern'),
(716, 'XERNEAS', 'Xerneas', 'FAIRY', NULL, 126, 131, 95, 131, 98, 99, 'Genderless', 'Slow', 340, 45, 0, 'FAIRYAURA', NULL, NULL, 'Undiscovered', 30720, 3.0, 215.0, 'Blue', 'Quadruped', NULL, 'Life', 'Legends say it can share eternal life. It slept for a thousand years in the form of a tree before its revival.', '6', NULL, '0716_Xerneas'),
(717, 'YVELTAL', 'Yveltal', 'DARK', 'FLYING', 126, 131, 95, 131, 98, 99, 'Genderless', 'Slow', 340, 45, 0, 'DARKAURA', NULL, NULL, 'Undiscovered', 30720, 5.8, 203.0, 'Red', 'Winged', NULL, 'Destruction', 'When its life comes to an end, it absorbs the life energy of every living thing and turns into a cocoon once more.', '6', NULL, '0717_Yveltal'),
(718, 'ZYGARDE', 'Zygarde', 'DRAGON', 'GROUND', 108, 100, 121, 81, 95, 95, 'Genderless', 'Slow', 300, 3, 0, 'AURABREAK', 'POWERCONSTRUCT', NULL, 'Undiscovered', 30720, 5.0, 305.0, 'Green', 'Serpentine', NULL, 'Order', 'It''s thought to be monitoring the ecosystem. There are rumors that even greater power lies hidden within it.', '6', NULL, '0718_Zygarde'),
(719, 'DIANCIE', 'Diancie', 'ROCK', 'FAIRY', 50, 100, 150, 100, 150, 50, 'Genderless', 'Slow', 300, 3, 50, 'CLEARBODY', NULL, NULL, 'Undiscovered', 6400, 0.7, 8.8, 'Pink', 'HeadArms', NULL, 'Jewel', 'A sudden transformation of Carbink, its pink, glimmering body is said to be the loveliest sight in the whole world.', '6', NULL, '0719_Diancie'),
(720, 'HOOPA', 'Hoopa', 'PSYCHIC', 'GHOST', 80, 110, 60, 150, 130, 70, 'Genderless', 'Slow', 300, 3, 50, 'MAGICIAN', NULL, NULL, 'Undiscovered', 30720, 0.5, 9.0, 'Purple', 'HeadArms', NULL, 'Mischief', 'This troublemaker sends anything and everything to faraway places using its loop, which can warp space.', '6', NULL, '0720_Hoopa');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(721, 'VOLCANION', 'Volcanion', 'FIRE', 'WATER', 80, 110, 120, 130, 90, 70, 'Genderless', 'Slow', 300, 3, 100, 'WATERABSORB', NULL, NULL, 'Undiscovered', 30720, 1.7, 195.0, 'Brown', 'Quadruped', NULL, 'Steam', 'It lets out billows of steam and disappears into the dense fog. It''s said to live in mountains where humans do not tread.', '6', NULL, '0721_Volcanion'),
(722, 'ROWLET', 'Rowlet', 'GRASS', 'FLYING', 68, 55, 55, 50, 50, 42, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'OVERGROW', NULL, 'LONGREACH', 'Flying', 3840, 0.3, 1.5, 'Brown', 'Winged', NULL, 'Grass Quill', 'It sends its feathers, which are as sharp as blades, flying in attack. Its legs are strong, so its kicks are also formidable.', '7', 'DARTRIX,Level,17', '0722_Rowlet'),
(723, 'DARTRIX', 'Dartrix', 'GRASS', 'FLYING', 78, 75, 75, 70, 70, 52, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'OVERGROW', NULL, 'LONGREACH', 'Flying', 3840, 0.7, 16.0, 'Brown', 'Winged', NULL, 'Blade Quill', 'A bit of a dandy, it spends its free time preening its wings. Its preoccupation with any dirt on its plumage can leave it unable to battle.', '7', 'DECIDUEYE,Level,34', '0723_Dartrix'),
(724, 'DECIDUEYE', 'Decidueye', 'GRASS', 'GHOST', 78, 107, 75, 100, 100, 70, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'OVERGROW', NULL, 'LONGREACH', 'Flying', 3840, 1.6, 36.6, 'Brown', 'Winged', NULL, 'Arrow Quill', 'It fires arrow quills from its wings with such precision, they can pierce a pebble at distances over a hundred yards.', '7', NULL, '0724_Decidueye'),
(725, 'LITTEN', 'Litten', 'FIRE', NULL, 45, 65, 40, 60, 40, 70, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'BLAZE', NULL, 'INTIMIDATE', 'Field', 3840, 0.4, 4.3, 'Red', 'Quadruped', NULL, 'Fire Cat', 'Its coat regrows twice a year. When the time comes, Litten sets its own body on fire and burns away the old fur.', '7', 'TORRACAT,Level,17', '0725_Litten'),
(726, 'TORRACAT', 'Torracat', 'FIRE', NULL, 65, 85, 50, 80, 50, 90, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'BLAZE', NULL, 'INTIMIDATE', 'Field', 3840, 0.7, 25.0, 'Red', 'Quadruped', NULL, 'Fire Cat', 'It can act spoiled if it grows close to its Trainer. A powerful Pokémon, its sharp claws can leave its Trainer''s whole body covered in scratches.', '7', 'INCINEROAR,Level,34', '0726_Torracat'),
(727, 'INCINEROAR', 'Incineroar', 'FIRE', 'DARK', 95, 115, 90, 80, 90, 60, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'BLAZE', NULL, 'INTIMIDATE', 'Field', 3840, 1.8, 83.0, 'Red', 'BipedalTail', NULL, 'Heel', 'Although it''s rough mannered and egotistical, it finds beating down unworthy opponents boring. It gets motivated for stronger opponents.', '7', NULL, '0727_Incineroar'),
(728, 'POPPLIO', 'Popplio', 'WATER', NULL, 50, 54, 54, 66, 56, 40, 'FemaleOneEighth', 'Parabolic', 64, 45, 50, 'TORRENT', NULL, 'LIQUIDVOICE', 'Water1,Field', 3840, 0.4, 7.5, 'Blue', 'Finned', NULL, 'Sea Lion', 'This Pokémon snorts body fluids from its nose, blowing balloons to smash into its foes. It''s famous for being a hard worker.', '7', 'BRIONNE,Level,17', '0728_Popplio'),
(729, 'BRIONNE', 'Brionne', 'WATER', NULL, 60, 69, 69, 91, 81, 50, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'TORRENT', NULL, 'LIQUIDVOICE', 'Water1,Field', 3840, 0.6, 17.5, 'Blue', 'Finned', NULL, 'Pop Star', 'It gets excited when it sees a dance it doesn''t know. This hard worker practices diligently until it can learn that dance.', '7', 'PRIMARINA,Level,34', '0729_Brionne'),
(730, 'PRIMARINA', 'Primarina', 'WATER', 'FAIRY', 80, 74, 74, 126, 116, 60, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'LIQUIDVOICE', 'Water1,Field', 3840, 1.8, 44.0, 'Blue', 'Finned', NULL, 'Soloist', 'It controls its water balloons with song. The melody is learned from others of its kind and is passed down from one generation to the next.', '7', NULL, '0730_Primarina'),
(731, 'PIKIPEK', 'Pikipek', 'NORMAL', 'FLYING', 35, 75, 30, 30, 30, 65, 'Female50Percent', 'Medium', 53, 255, 50, 'KEENEYE', 'SKILLLINK', 'PICKUP', 'Flying', 3840, 0.3, 1.2, 'Black', 'Winged', NULL, 'Woodpecker', 'It pecks at trees with its hard beak. You can get some idea of its mood or condition from the rhythm of its pecking.', '7', 'TRUMBEAK,Level,14', '0731_Pikipek'),
(732, 'TRUMBEAK', 'Trumbeak', 'NORMAL', 'FLYING', 55, 85, 50, 40, 50, 75, 'Female50Percent', 'Medium', 124, 120, 50, 'KEENEYE', 'SKILLLINK', 'PICKUP', 'Flying', 3840, 0.6, 14.8, 'Black', 'Winged', NULL, 'Bugle Beak', 'It eats berries and stores their seeds in its beak. When it encounters enemies or prey, it fires off all the seeds in a burst.', '7', 'TOUCANNON,Level,28', '0732_Trumbeak'),
(733, 'TOUCANNON', 'Toucannon', 'NORMAL', 'FLYING', 80, 120, 75, 75, 75, 60, 'Female50Percent', 'Medium', 243, 45, 50, 'KEENEYE', 'SKILLLINK', 'SHEERFORCE', 'Flying', 3840, 1.1, 26.0, 'Black', 'Winged', NULL, 'Cannon', 'They smack beaks with others of their kind to communicate. The strength and number of hits tell each other how they feel.', '7', NULL, '0733_Toucannon'),
(734, 'YUNGOOS', 'Yungoos', 'NORMAL', NULL, 48, 70, 30, 30, 30, 45, 'Female50Percent', 'Medium', 51, 255, 50, 'STAKEOUT', 'STRONGJAW', 'ADAPTABILITY', 'Field', 3840, 0.4, 6.0, 'Brown', 'Quadruped', NULL, 'Loitering', 'Its stomach takes up most of its long torso. It''s a big eater, so the amount Trainers have to spend on its food is no laughing matter.', '7', 'GUMSHOOS,LevelDay,20', '0734_Yungoos'),
(735, 'GUMSHOOS', 'Gumshoos', 'NORMAL', NULL, 88, 110, 60, 55, 60, 45, 'Female50Percent', 'Medium', 146, 127, 50, 'STAKEOUT', 'STRONGJAW', 'ADAPTABILITY', 'Field', 3840, 0.7, 14.2, 'Brown', 'Quadruped', NULL, 'Stakeout', 'When it finds a trace of its prey, it patiently stakes out the location... but it''s always snoozing by nightfall.', '7', NULL, '0735_Gumshoos'),
(736, 'GRUBBIN', 'Grubbin', 'BUG', NULL, 47, 62, 45, 55, 45, 46, 'Female50Percent', 'Medium', 60, 255, 50, 'SWARM', NULL, NULL, 'Bug', 3840, 0.4, 4.4, 'Gray', 'Insectoid', NULL, 'Larva', 'It spits a sticky thread to stop opponents in their tracks, and then it grabs them in its sharp, sturdy mandibles to take them down.', '7', 'CHARJABUG,Level,20', '0736_Grubbin'),
(737, 'CHARJABUG', 'Charjabug', 'BUG', 'ELECTRIC', 57, 82, 95, 55, 75, 36, 'Female50Percent', 'Medium', 140, 120, 50, 'BATTERY', NULL, NULL, 'Bug', 3840, 0.5, 10.5, 'Green', 'Serpentine', NULL, 'Battery', 'It buries itself in fallen leaves and barely moves, munching away on humus. If you accidentally step on one, you''ll get a shock!', '7', 'VIKAVOLT,Item,THUNDERSTONE,VIKAVOLT,LocationFlag,Magnetic', '0737_Charjabug'),
(738, 'VIKAVOLT', 'Vikavolt', 'BUG', 'ELECTRIC', 77, 70, 90, 145, 75, 43, 'Female50Percent', 'Medium', 250, 45, 50, 'LEVITATE', NULL, NULL, 'Bug', 3840, 1.5, 45.0, 'Blue', 'Insectoid', NULL, 'Stag Beetle', 'It zips around, on sharp lookout for an opening. It concentrates electrical energy within its large jaws and uses it to zap its enemies.', '7', NULL, '0738_Vikavolt'),
(739, 'CRABRAWLER', 'Crabrawler', 'FIGHTING', NULL, 47, 82, 57, 42, 47, 63, 'Female50Percent', 'Medium', 68, 225, 50, 'HYPERCUTTER', 'IRONFIST', 'ANGERPOINT', 'Water3', 5120, 0.6, 7.0, 'Purple', 'Insectoid', NULL, 'Boxing', 'It punches so much, its pincers often come off from overuse, but they grow back quickly. What little meat they contain is rich and delicious.', '7', 'CRABOMINABLE,LocationFlag,IceRock', '0739_Crabrawler'),
(740, 'CRABOMINABLE', 'Crabominable', 'FIGHTING', 'ICE', 97, 132, 77, 62, 67, 43, 'Female50Percent', 'Medium', 167, 60, 50, 'HYPERCUTTER', 'IRONFIST', 'ANGERPOINT', 'Water3', 5120, 1.7, 180.0, 'White', 'Insectoid', NULL, 'Woolly Crab', 'It aimed for the top but got lost and ended up on a snowy mountain. Being forced to endure the cold, this Pokémon evolved and grew fur.', '7', NULL, '0740_Crabominable'),
(741, 'ORICORIO', 'Oricorio', 'FIRE', 'FLYING', 75, 70, 70, 98, 70, 93, 'Female75Percent', 'Medium', 167, 45, 50, 'DANCER', NULL, NULL, 'Flying', 5120, 0.6, 3.4, 'Red', 'Winged', NULL, 'Dancing', 'It beats its wings together to create fire. As it moves in the steps of its beautiful dance, it bathes opponents in intense flames.', '7', NULL, '0741_Oricorio'),
(742, 'CUTIEFLY', 'Cutiefly', 'BUG', 'FAIRY', 40, 45, 40, 55, 40, 84, 'Female50Percent', 'Medium', 61, 190, 50, 'HONEYGATHER', 'SHIELDDUST', 'SWEETVEIL', 'Bug,Fairy', 5120, 0.1, 0.2, 'Yellow', 'Insectoid', NULL, 'Bee Fly', 'It feeds on the nectar and pollen of flowers. Because it''s able to sense auras, it can identify which flowers are about to bloom.', '7', 'RIBOMBEE,Level,25', '0742_Cutiefly'),
(743, 'RIBOMBEE', 'Ribombee', 'BUG', 'FAIRY', 60, 55, 60, 95, 70, 124, 'Female50Percent', 'Medium', 162, 75, 50, 'HONEYGATHER', 'SHIELDDUST', 'SWEETVEIL', 'Bug,Fairy', 5120, 0.2, 0.5, 'Yellow', 'MultiWinged', NULL, 'Bee Fly', 'Rain makes pollen damp, so Ribombee hates rain. When it sees ominous clouds, it finds a hollow in a tree, where it waits stock-still.', '7', NULL, '0743_Ribombee'),
(744, 'ROCKRUFF', 'Rockruff', 'ROCK', NULL, 45, 65, 40, 30, 40, 60, 'Female50Percent', 'Medium', 56, 190, 50, 'KEENEYE', 'VITALSPIRIT', 'STEADFAST', 'Field', 3840, 0.5, 9.2, 'Brown', 'Quadruped', NULL, 'Puppy', 'This Pokémon has lived with people since times long ago. It can sense when its Trainer is in the dumps and will stick close by its Trainer''s side.', '7', 'LYCANROC,Level,25', '0744_Rockruff'),
(745, 'LYCANROC', 'Lycanroc', 'ROCK', NULL, 75, 115, 65, 55, 65, 112, 'Female50Percent', 'Medium', 170, 90, 50, 'KEENEYE', 'SANDRUSH', 'STEADFAST', 'Field', 3840, 0.8, 25.0, 'Brown', 'Quadruped', NULL, 'Wolf', 'Its quick movements confuse its enemies. Well equipped with claws and fangs, it also uses the sharp rocks in its mane as weapons.', '7', NULL, '0745_Lycanroc'),
(746, 'WISHIWASHI', 'Wishiwashi', 'WATER', NULL, 45, 20, 20, 25, 25, 40, 'Female50Percent', 'Fast', 61, 60, 50, 'SCHOOLING', NULL, NULL, 'Water2', 3840, 0.2, 0.3, 'Blue', 'Finned', NULL, 'Small Fry', 'It''s awfully weak and notably tasty, so everyone is always out to get it. As it happens, anyone trying to bully it receives a painful lesson.', '7', NULL, '0746_Wishiwashi'),
(747, 'MAREANIE', 'Mareanie', 'POISON', 'WATER', 50, 53, 62, 43, 52, 45, 'Female50Percent', 'Medium', 61, 190, 50, 'MERCILESS', 'LIMBER', 'REGENERATOR', 'Water1', 5120, 0.4, 8.0, 'Blue', 'HeadBase', NULL, 'Brutal Star', 'It plunges the poison spike on its head into its prey. When the prey has weakened, Mareanie deals the finishing blow with its 10 tentacles.', '7', 'TOXAPEX,Level,38', '0747_Mareanie'),
(748, 'TOXAPEX', 'Toxapex', 'POISON', 'WATER', 50, 63, 152, 53, 142, 35, 'Female50Percent', 'Medium', 173, 75, 50, 'MERCILESS', 'LIMBER', 'REGENERATOR', 'Water1', 5120, 0.7, 14.5, 'Blue', 'Multiped', NULL, 'Brutal Star', 'Those attacked by Toxapex''s poison will suffer intense pain for three days and three nights. Post-recovery, there will be some aftereffects.', '7', NULL, '0748_Toxapex'),
(749, 'MUDBRAY', 'Mudbray', 'GROUND', NULL, 70, 100, 70, 45, 55, 45, 'Female50Percent', 'Medium', 77, 190, 50, 'OWNTEMPO', 'STAMINA', 'INNERFOCUS', 'Field', 5120, 1.0, 110.0, 'Brown', 'Quadruped', NULL, 'Donkey', 'It loves playing in the mud. If it isn''t showered with mud on a daily basis, it gets stressed out and stops listening to its Trainer.', '7', 'MUDSDALE,Level,30', '0749_Mudbray'),
(750, 'MUDSDALE', 'Mudsdale', 'GROUND', NULL, 100, 125, 100, 55, 85, 35, 'Female50Percent', 'Medium', 175, 60, 50, 'OWNTEMPO', 'STAMINA', 'INNERFOCUS', 'Field', 5120, 2.5, 920.0, 'Brown', 'Quadruped', NULL, 'Draft Horse', 'It remains calm and unmoving no matter the situation. It mixes dirt with the saliva in its mouth to make a special kind of mud.', '7', NULL, '0750_Mudsdale'),
(751, 'DEWPIDER', 'Dewpider', 'WATER', 'BUG', 38, 40, 52, 40, 72, 27, 'Female50Percent', 'Medium', 54, 200, 50, 'WATERBUBBLE', NULL, 'WATERABSORB', 'Water1,Bug', 3840, 0.3, 4.0, 'Green', 'HeadLegs', NULL, 'Water Bubble', 'When two Dewpider meet, they display their water bubbles to each other. Then the one with the smaller bubble gets out of the other''s way.', '7', 'ARAQUANID,Level,22', '0751_Dewpider'),
(752, 'ARAQUANID', 'Araquanid', 'WATER', 'BUG', 68, 70, 92, 50, 132, 42, 'Female50Percent', 'Medium', 159, 100, 50, 'WATERBUBBLE', NULL, 'WATERABSORB', 'Water1,Bug', 3840, 1.8, 82.0, 'Green', 'Insectoid', NULL, 'Water Bubble', 'It delivers headbutts with the water bubble on its head. Small Pokémon get sucked into the bubble, where they drown.', '7', NULL, '0752_Araquanid'),
(753, 'FOMANTIS', 'Fomantis', 'GRASS', NULL, 40, 55, 35, 50, 35, 35, 'Female50Percent', 'Medium', 50, 190, 50, 'LEAFGUARD', NULL, 'CONTRARY', 'Grass', 5120, 0.3, 1.5, 'Pink', 'BipedalTail', NULL, 'Sickle Grass', 'When the sun rises, Fomantis spreads its four leaves and bathes in the sunlight. The tip of its head has a pleasant aroma.', '7', 'LURANTIS,LevelDay,34', '0753_Fomantis'),
(754, 'LURANTIS', 'Lurantis', 'GRASS', NULL, 70, 105, 90, 80, 90, 45, 'Female50Percent', 'Medium', 168, 75, 50, 'LEAFGUARD', NULL, 'CONTRARY', 'Grass', 5120, 0.9, 18.5, 'Pink', 'Bipedal', NULL, 'Bloom Sickle', 'It requires a lot of effort to maintain Lurantis''s vivid coloring, but some collectors enjoy this work and treat it as their hobby.', '7', NULL, '0754_Lurantis'),
(755, 'MORELULL', 'Morelull', 'GRASS', 'FAIRY', 40, 35, 55, 65, 75, 15, 'Female50Percent', 'Medium', 57, 190, 50, 'ILLUMINATE', 'EFFECTSPORE', 'RAINDISH', 'Grass', 5120, 0.2, 1.5, 'Purple', 'HeadBase', NULL, 'Illuminating', 'It scatters its shining spores around itself. Even though they''re dangerous, nighttime tours of forests where Morelull live are popular.', '7', 'SHIINOTIC,Level,24', '0755_Morelull'),
(756, 'SHIINOTIC', 'Shiinotic', 'GRASS', 'FAIRY', 60, 45, 80, 90, 100, 30, 'Female50Percent', 'Medium', 142, 75, 50, 'ILLUMINATE', 'EFFECTSPORE', 'RAINDISH', 'Grass', 5120, 1.0, 11.5, 'Purple', 'Bipedal', NULL, 'Illuminating', 'It puts its prey to sleep and siphons off their vitality through the tip of its arms. If one of its kind is weakened, it helps by sending it vitality.', '7', NULL, '0756_Shiinotic'),
(757, 'SALANDIT', 'Salandit', 'POISON', 'FIRE', 48, 44, 40, 71, 40, 77, 'FemaleOneEighth', 'Medium', 64, 120, 50, 'CORROSION', NULL, 'OBLIVIOUS', 'Monster,Dragon', 5120, 0.6, 4.8, 'Black', 'Quadruped', NULL, 'Toxic Lizard', 'It burns its bodily fluids to create a poisonous gas. When its enemies become disoriented from inhaling the gas, it attacks them.', '7', 'SALAZZLE,LevelFemale,33', '0757_Salandit'),
(758, 'SALAZZLE', 'Salazzle', 'POISON', 'FIRE', 68, 64, 60, 111, 60, 117, 'AlwaysFemale', 'Medium', 168, 45, 50, 'CORROSION', NULL, 'OBLIVIOUS', 'Monster,Dragon', 5120, 1.2, 22.2, 'Black', 'Quadruped', NULL, 'Toxic Lizard', 'Filled with pheromones, its poisonous gas can be diluted to use in the production of luscious perfumes.', '7', NULL, '0758_Salazzle'),
(759, 'STUFFUL', 'Stufful', 'NORMAL', 'FIGHTING', 70, 75, 50, 45, 50, 50, 'Female50Percent', 'Medium', 68, 140, 50, 'FLUFFY', 'KLUTZ', 'CUTECHARM', 'Field', 3840, 0.5, 6.8, 'Pink', 'Quadruped', NULL, 'Flailing', 'Despite its adorable appearance, when it gets angry and flails about, its arms and legs could knock a pro wrestler sprawling.', '7', 'BEWEAR,Level,27', '0759_Stufful'),
(760, 'BEWEAR', 'Bewear', 'NORMAL', 'FIGHTING', 120, 125, 80, 55, 60, 60, 'Female50Percent', 'Medium', 175, 70, 50, 'FLUFFY', 'KLUTZ', 'UNNERVE', 'Field', 3840, 2.1, 135.0, 'Pink', 'BipedalTail', NULL, 'Strong Arm', 'It waves its hands wildly in intimidation and warning. Life is over for anyone who doesn''t run away as fast as possible.', '7', NULL, '0760_Bewear'),
(761, 'BOUNSWEET', 'Bounsweet', 'GRASS', NULL, 42, 30, 38, 30, 38, 32, 'AlwaysFemale', 'Parabolic', 42, 235, 50, 'LEAFGUARD', 'OBLIVIOUS', 'SWEETVEIL', 'Grass', 5120, 0.3, 3.2, 'Purple', 'HeadLegs', NULL, 'Fruit', 'Because of its sweet, delicious aroma, bird Pokémon are always after it, but it''s not intelligent enough to care.', '7', 'STEENEE,Level,18', '0761_Bounsweet'),
(762, 'STEENEE', 'Steenee', 'GRASS', NULL, 52, 40, 48, 40, 48, 62, 'AlwaysFemale', 'Parabolic', 102, 120, 50, 'LEAFGUARD', 'OBLIVIOUS', 'SWEETVEIL', 'Grass', 5120, 0.7, 8.2, 'Purple', 'Bipedal', NULL, 'Fruit', 'It''s protected by its hard sepals, so it plays with bird Pokémon without worry. They peck it relentlessly, but it doesn''t care.', '7', 'TSAREENA,HasMove,STOMP', '0762_Steenee'),
(763, 'TSAREENA', 'Tsareena', 'GRASS', NULL, 72, 120, 98, 50, 98, 72, 'AlwaysFemale', 'Parabolic', 255, 45, 50, 'LEAFGUARD', 'QUEENLYMAJESTY', 'SWEETVEIL', 'Grass', 5120, 1.2, 21.4, 'Purple', 'Bipedal', NULL, 'Fruit', 'A Pokémon with an aggressive personality and a mastery of kicking, it cackles every time it kicks an opponent.', '7', NULL, '0763_Tsareena'),
(764, 'COMFEY', 'Comfey', 'FAIRY', NULL, 51, 52, 90, 82, 110, 100, 'Female75Percent', 'Fast', 170, 60, 50, 'FLOWERVEIL', 'TRIAGE', 'NATURALCURE', 'Grass', 5120, 0.1, 0.3, 'Green', 'Head', NULL, 'Posy Picker', 'Baths prepared with the flowers from its vine have a relaxing effect, so this Pokémon is a hit with many people.', '7', NULL, '0764_Comfey'),
(765, 'ORANGURU', 'Oranguru', 'NORMAL', 'PSYCHIC', 90, 60, 80, 90, 110, 60, 'Female50Percent', 'Slow', 172, 45, 50, 'INNERFOCUS', 'TELEPATHY', 'SYMBIOSIS', 'Field', 5120, 1.5, 76.0, 'White', 'Bipedal', NULL, 'Sage', 'It normally spends its time meditating in the treetops. It throws Poké Balls and gives other Pokémon orders as it pleases.', '7', NULL, '0765_Oranguru'),
(766, 'PASSIMIAN', 'Passimian', 'FIGHTING', NULL, 100, 120, 90, 40, 60, 80, 'Female50Percent', 'Slow', 172, 45, 50, 'RECEIVER', NULL, 'DEFIANT', 'Field', 5120, 2.0, 82.8, 'White', 'BipedalTail', NULL, 'Teamwork', 'Berries are its weapons as well as the staple of its diet. The one that can throw a berry the farthest is the boss of the troop.', '7', NULL, '0766_Passimian'),
(767, 'WIMPOD', 'Wimpod', 'BUG', 'WATER', 25, 35, 40, 20, 30, 80, 'Female50Percent', 'Medium', 46, 90, 50, 'WIMPOUT', NULL, NULL, 'Bug,Water3', 5120, 0.5, 12.0, 'Gray', 'Multiped', NULL, 'Turn Tail', 'This Pokémon is a coward. As it desperately dashes off, the flailing of its many legs leaves a sparkling clean path in its wake.', '7', 'GOLISOPOD,Level,30', '0767_Wimpod'),
(768, 'GOLISOPOD', 'Golisopod', 'BUG', 'WATER', 75, 125, 140, 60, 90, 40, 'Female50Percent', 'Medium', 186, 45, 50, 'EMERGENCYEXIT', NULL, NULL, 'Bug,Water3', 5120, 2.0, 108.0, 'Gray', 'Bipedal', NULL, 'Hard Scale', 'It battles skillfully with its six arms, but spends most of its time peacefully meditating in caves deep beneath the sea.', '7', NULL, '0768_Golisopod'),
(769, 'SANDYGAST', 'Sandygast', 'GHOST', 'GROUND', 55, 55, 80, 70, 45, 15, 'Female50Percent', 'Medium', 64, 140, 50, 'WATERCOMPACTION', NULL, 'SANDVEIL', 'Amorphous', 3840, 0.5, 70.0, 'Brown', 'Serpentine', NULL, 'Sand Heap', 'It likes the shovel on its head, so Sandygast will get serious and fight any children who come to take it back.', '7', 'PALOSSAND,Level,42', '0769_Sandygast'),
(770, 'PALOSSAND', 'Palossand', 'GHOST', 'GROUND', 85, 75, 110, 100, 75, 35, 'Female50Percent', 'Medium', 168, 60, 50, 'WATERCOMPACTION', NULL, 'SANDVEIL', 'Amorphous', 3840, 1.3, 250.0, 'Brown', 'Serpentine', NULL, 'Sand Castle', 'Buried beneath the castle are masses of dried-up bones from those whose vitality it has drained.', '7', NULL, '0770_Palossand'),
(771, 'PYUKUMUKU', 'Pyukumuku', 'WATER', NULL, 55, 60, 130, 30, 130, 5, 'Female50Percent', 'Fast', 144, 60, 50, 'INNARDSOUT', NULL, 'UNAWARE', 'Water1', 3840, 0.3, 1.2, 'Black', 'Serpentine', NULL, 'Sea Cucumber', 'It lives in shallow seas, such as areas near a beach. It can eject its internal organs, which it uses to engulf its prey or battle enemies.', '7', NULL, '0771_Pyukumuku'),
(772, 'TYPENULL', 'Type: Null', 'NORMAL', NULL, 95, 95, 95, 95, 95, 59, 'Genderless', 'Slow', 107, 3, 0, 'BATTLEARMOR', NULL, NULL, 'Undiscovered', 30720, 1.9, 120.5, 'Gray', 'Quadruped', NULL, 'Synthetic', 'The heavy control mask it wears suppresses its intrinsic capabilities. This Pokémon has some hidden special power.', '7', 'SILVALLY,Happiness,', '0772_Type_Null'),
(773, 'SILVALLY', 'Silvally', 'NORMAL', NULL, 95, 95, 95, 95, 95, 95, 'Genderless', 'Slow', 285, 3, 0, 'RKSSYSTEM', NULL, NULL, 'Undiscovered', 30720, 2.3, 100.5, 'Gray', 'Quadruped', NULL, 'Synthetic', 'Its trust in its partner is what awakens it. This Pokémon is capable of changing its type, a flexibility that is well displayed in battle.', '7', NULL, '0773_Silvally'),
(774, 'MINIOR', 'Minior', 'ROCK', 'FLYING', 60, 60, 100, 60, 100, 60, 'Genderless', 'Parabolic', 154, 30, 50, 'SHIELDSDOWN', NULL, NULL, 'Mineral', 6400, 0.3, 40.0, 'Brown', 'Head', NULL, 'Meteor', 'Originally making its home in the ozone layer, it hurtles to the ground when the shell enclosing its body grows too heavy.', '7', NULL, '0774_Minior'),
(775, 'KOMALA', 'Komala', 'NORMAL', NULL, 65, 115, 65, 75, 95, 65, 'Female50Percent', 'Slow', 168, 45, 50, 'COMATOSE', NULL, NULL, 'Field', 5120, 0.4, 19.9, 'Blue', 'Bipedal', NULL, 'Drowsing', 'It remains asleep from birth to death as a result of the sedative properties of the leaves that form its diet.', '7', NULL, '0775_Komala'),
(776, 'TURTONATOR', 'Turtonator', 'FIRE', 'DRAGON', 60, 78, 135, 91, 85, 36, 'Female50Percent', 'Medium', 170, 70, 50, 'SHELLARMOR', NULL, NULL, 'Monster,Dragon', 5120, 2.0, 212.0, 'Red', 'BipedalTail', NULL, 'Blast Turtle', 'It lives in volcanoes and eats sulfur and other minerals. Materials from the food it eats form the basis of its explosive shell.', '7', NULL, '0776_Turtonator'),
(777, 'TOGEDEMARU', 'Togedemaru', 'ELECTRIC', 'STEEL', 65, 98, 63, 40, 73, 96, 'Female50Percent', 'Medium', 152, 180, 50, 'IRONBARBS', 'LIGHTNINGROD', 'STURDY', 'Field,Fairy', 2560, 0.3, 3.3, 'Gray', 'BipedalTail', NULL, 'Roly-Poly', 'The long hairs on its back act as lightning rods. The bolts of lightning it attracts are stored as energy in its electric sac.', '7', NULL, '0777_Togedemaru'),
(778, 'MIMIKYU', 'Mimikyu', 'GHOST', 'FAIRY', 55, 90, 80, 50, 105, 96, 'Female50Percent', 'Medium', 167, 45, 50, 'DISGUISE', NULL, NULL, 'Amorphous', 5120, 0.2, 0.7, 'Yellow', 'Serpentine', NULL, 'Disguise', 'A lonely Pokémon, it conceals its terrifying appearance beneath an old rag so it can get closer to people and other Pokémon.', '7', NULL, '0778_Mimikyu'),
(779, 'BRUXISH', 'Bruxish', 'WATER', 'PSYCHIC', 68, 105, 70, 70, 70, 92, 'Female50Percent', 'Medium', 166, 80, 50, 'DAZZLING', 'STRONGJAW', 'WONDERSKIN', 'Water2', 3840, 0.9, 19.0, 'Pink', 'Finned', NULL, 'Gnash Teeth', 'When it unleashes its psychic power from the protuberance on its head, the grating sound of grinding teeth echoes through the area.', '7', NULL, '0779_Bruxish'),
(780, 'DRAMPA', 'Drampa', 'NORMAL', 'DRAGON', 78, 60, 85, 135, 91, 36, 'Female50Percent', 'Medium', 170, 70, 50, 'BERSERK', 'SAPSIPPER', 'CLOUDNINE', 'Monster,Dragon', 5120, 3.0, 185.0, 'White', 'Serpentine', NULL, 'Placid', 'This Pokémon is friendly to people and loves children most of all. It comes from deep in the mountains to play with children it likes in town.', '7', NULL, '0780_Drampa'),
(781, 'DHELMISE', 'Dhelmise', 'GHOST', 'GRASS', 70, 131, 100, 86, 90, 40, 'Genderless', 'Medium', 181, 25, 50, 'STEELWORKER', NULL, NULL, 'Mineral', 6400, 3.9, 210.0, 'Green', 'HeadBase', NULL, 'Sea Creeper', 'The soul of seaweed adrift in the waves became reborn as this Pokémon. It maintains itself with new infusions of seabed detritus and seaweed.', '7', NULL, '0781_Dhelmise'),
(782, 'JANGMOO', 'Jangmo-o', 'DRAGON', NULL, 45, 55, 65, 45, 45, 45, 'Female50Percent', 'Slow', 60, 45, 50, 'BULLETPROOF', 'SOUNDPROOF', 'OVERCOAT', 'Dragon', 10240, 0.6, 29.7, 'Gray', 'Quadruped', NULL, 'Scaly', 'It expresses its feelings by smacking its scales. Metallic sounds echo through the tall mountains where Jangmo-o lives.', '7', 'HAKAMOO,Level,35', '0782_Jangmo-o'),
(783, 'HAKAMOO', 'Hakamo-o', 'DRAGON', 'FIGHTING', 55, 75, 90, 65, 70, 65, 'Female50Percent', 'Slow', 147, 45, 50, 'BULLETPROOF', 'SOUNDPROOF', 'OVERCOAT', 'Dragon', 10240, 1.2, 47.0, 'Gray', 'BipedalTail', NULL, 'Scaly', 'It sheds and regrows its scales on a continuous basis. The scales become harder and sharper each time they''re regrown.', '7', 'KOMMOO,Level,45', '0783_Hakamo-o'),
(784, 'KOMMOO', 'Kommo-o', 'DRAGON', 'FIGHTING', 75, 110, 125, 100, 105, 85, 'Female50Percent', 'Slow', 300, 45, 50, 'BULLETPROOF', 'SOUNDPROOF', 'OVERCOAT', 'Dragon', 10240, 1.6, 78.2, 'Gray', 'BipedalTail', NULL, 'Scaly', 'Its rigid scales function as offense and defense. In the past, its scales were processed and used to make weapons and other commodities.', '7', NULL, '0784_Kommo-o'),
(785, 'TAPUKOKO', 'Tapu Koko', 'ELECTRIC', 'FAIRY', 70, 115, 85, 95, 75, 130, 'Genderless', 'Slow', 285, 3, 50, 'ELECTRICSURGE', NULL, 'TELEPATHY', 'Undiscovered', 3840, 1.8, 20.5, 'Yellow', 'HeadArms', NULL, 'Land Spirit', 'Although it''s called a guardian deity, if a person or Pokémon puts it in a bad mood, it will become a malevolent deity and attack.', '7', NULL, '0785_Tapu_Koko'),
(786, 'TAPULELE', 'Tapu Lele', 'PSYCHIC', 'FAIRY', 70, 85, 75, 130, 115, 95, 'Genderless', 'Slow', 285, 3, 50, 'PSYCHICSURGE', NULL, 'TELEPATHY', 'Undiscovered', 3840, 1.2, 18.6, 'Pink', 'HeadArms', NULL, 'Land Spirit', 'As it flutters about, it scatters its strangely glowing scales. Touching them is said to restore good health on the spot.', '7', NULL, '0786_Tapu_Lele'),
(787, 'TAPUBULU', 'Tapu Bulu', 'GRASS', 'FAIRY', 70, 130, 115, 85, 95, 75, 'Genderless', 'Slow', 285, 3, 50, 'GRASSYSURGE', NULL, 'TELEPATHY', 'Undiscovered', 3840, 1.9, 45.5, 'Red', 'HeadArms', NULL, 'Land Spirit', 'It pulls large trees up by the roots and swings them around. It causes vegetation to grow, and then it absorbs energy from the growth.', '7', NULL, '0787_Tapu_Bulu'),
(788, 'TAPUFINI', 'Tapu Fini', 'WATER', 'FAIRY', 70, 75, 115, 95, 130, 85, 'Genderless', 'Slow', 285, 3, 50, 'MISTYSURGE', NULL, 'TELEPATHY', 'Undiscovered', 3840, 1.3, 21.2, 'Purple', 'HeadArms', NULL, 'Land Spirit', 'The dense fog it creates brings the downfall and destruction of its confused enemies. Ocean currents are the source of its energy.', '7', NULL, '0788_Tapu_Fini'),
(789, 'COSMOG', 'Cosmog', 'PSYCHIC', NULL, 43, 29, 31, 29, 31, 37, 'Genderless', 'Slow', 40, 45, 0, 'UNAWARE', NULL, NULL, 'Undiscovered', 30720, 0.2, 0.1, 'Blue', 'Head', NULL, 'Nebula', 'Whether or not it''s a Pokémon from this world is a mystery. When it''s in a jam, it warps away to a safe place to hide.', '7', 'COSMOEM,Level,43', '0789_Cosmog'),
(790, 'COSMOEM', 'Cosmoem', 'PSYCHIC', NULL, 43, 29, 131, 29, 131, 37, 'Genderless', 'Slow', 140, 45, 0, 'STURDY', NULL, NULL, 'Undiscovered', 30720, 0.1, 999.9, 'Blue', 'Head', NULL, 'Protostar', 'Motionless as if dead, its body is faintly warm to the touch. In the distant past, it was called the cocoon of the stars.', '7', 'SOLGALEO,LevelDay,53,LUNALA,LevelNight,53', '0790_Cosmoem'),
(791, 'SOLGALEO', 'Solgaleo', 'PSYCHIC', 'STEEL', 137, 137, 107, 113, 89, 97, 'Genderless', 'Slow', 340, 45, 0, 'FULLMETALBODY', NULL, NULL, 'Undiscovered', 30720, 3.4, 230.0, 'White', 'Quadruped', NULL, 'Sunne', 'It is said to live in another world. The intense light it radiates from the surface of its body can make the darkest of nights light up like midday.', '7', NULL, '0791_Solgaleo'),
(792, 'LUNALA', 'Lunala', 'PSYCHIC', 'GHOST', 137, 113, 89, 137, 107, 97, 'Genderless', 'Slow', 340, 45, 0, 'SHADOWSHIELD', NULL, NULL, 'Undiscovered', 30720, 4.0, 120.0, 'Purple', 'Winged', NULL, 'Moone', 'Said to live in another world, this Pokémon devours light, drawing the moonless dark veil of night over the brightness of day.', '7', NULL, '0792_Lunala'),
(793, 'NIHILEGO', 'Nihilego', 'ROCK', 'POISON', 109, 53, 47, 127, 131, 103, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 1.2, 55.5, 'White', 'Multiped', NULL, 'Parasite', 'One of several mysterious Ultra Beasts. People on the street report observing those infested by it suddenly becoming violent.', '7', NULL, '0793_Nihilego'),
(794, 'BUZZWOLE', 'Buzzwole', 'BUG', 'FIGHTING', 107, 139, 139, 53, 53, 79, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 2.4, 333.6, 'Red', 'Multiped', NULL, 'Swollen', 'This Ultra Beast appeared from another world. It shows off its body, but whether that display is a boast or a threat remains unclear.', '7', NULL, '0794_Buzzwole'),
(795, 'PHEROMOSA', 'Pheromosa', 'BUG', 'FIGHTING', 71, 137, 37, 137, 37, 151, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 1.8, 25.0, 'White', 'Bipedal', NULL, 'Lissome', 'One of the Ultra Beasts. It refuses to touch anything, perhaps because it senses some uncleanness in this world.', '7', NULL, '0795_Pheromosa'),
(796, 'XURKITREE', 'Xurkitree', 'ELECTRIC', NULL, 83, 89, 71, 173, 71, 83, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 3.8, 100.0, 'Black', 'BipedalTail', NULL, 'Glowing', 'One of the mysterious life-forms known as Ultra Beasts. Astonishing electric shocks emanate from its entire body, according to witnesses.', '7', NULL, '0796_Xurkitree'),
(797, 'CELESTEELA', 'Celesteela', 'STEEL', 'FLYING', 97, 101, 103, 107, 101, 61, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 9.2, 999.9, 'Green', 'Bipedal', NULL, 'Launch', 'One kind of Ultra Beast. Witnesses have seen it burn down a forest by expelling gas from its two arms.', '7', NULL, '0797_Celesteela'),
(798, 'KARTANA', 'Kartana', 'GRASS', 'STEEL', 59, 181, 131, 59, 31, 109, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 0.3, 0.1, 'White', 'Bipedal', NULL, 'Drawn Sword', 'One of the Ultra Beast life-forms, it was observed cutting down a gigantic steel tower with one stroke of its blade.', '7', NULL, '0798_Kartana'),
(799, 'GUZZLORD', 'Guzzlord', 'DARK', 'DRAGON', 223, 101, 53, 97, 53, 43, 'Genderless', 'Slow', 285, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 5.5, 888.0, 'Black', 'BipedalTail', NULL, 'Junkivore', 'A dangerous Ultra Beast, it appears to be eating constantly, but for some reason its droppings have never been found.', '7', NULL, '0799_Guzzlord'),
(800, 'NECROZMA', 'Necrozma', 'PSYCHIC', NULL, 97, 107, 101, 127, 89, 79, 'Genderless', 'Slow', 300, 255, 0, 'PRISMARMOR', NULL, NULL, 'Undiscovered', 30720, 2.4, 230.0, 'Black', 'HeadArms', NULL, 'Prism', 'Light is apparently the source of its energy. It has an extraordinarily vicious disposition and is constantly firing off laser beams.', '7', NULL, '0800_Necrozma');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(801, 'MAGEARNA', 'Magearna', 'STEEL', 'FAIRY', 80, 95, 115, 130, 115, 65, 'Genderless', 'Slow', 300, 3, 0, 'SOULHEART', NULL, NULL, 'Undiscovered', 30720, 1.0, 80.5, 'Gray', 'Bipedal', NULL, 'Artificial', 'This artificial Pokémon, constructed more than 500 years ago, can understand human speech but cannot itself speak.', '7', NULL, '0801_Magearna'),
(802, 'MARSHADOW', 'Marshadow', 'FIGHTING', 'GHOST', 90, 125, 80, 90, 90, 125, 'Genderless', 'Slow', 300, 3, 0, 'TECHNICIAN', NULL, NULL, 'Undiscovered', 30720, 0.7, 22.2, 'Gray', 'Bipedal', NULL, 'Gloomdweller', 'Able to conceal itself in shadows, it never appears before humans, so its very existence was the stuff of myth.', '7', NULL, '0802_Marshadow'),
(803, 'POIPOLE', 'Poipole', 'POISON', NULL, 67, 73, 67, 73, 67, 73, 'Genderless', 'Slow', 210, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 0.6, 1.8, 'Purple', 'BipedalTail', NULL, 'Poison Pin', 'An Ultra Beast that lives in a different world, it cackles wildly as it sprays its opponents with poison from the needles on its head.', '7', 'NAGANADEL,HasMove,DRAGONPULSE', '0803_Poipole'),
(804, 'NAGANADEL', 'Naganadel', 'POISON', 'DRAGON', 73, 73, 73, 127, 73, 121, 'Genderless', 'Slow', 270, 45, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 3.6, 150.0, 'Purple', 'Winged', NULL, 'Poison Pin', 'One kind of Ultra Beast, it fires a glowing, venomous liquid from its needles. This liquid is also immensely adhesive.', '7', NULL, '0804_Naganadel'),
(805, 'STAKATAKA', 'Stakataka', 'ROCK', 'STEEL', 61, 131, 211, 53, 101, 13, 'Genderless', 'Slow', 285, 30, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 5.5, 820.0, 'Gray', 'Quadruped', NULL, 'Rampart', 'When stone walls started moving and attacking, the brute''s true identity was this mysterious life-form, which brings to mind an Ultra Beast.', '7', NULL, '0805_Stakataka'),
(806, 'BLACEPHALON', 'Blacephalon', 'FIRE', 'GHOST', 53, 127, 53, 151, 79, 107, 'Genderless', 'Slow', 285, 30, 0, 'BEASTBOOST', NULL, NULL, 'Undiscovered', 30720, 1.8, 13.0, 'White', 'Bipedal', NULL, 'Fireworks', 'It slithers toward people. Then, without warning, it triggers the explosion of its own head. It''s apparently one kind of Ultra Beast.', '7', NULL, '0806_Blacephalon'),
(807, 'ZERAORA', 'Zeraora', 'ELECTRIC', NULL, 88, 112, 75, 102, 80, 143, 'Genderless', 'Slow', 300, 3, 0, 'VOLTABSORB', NULL, NULL, 'Undiscovered', 30720, 1.5, 44.5, 'Yellow', 'Bipedal', NULL, 'Thunderclap', 'It approaches its enemies at the speed of lightning, then tears them limb from limb with its sharp claws.', '7', NULL, '0807_Zeraora'),
(808, 'MELTAN', 'Meltan', 'STEEL', NULL, 46, 65, 65, 55, 35, 34, 'Genderless', 'Slow', 150, 3, 0, 'MAGNETPULL', NULL, NULL, 'Undiscovered', 30720, 0.2, 8.0, 'Gray', 'Head', NULL, 'Hex Nut', 'It melts particles of iron and other metals found in the subsoil, so it can absorb them into its body of molten steel.', '7', 'MELMETAL,Level,45', '0808_Meltan'),
(809, 'MELMETAL', 'Melmetal', 'STEEL', NULL, 135, 143, 143, 80, 65, 34, 'Genderless', 'Slow', 300, 3, 0, 'IRONFIST', NULL, NULL, 'Undiscovered', 30720, 2.5, 800.0, 'Gray', 'Bipedal', NULL, 'Hex Nut', 'Revered long ago for its capacity to create iron from nothing, for some reason it has come back to life after 3,000 years.', '7', NULL, '0809_Melmetal'),
(810, 'GROOKEY', 'Grookey', 'GRASS', NULL, 50, 65, 50, 40, 40, 65, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'OVERGROW', NULL, 'GRASSYSURGE', 'Field,Grass', 5120, 0.3, 5.0, 'Green', 'BipedalTail', NULL, 'Chimp', 'When it uses its special stick to strike up a beat, the sound waves produced carry revitalizing energy to the plants and flowers in the area.', '8', 'THWACKEY,Level,16', '0810_Grookey'),
(811, 'THWACKEY', 'Thwackey', 'GRASS', NULL, 70, 85, 70, 55, 60, 80, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'OVERGROW', NULL, 'GRASSYSURGE', 'Field,Grass', 5120, 0.7, 14.0, 'Green', 'BipedalTail', NULL, 'Beat', 'When it''s drumming out rapid beats in battle, it gets so caught up in the rhythm that it won''t even notice that it''s already knocked out its opponent.', '8', 'RILLABOOM,Level,35', '0811_Thwackey'),
(812, 'RILLABOOM', 'Rillaboom', 'GRASS', NULL, 100, 125, 90, 60, 70, 85, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'OVERGROW', NULL, 'GRASSYSURGE', 'Field,Grass', 5120, 2.1, 90.0, 'Green', 'Bipedal', NULL, 'Drummer', 'By drumming, it taps into the power of its special tree stump. The roots of the stump follow its direction in battle.', '8', NULL, '0812_Rillaboom'),
(813, 'SCORBUNNY', 'Scorbunny', 'FIRE', NULL, 50, 71, 40, 40, 40, 69, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'LIBERO', 'Field,Humanlike', 5120, 0.3, 4.5, 'White', 'BipedalTail', NULL, 'Rabbit', 'A warm-up of running around gets fire energy coursing through this Pokémon''s body. Once that happens, it''s ready to fight at full power.', '8', 'RABOOT,Level,16', '0813_Scorbunny'),
(814, 'RABOOT', 'Raboot', 'FIRE', NULL, 65, 86, 60, 55, 60, 94, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'BLAZE', NULL, 'LIBERO', 'Field,Humanlike', 5120, 0.6, 9.0, 'Gray', 'BipedalTail', NULL, 'Rabbit', 'It kicks berries right off the branches of trees and then juggles them with its feet, practicing its footwork.', '8', 'CINDERACE,Level,35', '0814_Raboot'),
(815, 'CINDERACE', 'Cinderace', 'FIRE', NULL, 80, 116, 75, 65, 75, 119, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'BLAZE', NULL, 'LIBERO', 'Field,Humanlike', 5120, 1.4, 33.0, 'White', 'BipedalTail', NULL, 'Striker', 'It juggles a pebble with its feet, turning it into a burning soccer ball. Its shots strike opponents hard and leave them scorched.', '8', NULL, '0815_Cinderace'),
(816, 'SOBBLE', 'Sobble', 'WATER', NULL, 50, 40, 40, 70, 40, 70, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'TORRENT', NULL, 'SNIPER', 'Water1,Field', 5120, 0.3, 4.0, 'Blue', 'Quadruped', NULL, 'Water Lizard', 'When scared, this Pokémon cries. Its tears pack the chemical punch of 100 onions, and attackers won''t be able to resist weeping.', '8', 'DRIZZILE,Level,16', '0816_Sobble'),
(817, 'DRIZZILE', 'Drizzile', 'WATER', NULL, 65, 60, 55, 95, 55, 90, 'FemaleOneEighth', 'Parabolic', 147, 45, 50, 'TORRENT', NULL, 'SNIPER', 'Water1,Field', 5120, 0.7, 11.5, 'Blue', 'BipedalTail', NULL, 'Water Lizard', 'A clever combatant, this Pokémon battles using water balloons created with moisture secreted from its palms.', '8', 'INTELEON,Level,35', '0817_Drizzile'),
(818, 'INTELEON', 'Inteleon', 'WATER', NULL, 70, 85, 65, 125, 65, 120, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'SNIPER', 'Water1,Field', 5120, 1.9, 45.2, 'Blue', 'BipedalTail', NULL, 'Secret Agent', 'It has many hidden capabilities, such as fingertips that can shoot water and a membrane on its back that it can use to glide through the air.', '8', NULL, '0818_Inteleon'),
(819, 'SKWOVET', 'Skwovet', 'NORMAL', NULL, 70, 55, 55, 35, 35, 25, 'Female50Percent', 'Medium', 55, 255, 50, 'CHEEKPOUCH', NULL, 'GLUTTONY', 'Field', 5120, 0.3, 2.5, 'Brown', 'BipedalTail', NULL, 'Cheeky', 'It eats berries nonstop-a habit that has made it more resilient than it looks. It''ll show up on farms, searching for yet more berries.', '8', 'GREEDENT,Level,24', '0819_Skwovet'),
(820, 'GREEDENT', 'Greedent', 'NORMAL', NULL, 120, 95, 95, 55, 75, 20, 'Female50Percent', 'Medium', 161, 90, 50, 'CHEEKPOUCH', NULL, 'GLUTTONY', 'Field', 5120, 0.6, 6.0, 'Brown', 'BipedalTail', NULL, 'Greedy', 'It stashes berries in its tail - so many berries that they fall out constantly. But this Pokémon is a bit slow-witted, so it doesn''t notice the loss.', '8', NULL, '0820_Greedent'),
(821, 'ROOKIDEE', 'Rookidee', 'FLYING', NULL, 38, 47, 35, 33, 35, 57, 'Female50Percent', 'Parabolic', 49, 255, 50, 'KEENEYE', 'UNNERVE', 'BIGPECKS', 'Flying', 3840, 0.2, 1.8, 'Blue', 'Winged', NULL, 'Tiny Bird', 'Jumping nimbly about, this small-bodied Pokémon takes advantage of even the slightest opportunity to disorient larger opponents.', '8', 'CORVISQUIRE,Level,18', '0821_Rookidee'),
(822, 'CORVISQUIRE', 'Corvisquire', 'FLYING', NULL, 68, 67, 55, 43, 55, 77, 'Female50Percent', 'Parabolic', 128, 120, 50, 'KEENEYE', 'UNNERVE', 'BIGPECKS', 'Flying', 3840, 0.8, 16.0, 'Blue', 'Winged', NULL, 'Raven', 'Smart enough to use tools in battle, these Pokémon have been seen picking up rocks and flinging them or using ropes to wrap up enemies.', '8', 'CORVIKNIGHT,Level,38', '0822_Corvisquire'),
(823, 'CORVIKNIGHT', 'Corviknight', 'FLYING', 'STEEL', 98, 87, 105, 53, 85, 67, 'Female50Percent', 'Parabolic', 248, 45, 50, 'PRESSURE', 'UNNERVE', 'MIRRORARMOR', 'Flying', 3840, 2.2, 75.0, 'Purple', 'Winged', NULL, 'Raven', 'This Pokémon reigns supreme in the skies. The black luster of its steel body could drive terror into the heart of any foe.', '8', NULL, '0823_Corviknight'),
(824, 'BLIPBUG', 'Blipbug', 'BUG', NULL, 25, 20, 20, 25, 45, 45, 'Female50Percent', 'Medium', 36, 255, 50, 'SWARM', 'COMPOUNDEYES', 'TELEPATHY', 'Bug', 3840, 0.4, 8.0, 'Blue', 'Insectoid', NULL, 'Larva', 'Often found in gardens, this Pokémon has hairs on its body that it uses to assess its surroundings.', '8', 'DOTTLER,Level,10', '0824_Blipbug'),
(825, 'DOTTLER', 'Dottler', 'BUG', 'PSYCHIC', 50, 35, 80, 50, 90, 30, 'Female50Percent', 'Medium', 117, 120, 50, 'SWARM', 'COMPOUNDEYES', 'TELEPATHY', 'Bug', 3840, 0.4, 19.5, 'Yellow', 'Insectoid', NULL, 'Radome', 'It barely moves, but it''s still alive. Hiding in its shell without food or water seems to have awakened its psychic powers.', '8', 'ORBEETLE,Level,30', '0825_Dottler'),
(826, 'ORBEETLE', 'Orbeetle', 'BUG', 'PSYCHIC', 60, 45, 110, 80, 120, 90, 'Female50Percent', 'Medium', 253, 45, 50, 'SWARM', 'FRISK', 'TELEPATHY', 'Bug', 3840, 0.4, 40.8, 'Red', 'Winged', NULL, 'Seven Spot', 'It''s famous for its high level of intelligence, and the large size of its brain is proof that it also possesses immense psychic power.', '8', NULL, '0826_Orbeetle'),
(827, 'NICKIT', 'Nickit', 'DARK', NULL, 40, 28, 28, 47, 52, 50, 'Female50Percent', 'Fast', 49, 255, 50, 'RUNAWAY', 'UNBURDEN', 'STAKEOUT', 'Field', 3840, 0.6, 8.9, 'Brown', 'Quadruped', NULL, 'Fox', 'Aided by the soft pads on its feet, it silently raids the food stores of other Pokémon. It survives off its ill-gotten gains.', '8', 'THIEVUL,Level,18', '0827_Nickit'),
(828, 'THIEVUL', 'Thievul', 'DARK', NULL, 70, 58, 58, 87, 92, 90, 'Female50Percent', 'Fast', 159, 127, 50, 'RUNAWAY', 'UNBURDEN', 'STAKEOUT', 'Field', 3840, 1.2, 19.9, 'Brown', 'Quadruped', NULL, 'Fox', 'It secretly marks potential targets with a scent. By following the scent, it stalks its targets and steals from them when they least expect it.', '8', NULL, '0828_Thievul'),
(829, 'GOSSIFLEUR', 'Gossifleur', 'GRASS', NULL, 40, 40, 60, 40, 60, 10, 'Female50Percent', 'Medium', 50, 190, 50, 'COTTONDOWN', 'REGENERATOR', 'EFFECTSPORE', 'Grass', 5120, 0.4, 2.2, 'Green', 'HeadBase', NULL, 'Flowering', 'It anchors itself in the ground with its single leg, then basks in the sun. After absorbing enough sunlight, its petals spread as it blooms brilliantly.', '8', 'ELDEGOSS,Level,20', '0829_Gossifleur'),
(830, 'ELDEGOSS', 'Eldegoss', 'GRASS', NULL, 60, 50, 90, 80, 120, 60, 'Female50Percent', 'Medium', 161, 75, 50, 'COTTONDOWN', 'REGENERATOR', 'EFFECTSPORE', 'Grass', 5120, 0.5, 2.5, 'Green', 'HeadBase', NULL, 'Cotton Bloom', 'The seeds attached to its cotton fluff are full of nutrients. It spreads them on the wind so that plants and other Pokémon can benefit from them.', '8', NULL, '0830_Eldegoss'),
(831, 'WOOLOO', 'Wooloo', 'NORMAL', NULL, 42, 40, 55, 40, 45, 48, 'Female50Percent', 'Medium', 122, 255, 50, 'FLUFFY', 'RUNAWAY', 'BULLETPROOF', 'Field', 3840, 0.6, 6.0, 'White', 'Quadruped', NULL, 'Sheep', 'Its curly fleece is such an effective cushion that this Pokémon could fall off a cliff and stand right back up at the bottom, unharmed.', '8', 'DUBWOOL,Level,24', '0831_Wooloo'),
(832, 'DUBWOOL', 'Dubwool', 'NORMAL', NULL, 72, 80, 100, 60, 90, 88, 'Female50Percent', 'Medium', 172, 127, 50, 'FLUFFY', 'STEADFAST', 'BULLETPROOF', 'Field', 3840, 1.3, 43.0, 'White', 'Quadruped', NULL, 'Sheep', 'Its majestic horns are meant only to impress the opposite gender. They never see use in battle.', '8', NULL, '0832_Dubwool'),
(833, 'CHEWTLE', 'Chewtle', 'WATER', NULL, 50, 64, 50, 38, 38, 44, 'Female50Percent', 'Medium', 57, 255, 50, 'STRONGJAW', 'SHELLARMOR', 'SWIFTSWIM', 'Monster,Water1', 5120, 0.3, 8.5, 'Green', 'Quadruped', NULL, 'Snapping', 'It starts off battles by attacking with its rock-hard horn, but as soon as the opponent flinches, this Pokémon bites down and never lets go.', '8', 'DREDNAW,Level,22', '0833_Chewtle'),
(834, 'DREDNAW', 'Drednaw', 'WATER', 'ROCK', 90, 115, 90, 48, 68, 74, 'Female50Percent', 'Medium', 170, 75, 50, 'STRONGJAW', 'SHELLARMOR', 'SWIFTSWIM', 'Monster,Water1', 5120, 1.0, 115.5, 'Green', 'Quadruped', NULL, 'Bite', 'With jaws that can shear through steel rods, this highly aggressive Pokémon chomps down on its unfortunate prey.', '8', NULL, '0834_Drednaw'),
(835, 'YAMPER', 'Yamper', 'ELECTRIC', NULL, 59, 45, 50, 40, 50, 26, 'Female50Percent', 'Fast', 54, 255, 50, 'BALLFETCH', NULL, 'RATTLED', 'Field', 5120, 0.3, 13.5, 'Yellow', 'Quadruped', NULL, 'Puppy', 'This gluttonous Pokémon only assists people with their work because it wants treats. As it runs, it crackles with electricity.', '8', 'BOLTUND,Level,25', '0835_Yamper'),
(836, 'BOLTUND', 'Boltund', 'ELECTRIC', NULL, 69, 90, 60, 90, 60, 121, 'Female50Percent', 'Fast', 172, 45, 50, 'STRONGJAW', NULL, 'COMPETITIVE', 'Field', 5120, 1.0, 34.0, 'Yellow', 'Quadruped', NULL, 'Dog', 'This Pokémon generates electricity and channels it into its legs to keep them going strong. Boltund can run nonstop for three full days.', '8', NULL, '0836_Boltund'),
(837, 'ROLYCOLY', 'Rolycoly', 'ROCK', NULL, 30, 40, 50, 40, 50, 30, 'Female50Percent', 'Parabolic', 48, 255, 50, 'STEAMENGINE', 'HEATPROOF', 'FLASHFIRE', 'Mineral', 3840, 0.3, 12.0, 'Black', 'Head', NULL, 'Coal', 'Most of its body has the same composition as coal. Fittingly, this Pokémon was first discovered in coal mines about 400 years ago.', '8', 'CARKOL,Level,18', '0837_Rolycoly'),
(838, 'CARKOL', 'Carkol', 'ROCK', 'FIRE', 80, 60, 90, 60, 70, 50, 'Female50Percent', 'Parabolic', 144, 120, 50, 'STEAMENGINE', 'FLAMEBODY', 'FLASHFIRE', 'Mineral', 3840, 1.1, 78.0, 'Black', 'HeadLegs', NULL, 'Coal', 'By rapidly rolling its legs, it can travel at over 18 mph. The temperature of the flames it breathes exceeds 1,000 degrees Celsius.', '8', 'COALOSSAL,Level,34', '0838_Carkol'),
(839, 'COALOSSAL', 'Coalossal', 'ROCK', 'FIRE', 110, 80, 120, 80, 90, 30, 'Female50Percent', 'Parabolic', 255, 45, 50, 'STEAMENGINE', 'FLAMEBODY', 'FLASHFIRE', 'Mineral', 3840, 2.8, 310.5, 'Black', 'Bipedal', NULL, 'Coal', 'While it''s engaged in battle, its mountain of coal will burn bright red, sending off sparks that scorch the surrounding area.', '8', NULL, '0839_Coalossal'),
(840, 'APPLIN', 'Applin', 'GRASS', 'DRAGON', 40, 40, 80, 40, 40, 20, 'Female50Percent', 'Erratic', 52, 255, 50, 'RIPEN', 'GLUTTONY', 'BULLETPROOF', 'Grass,Dragon', 5120, 0.2, 0.5, 'Green', 'Serpentine', NULL, 'Apple Core', 'It spends its entire life inside an apple. It hides from its natural enemies, bird Pokémon, by pretending it''s just an apple and nothing more.', '8', 'FLAPPLE,Item,TARTAPPLE,APPLETUN,Item,SWEETAPPLE', '0840_Applin'),
(841, 'FLAPPLE', 'Flapple', 'GRASS', 'DRAGON', 70, 110, 80, 95, 60, 70, 'Female50Percent', 'Erratic', 170, 45, 50, 'RIPEN', 'GLUTTONY', 'HUSTLE', 'Grass,Dragon', 5120, 0.3, 1.0, 'Green', 'Winged', NULL, 'Apple Wing', 'It ate a sour apple, and that induced its evolution. In its cheeks, it stores an acid capable of causing chemical burns.', '8', NULL, '0841_Flapple'),
(842, 'APPLETUN', 'Appletun', 'GRASS', 'DRAGON', 110, 85, 80, 100, 80, 30, 'Female50Percent', 'Erratic', 170, 45, 50, 'RIPEN', 'GLUTTONY', 'THICKFAT', 'Grass,Dragon', 5120, 0.4, 13.0, 'Green', 'Quadruped', NULL, 'Apple Nectar', 'Its body is covered in sweet nectar, and the skin on its back is especially yummy. Children used to have it as a snack.', '8', NULL, '0842_Appletun'),
(843, 'SILICOBRA', 'Silicobra', 'GROUND', NULL, 52, 57, 75, 35, 50, 46, 'Female50Percent', 'Medium', 63, 255, 50, 'SANDSPIT', 'SHEDSKIN', 'SANDVEIL', 'Field,Dragon', 5120, 2.2, 7.6, 'Green', 'Serpentine', NULL, 'Sand Snake', 'It spews sand from its nostrils. While the enemy is blinded, it burrows into the ground to hide.', '8', 'SANDACONDA,Level,36', '0843_Silicobra'),
(844, 'SANDACONDA', 'Sandaconda', 'GROUND', NULL, 72, 107, 125, 65, 70, 71, 'Female50Percent', 'Medium', 179, 120, 50, 'SANDSPIT', 'SHEDSKIN', 'SANDVEIL', 'Field,Dragon', 5120, 3.8, 65.5, 'Green', 'Serpentine', NULL, 'Sand Snake', 'Its unique style of coiling allows it to blast sand out of its sand sac more efficiently.', '8', NULL, '0844_Sandaconda'),
(845, 'CRAMORANT', 'Cramorant', 'FLYING', 'WATER', 70, 85, 55, 85, 95, 85, 'Female50Percent', 'Medium', 166, 45, 50, 'GULPMISSILE', NULL, NULL, 'Water1,Flying', 5120, 0.8, 18.0, 'Blue', 'Winged', NULL, 'Gulp', 'It''s so strong that it can knock out some opponents in a single hit, but it also may forget what it''s battling midfight.', '8', NULL, '0845_Cramorant'),
(846, 'ARROKUDA', 'Arrokuda', 'WATER', NULL, 41, 63, 40, 40, 30, 66, 'Female50Percent', 'Slow', 56, 255, 50, 'SWIFTSWIM', NULL, 'PROPELLERTAIL', 'Water2', 5120, 0.5, 1.0, 'Brown', 'Finned', NULL, 'Rush', 'If it sees any movement around it, this Pokémon charges for it straightaway, leading with its sharply pointed jaw. It''s very proud of that jaw.', '8', 'BARRASKEWDA,Level,26', '0846_Arrokuda'),
(847, 'BARRASKEWDA', 'Barraskewda', 'WATER', NULL, 61, 123, 60, 60, 50, 136, 'Female50Percent', 'Slow', 172, 60, 50, 'SWIFTSWIM', NULL, 'PROPELLERTAIL', 'Water2', 5120, 1.3, 30.0, 'Brown', 'Finned', NULL, 'Skewer', 'This Pokémon has a jaw that''s as sharp as a spear and as strong as steel. Apparently Barraskewda''s flesh is surprisingly tasty, too.', '8', NULL, '0847_Barraskewda'),
(848, 'TOXEL', 'Toxel', 'ELECTRIC', 'POISON', 40, 38, 35, 54, 35, 40, 'Female50Percent', 'Parabolic', 48, 75, 50, 'RATTLED', 'STATIC', 'KLUTZ', 'Undiscovered', 6400, 0.4, 11.0, 'Purple', 'BipedalTail', NULL, 'Baby', 'It manipulates the chemical makeup of its poison to produce electricity. The voltage is weak, but it can cause a tingling paralysis.', '8', 'TOXTRICITY,Level,30', '0848_Toxel'),
(849, 'TOXTRICITY', 'Toxtricity', 'ELECTRIC', 'POISON', 75, 98, 70, 114, 70, 75, 'Female50Percent', 'Parabolic', 176, 45, 50, 'PUNKROCK', 'PLUS', 'TECHNICIAN', 'Humanlike', 6400, 1.6, 40.0, 'Purple', 'BipedalTail', NULL, 'Punk', 'When this Pokémon sounds as if it''s strumming a guitar, it''s actually clawing at the protrusions on its chest to generate electricity.', '8', NULL, '0849_Toxtricity'),
(850, 'SIZZLIPEDE', 'Sizzlipede', 'FIRE', 'BUG', 50, 65, 45, 50, 50, 45, 'Female50Percent', 'Medium', 61, 190, 50, 'FLASHFIRE', 'WHITESMOKE', 'FLAMEBODY', 'Bug', 5120, 0.7, 1.0, 'Red', 'Multiped', NULL, 'Radiator', 'It stores flammable gas in its body and uses it to generate heat. The yellow sections on its belly get particularly hot.', '8', 'CENTISKORCH,Level,28', '0850_Sizzlipede'),
(851, 'CENTISKORCH', 'Centiskorch', 'FIRE', 'BUG', 100, 115, 65, 90, 90, 65, 'Female50Percent', 'Medium', 184, 75, 50, 'FLASHFIRE', 'WHITESMOKE', 'FLAMEBODY', 'Bug', 5120, 3.0, 120.0, 'Red', 'Multiped', NULL, 'Radiator', 'While its burning body is already dangerous on its own, this excessively hostile Pokémon also has large and very sharp fangs.', '8', NULL, '0851_Centiskorch'),
(852, 'CLOBBOPUS', 'Clobbopus', 'FIGHTING', NULL, 50, 68, 60, 50, 50, 32, 'Female50Percent', 'Parabolic', 62, 180, 50, 'LIMBER', NULL, 'TECHNICIAN', 'Water1,Humanlike', 6400, 0.6, 4.0, 'Brown', 'Multiped', NULL, 'Tantrum', 'It''s very curious, but its means of investigating things is to try to punch them with its tentacles. The search for food is what brings it onto land.', '8', 'GRAPPLOCT,HasMove,TAUNT', '0852_Clobbopus'),
(853, 'GRAPPLOCT', 'Grapploct', 'FIGHTING', NULL, 80, 118, 90, 70, 80, 42, 'Female50Percent', 'Parabolic', 168, 45, 50, 'LIMBER', NULL, 'TECHNICIAN', 'Water1,Humanlike', 6400, 1.6, 39.0, 'Blue', 'Multiped', NULL, 'Jujitsu', 'A body made up of nothing but muscle makes the grappling moves this Pokémon performs with its tentacles tremendously powerful.', '8', NULL, '0853_Grapploct'),
(854, 'SINISTEA', 'Sinistea', 'GHOST', NULL, 40, 45, 45, 74, 54, 50, 'Genderless', 'Medium', 62, 120, 50, 'WEAKARMOR', NULL, 'CURSEDBODY', 'Mineral,Amorphous', 5120, 0.1, 0.2, 'Purple', 'Head', NULL, 'Black Tea', 'The teacup in which this Pokémon makes its home is a famous piece of antique tableware. Many forgeries are in circulation.', '8', 'POLTEAGEIST,Item,CRACKEDPOT', '0854_Sinistea'),
(855, 'POLTEAGEIST', 'Polteageist', 'GHOST', NULL, 60, 65, 65, 134, 114, 70, 'Genderless', 'Medium', 178, 60, 50, 'WEAKARMOR', NULL, 'CURSEDBODY', 'Mineral,Amorphous', 5120, 0.2, 0.4, 'Purple', 'Head', NULL, 'Black Tea', 'This species lives in antique teapots. Most pots are forgeries, but on rare occasions, an authentic work is found.', '8', NULL, '0855_Polteageist'),
(856, 'HATENNA', 'Hatenna', 'PSYCHIC', NULL, 42, 30, 45, 56, 53, 39, 'AlwaysFemale', 'Slow', 53, 235, 50, 'HEALER', 'ANTICIPATION', 'MAGICBOUNCE', 'Fairy', 5120, 0.4, 3.4, 'Pink', 'HeadLegs', NULL, 'Calm', 'Via the protrusion on its head, it senses other creatures'' emotions. If you don''t have a calm disposition, it will never warm up to you.', '8', 'HATTREM,Level,32', '0856_Hatenna'),
(857, 'HATTREM', 'Hattrem', 'PSYCHIC', NULL, 57, 40, 65, 86, 73, 49, 'AlwaysFemale', 'Slow', 130, 120, 50, 'HEALER', 'ANTICIPATION', 'MAGICBOUNCE', 'Fairy', 5120, 0.6, 4.8, 'Pink', 'Bipedal', NULL, 'Serene', 'Using the braids on its head, it pummels foes to get them to quiet down. One blow from those braids would knock out a professional boxer.', '8', 'HATTERENE,Level,42', '0857_Hattrem'),
(858, 'HATTERENE', 'Hatterene', 'PSYCHIC', 'FAIRY', 57, 90, 95, 136, 103, 29, 'AlwaysFemale', 'Slow', 255, 45, 50, 'HEALER', 'ANTICIPATION', 'MAGICBOUNCE', 'Fairy', 5120, 2.1, 5.1, 'Pink', 'HeadBase', NULL, 'Silent', 'It emits psychic power strong enough to cause headaches as a deterrent to the approach of others.', '8', NULL, '0858_Hatterene'),
(859, 'IMPIDIMP', 'Impidimp', 'DARK', 'FAIRY', 45, 45, 30, 55, 40, 50, 'AlwaysMale', 'Medium', 53, 255, 50, 'PRANKSTER', 'FRISK', 'PICKPOCKET', 'Fairy,Humanlike', 5120, 0.4, 5.5, 'Pink', 'Bipedal', NULL, 'Wily', 'Through its nose, it sucks in the emanations produced by people and Pokémon when they feel annoyed. It thrives off this negative energy.', '8', 'MORGREM,Level,32', '0859_Impidimp'),
(860, 'MORGREM', 'Morgrem', 'DARK', 'FAIRY', 65, 60, 45, 75, 55, 70, 'AlwaysMale', 'Medium', 130, 120, 50, 'PRANKSTER', 'FRISK', 'PICKPOCKET', 'Fairy,Humanlike', 5120, 0.8, 12.5, 'Pink', 'Bipedal', NULL, 'Devious', 'With sly cunning, it tries to lure people into the woods. Some believe it to have the power to make crops grow.', '8', 'GRIMMSNARL,Level,42', '0860_Morgrem'),
(861, 'GRIMMSNARL', 'Grimmsnarl', 'DARK', 'FAIRY', 95, 120, 65, 95, 75, 60, 'AlwaysMale', 'Medium', 255, 45, 50, 'PRANKSTER', 'FRISK', 'PICKPOCKET', 'Fairy,Humanlike', 5120, 1.5, 61.0, 'Purple', 'Bipedal', NULL, 'Bulk Up', 'Its hairs work like muscle fibers. When its hairs unfurl, they latch on to opponents, ensnaring them as tentacles would.', '8', NULL, '0861_Grimmsnarl'),
(862, 'OBSTAGOON', 'Obstagoon', 'DARK', 'NORMAL', 93, 90, 101, 60, 81, 95, 'Female50Percent', 'Medium', 260, 45, 50, 'RECKLESS', 'GUTS', 'DEFIANT', 'Field', 3840, 1.6, 46.0, 'Gray', 'BipedalTail', NULL, 'Blocking', 'It evolved after experiencing numerous fights. While crossing its arms, it lets out a shout that would make any opponent flinch.', '8', NULL, '0862_Obstagoon'),
(863, 'PERRSERKER', 'Perrserker', 'STEEL', NULL, 70, 110, 100, 50, 60, 50, 'Female50Percent', 'Medium', 154, 90, 50, 'BATTLEARMOR', 'TOUGHCLAWS', 'STEELYSPIRIT', 'Field', 5120, 0.8, 28.0, 'Brown', 'BipedalTail', NULL, 'Viking', 'What appears to be an iron helmet is actually hardened hair. This Pokémon lives for the thrill of battle.', '8', NULL, '0863_Perrserker'),
(864, 'CURSOLA', 'Cursola', 'GHOST', NULL, 60, 95, 50, 145, 130, 30, 'Female75Percent', 'Fast', 179, 30, 50, 'WEAKARMOR', NULL, 'PERISHBODY', 'Water1,Water3', 5120, 1.0, 0.4, 'White', 'HeadArms', NULL, 'Coral', 'Its shell is overflowing with its heightened otherworldly energy. The ectoplasm serves as protection for this Pokémon''s core spirit.', '8', NULL, '0864_Cursola'),
(865, 'SIRFETCHD', 'Sirfetch''d', 'FIGHTING', NULL, 62, 135, 95, 68, 82, 65, 'Female50Percent', 'Medium', 177, 45, 50, 'STEADFAST', NULL, 'SCRAPPY', 'Flying,Field', 5120, 0.8, 117.0, 'White', 'Winged', NULL, 'Wild Duck', 'After deflecting attacks with its hard leaf shield, it strikes back with its sharp leek stalk. The leek stalk is both weapon and food.', '8', NULL, '0865_Sirfetch''d'),
(866, 'MRRIME', 'Mr. Rime', 'ICE', 'PSYCHIC', 80, 85, 75, 110, 100, 70, 'Female50Percent', 'Medium', 182, 45, 50, 'TANGLEDFEET', 'SCREENCLEANER', 'ICEBODY', 'Humanlike', 6400, 1.5, 58.2, 'Purple', 'Bipedal', NULL, 'Comedian', 'Its amusing movements make it very popular. It releases its psychic power from the pattern on its belly.', '8', NULL, '0866_Mr_Rime'),
(867, 'RUNERIGUS', 'Runerigus', 'GROUND', 'GHOST', 58, 95, 145, 50, 105, 30, 'Female50Percent', 'Medium', 169, 90, 50, 'WANDERINGSPIRIT', NULL, NULL, 'Mineral,Amorphous', 6400, 1.6, 66.6, 'Gray', 'HeadBase', NULL, 'Grudge', 'A powerful curse was woven into an ancient painting. After absorbing the spirit of a Yamask, the painting began to move.', '8', NULL, '0867_Runerigus'),
(868, 'MILCERY', 'Milcery', 'FAIRY', NULL, 45, 40, 40, 50, 61, 34, 'AlwaysFemale', 'Medium', 54, 200, 50, 'SWEETVEIL', NULL, 'AROMAVEIL', 'Fairy,Amorphous', 5120, 0.2, 0.3, 'White', 'Head', NULL, 'Cream', 'This Pokémon was born from sweet-smelling particles in the air. Its body is made of cream.', '8', 'ALCREMIE,HoldItem,STRAWBERRYSWEET,ALCREMIE,HoldItem,BERRYSWEET,ALCREMIE,HoldItem,LOVESWEET,ALCREMIE,HoldItem,STARSWEET,ALCREMIE,HoldItem,CLOVERSWEET,ALCREMIE,HoldItem,FLOWERSWEET,ALCREMIE,HoldItem,RIBBONSWEET', '0868_Milcery'),
(869, 'ALCREMIE', 'Alcremie', 'FAIRY', NULL, 65, 60, 75, 110, 121, 64, 'AlwaysFemale', 'Medium', 173, 100, 50, 'SWEETVEIL', NULL, 'AROMAVEIL', 'Fairy,Amorphous', 5120, 0.3, 0.5, 'White', 'HeadBase', NULL, 'Cream', 'When Alcremie is content, the cream it secretes from its hands becomes sweeter and richer.', '8', NULL, '0869_Alcremie'),
(870, 'FALINKS', 'Falinks', 'FIGHTING', NULL, 65, 100, 100, 70, 60, 75, 'Genderless', 'Medium', 165, 45, 50, 'BATTLEARMOR', NULL, 'DEFIANT', 'Fairy,Mineral', 6400, 3.0, 62.0, 'Yellow', 'MultiBody', NULL, 'Formation', 'The six of them work together as one Pokémon. Teamwork is also their battle strategy, and they constantly change their formation as they fight.', '8', NULL, '0870_Falinks'),
(871, 'PINCURCHIN', 'Pincurchin', 'ELECTRIC', NULL, 48, 101, 95, 91, 85, 15, 'Female50Percent', 'Medium', 152, 75, 50, 'LIGHTNINGROD', NULL, 'ELECTRICSURGE', 'Water1,Amorphous', 5120, 0.3, 1.0, 'Purple', 'Multiped', NULL, 'Sea Urchin', 'It stores electricity in each spine. Even if one gets broken off, it still continues to emit electricity for at least three hours.', '8', NULL, '0871_Pincurchin'),
(872, 'SNOM', 'Snom', 'ICE', 'BUG', 30, 25, 35, 45, 30, 20, 'Female50Percent', 'Medium', 37, 190, 50, 'SHIELDDUST', NULL, 'ICESCALES', 'Bug', 5120, 0.3, 3.8, 'White', 'Serpentine', NULL, 'Worm', 'It spits out thread imbued with a frigid sort of energy and uses it to tie its body to branches, disguising itself as an icicle while it sleeps.', '8', 'FROSMOTH,HappinessNight,', '0872_Snom'),
(873, 'FROSMOTH', 'Frosmoth', 'ICE', 'BUG', 70, 65, 60, 125, 90, 65, 'Female50Percent', 'Medium', 168, 75, 50, 'SHIELDDUST', NULL, 'ICESCALES', 'Bug', 5120, 1.3, 42.0, 'White', 'MultiWinged', NULL, 'Frost Moth', 'It shows no mercy to any who desecrate fields and mountains. It will fly around on its icy wings, causing a blizzard to chase offenders away.', '8', NULL, '0873_Frosmoth'),
(874, 'STONJOURNER', 'Stonjourner', 'ROCK', NULL, 100, 125, 135, 20, 20, 70, 'Female50Percent', 'Slow', 165, 60, 50, 'POWERSPOT', NULL, NULL, 'Mineral', 6400, 2.5, 520.0, 'Gray', 'HeadLegs', NULL, 'Big Rock', 'Once a year, on a specific date and at a specific time, they gather out of nowhere and form up in a circle.', '8', NULL, '0874_Stonjourner'),
(875, 'EISCUE', 'Eiscue', 'ICE', NULL, 75, 80, 110, 65, 90, 50, 'Female50Percent', 'Slow', 165, 60, 50, 'ICEFACE', NULL, NULL, 'Water1,Field', 6400, 1.4, 89.0, 'Blue', 'BipedalTail', NULL, 'Penguin', 'It drifted in on the flow of ocean waters from a frigid place. It keeps its head iced constantly to make sure it stays nice and cold.', '8', NULL, '0875_Eiscue'),
(876, 'INDEEDEE', 'Indeedee', 'PSYCHIC', 'NORMAL', 60, 65, 55, 105, 95, 95, 'Female50Percent', 'Fast', 166, 30, 140, 'INNERFOCUS', 'SYNCHRONIZE', 'PSYCHICSURGE', 'Fairy', 10240, 0.9, 28.0, 'Purple', 'BipedalTail', NULL, 'Emotion', 'It uses the horns on its head to sense the emotions of others. Males will act as valets for those they serve, looking after their every need.', '8', NULL, '0876_Indeedee'),
(877, 'MORPEKO', 'Morpeko', 'ELECTRIC', 'DARK', 58, 95, 58, 70, 58, 97, 'Female50Percent', 'Medium', 153, 180, 50, 'HUNGERSWITCH', NULL, NULL, 'Field,Fairy', 2560, 0.3, 3.0, 'Yellow', 'Bipedal', NULL, 'Two-Sided', 'As it eats the seeds stored up in its pocket-like pouches, this Pokémon is not just satisfying its constant hunger. It''s also generating electricity.', '8', NULL, '0877_Morpeko'),
(878, 'CUFANT', 'Cufant', 'STEEL', NULL, 72, 80, 49, 40, 49, 40, 'Female50Percent', 'Medium', 66, 190, 50, 'SHEERFORCE', NULL, 'HEAVYMETAL', 'Field,Mineral', 6400, 1.2, 100.0, 'Yellow', 'Quadruped', NULL, 'Copperderm', 'It digs up the ground with its trunk. It''s also very strong, being able to carry loads of over five tons without any problem at all.', '8', 'COPPERAJAH,Level,34', '0878_Cufant'),
(879, 'COPPERAJAH', 'Copperajah', 'STEEL', NULL, 122, 130, 69, 80, 69, 30, 'Female50Percent', 'Medium', 175, 90, 50, 'SHEERFORCE', NULL, 'HEAVYMETAL', 'Field,Mineral', 6400, 3.0, 650.0, 'Green', 'Quadruped', NULL, 'Copperderm', 'These Pokémon live in herds. Their trunks have incredible grip strength, strong enough to crush giant rocks into powder.', '8', NULL, '0879_Copperajah'),
(880, 'DRACOZOLT', 'Dracozolt', 'ELECTRIC', 'DRAGON', 90, 100, 90, 80, 70, 75, 'Genderless', 'Slow', 177, 45, 50, 'VOLTABSORB', 'HUSTLE', 'SANDRUSH', 'Undiscovered', 8960, 1.8, 190.0, 'Green', 'BipedalTail', NULL, 'Fossil', 'In ancient times, it was unbeatable thanks to its powerful lower body, but it went extinct anyway after it depleted all its plant-based food sources.', '8', NULL, '0880_Dracozolt');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(881, 'ARCTOZOLT', 'Arctozolt', 'ELECTRIC', 'ICE', 90, 100, 90, 90, 80, 55, 'Genderless', 'Slow', 177, 45, 50, 'VOLTABSORB', 'STATIC', 'SLUSHRUSH', 'Undiscovered', 8960, 2.3, 150.0, 'Blue', 'BipedalTail', NULL, 'Fossil', 'The shaking of its freezing upper half is what generates its electricity. It has a hard time walking around.', '8', NULL, '0881_Arctozolt'),
(882, 'DRACOVISH', 'Dracovish', 'WATER', 'DRAGON', 90, 90, 100, 70, 80, 75, 'Genderless', 'Slow', 177, 45, 50, 'WATERABSORB', 'STRONGJAW', 'SANDRUSH', 'Undiscovered', 8960, 2.3, 215.0, 'Green', 'HeadLegs', NULL, 'Fossil', 'Powerful legs and jaws made it the apex predator of its time. Its own overhunting of its prey was what drove it to extinction.', '8', NULL, '0882_Dracovish'),
(883, 'ARCTOVISH', 'Arctovish', 'WATER', 'ICE', 90, 90, 100, 80, 90, 55, 'Genderless', 'Slow', 177, 45, 50, 'WATERABSORB', 'ICEBODY', 'SLUSHRUSH', 'Undiscovered', 8960, 2.0, 175.0, 'Blue', 'Finned', NULL, 'Fossil', 'Though it''s able to capture prey by freezing its surroundings, it has trouble eating the prey afterward because its mouth is on top of its head.', '8', NULL, '0883_Arctovish'),
(884, 'DURALUDON', 'Duraludon', 'STEEL', 'DRAGON', 70, 95, 115, 120, 50, 85, 'Female50Percent', 'Medium', 187, 45, 50, 'LIGHTMETAL', 'HEAVYMETAL', 'STALWART', 'Mineral,Dragon', 7680, 1.8, 40.0, 'White', 'BipedalTail', NULL, 'Alloy', 'Its body resembles polished metal, and it''s both lightweight and strong. The only drawback is that it rusts easily.', '8', NULL, '0884_Duraludon'),
(885, 'DREEPY', 'Dreepy', 'DRAGON', 'GHOST', 28, 60, 30, 40, 30, 82, 'Female50Percent', 'Slow', 54, 45, 50, 'CLEARBODY', 'INFILTRATOR', 'CURSEDBODY', 'Amorphous,Dragon', 10240, 0.5, 2.0, 'Green', 'Serpentine', NULL, 'Lingering', 'After being reborn as a ghost Pokémon, Dreepy wanders the areas it used to inhabit back when it was alive in prehistoric seas.', '8', 'DRAKLOAK,Level,50', '0885_Dreepy'),
(886, 'DRAKLOAK', 'Drakloak', 'DRAGON', 'GHOST', 68, 80, 50, 60, 50, 102, 'Female50Percent', 'Slow', 144, 45, 50, 'CLEARBODY', 'INFILTRATOR', 'CURSEDBODY', 'Amorphous,Dragon', 10240, 1.4, 11.0, 'Green', 'HeadArms', NULL, 'Caretaker', 'It''s capable of flying faster than 120 mph. It battles alongside Dreepy and dotes on them until they successfully evolve.', '8', 'DRAGAPULT,Level,60', '0886_Drakloak'),
(887, 'DRAGAPULT', 'Dragapult', 'DRAGON', 'GHOST', 88, 120, 75, 100, 75, 142, 'Female50Percent', 'Slow', 300, 45, 50, 'CLEARBODY', 'INFILTRATOR', 'CURSEDBODY', 'Amorphous,Dragon', 10240, 3.0, 50.0, 'Green', 'BipedalTail', NULL, 'Stealth', 'When it isn''t battling, it keeps Dreepy in the holes on its horns. Once a fight starts, it launches the Dreepy like supersonic missiles.', '8', NULL, '0887_Dragapult'),
(888, 'ZACIAN', 'Zacian', 'FAIRY', NULL, 92, 130, 115, 80, 115, 138, 'Genderless', 'Slow', 335, 10, 0, 'INTREPIDSWORD', NULL, NULL, 'Undiscovered', 30720, 2.8, 110.0, 'Blue', 'Quadruped', NULL, 'Warrior', 'Known as a legendary hero, this Pokémon absorbs metal particles, transforming them into a weapon it uses to battle.', '8', NULL, '0888_Zacian'),
(889, 'ZAMAZENTA', 'Zamazenta', 'FIGHTING', NULL, 92, 130, 115, 80, 115, 138, 'Genderless', 'Slow', 335, 10, 0, 'DAUNTLESSSHIELD', NULL, NULL, 'Undiscovered', 30720, 2.9, 210.0, 'Red', 'Quadruped', NULL, 'Warrior', 'This Pokémon slept for aeons while in the form of a statue. It was asleep for so long, people forgot that it ever existed.', '8', NULL, '0889_Zamazenta'),
(890, 'ETERNATUS', 'Eternatus', 'POISON', 'DRAGON', 140, 85, 95, 145, 95, 130, 'Genderless', 'Slow', 345, 255, 0, 'PRESSURE', NULL, NULL, 'Undiscovered', 30720, 20.0, 950.0, 'Purple', 'Winged', NULL, 'Gigantic', 'The core on its chest absorbs energy emanating from the lands of the Galar region. This energy is what allows Eternatus to stay active.', '8', NULL, '0890_Eternatus'),
(891, 'KUBFU', 'Kubfu', 'FIGHTING', NULL, 60, 90, 60, 53, 50, 72, 'FemaleOneEighth', 'Slow', 77, 3, 50, 'INNERFOCUS', NULL, NULL, 'Undiscovered', 30720, 0.6, 12.0, 'Gray', 'BipedalTail', NULL, 'Wushu', 'Kubfu trains hard to perfect its moves. The moves it masters will determine which form it takes when it evolves.', '8', 'URSHIFU,Event,1', '0891_Kubfu'),
(892, 'URSHIFU', 'Urshifu', 'FIGHTING', 'DARK', 100, 130, 100, 63, 60, 97, 'FemaleOneEighth', 'Slow', 275, 3, 50, 'UNSEENFIST', NULL, NULL, 'Undiscovered', 30720, 1.9, 105.0, 'Gray', 'Bipedal', NULL, 'Wushu', 'Inhabiting the mountains of a distant region, this Pokémon races across sheer cliffs, training its legs and refining its moves.', '8', NULL, '0892_Urshifu'),
(893, 'ZARUDE', 'Zarude', 'DARK', 'GRASS', 105, 120, 105, 70, 95, 105, 'Genderless', 'Slow', 300, 3, 0, 'LEAFGUARD', NULL, NULL, 'Undiscovered', 30720, 1.8, 70.0, 'Black', 'BipedalTail', NULL, 'Rogue Monkey', 'Once the vines on Zarude''s body tear off, they become nutrients in the soil. This helps the plants of the forest grow.', '8', NULL, '0893_Zarude'),
(894, 'REGIELEKI', 'Regieleki', 'ELECTRIC', NULL, 80, 100, 50, 100, 50, 200, 'Genderless', 'Slow', 290, 3, 35, 'TRANSISTOR', NULL, NULL, 'Undiscovered', 30720, 1.2, 145.0, 'Yellow', 'Bipedal', NULL, 'Electron', 'This Pokémon is a cluster of electrical energy. It''s said that removing the rings on Regieleki''s body will unleash the Pokémon''s latent power.', '8', NULL, '0894_Regieleki'),
(895, 'REGIDRAGO', 'Regidrago', 'DRAGON', NULL, 200, 100, 50, 100, 50, 80, 'Genderless', 'Slow', 290, 3, 35, 'DRAGONSMAW', NULL, NULL, 'Undiscovered', 30720, 2.1, 200.0, 'Green', 'Bipedal', NULL, 'Dragon Orb', 'Its body is composed of crystallized dragon energy. Regidrago is said to have the powers of every dragon Pokémon.', '8', NULL, '0895_Regidrago'),
(896, 'GLASTRIER', 'Glastrier', 'ICE', NULL, 100, 145, 130, 65, 110, 30, 'Genderless', 'Slow', 290, 3, 35, 'CHILLINGNEIGH', NULL, NULL, 'Undiscovered', 30720, 2.2, 800.0, 'White', 'Quadruped', NULL, 'Wild Horse', 'Glastrier has tremendous physical strength, and the mask of ice covering its face is 100 times harder than diamond.', '8', NULL, '0896_Glastrier'),
(897, 'SPECTRIER', 'Spectrier', 'GHOST', NULL, 100, 65, 60, 145, 80, 130, 'Genderless', 'Slow', 290, 3, 35, 'GRIMNEIGH', NULL, NULL, 'Undiscovered', 30720, 2.0, 44.5, 'Black', 'Quadruped', NULL, 'Swift Horse', 'As it dashes through the night, Spectrier absorbs the life-force of sleeping creatures. It craves silence and solitude.', '8', NULL, '0897_Spectrier'),
(898, 'CALYREX', 'Calyrex', 'PSYCHIC', 'GRASS', 100, 80, 80, 80, 80, 80, 'Genderless', 'Slow', 250, 3, 100, 'UNNERVE', NULL, NULL, 'Undiscovered', 30720, 1.1, 7.7, 'Green', 'Bipedal', NULL, 'King', 'Calyrex is a merciful Pokémon, capable of providing healing and blessings. It reigned over the Galar region in times of yore.', '8', NULL, '0898_Calyrex'),
(899, 'WYRDEER', 'Wyrdeer', 'NORMAL', 'PSYCHIC', 103, 105, 72, 105, 75, 65, 'Female50Percent', 'Slow', 263, 135, 50, 'INTIMIDATE', 'FRISK', 'SAPSIPPER', 'Field', 5120, 1.8, 95.1, 'Gray', 'Quadruped', NULL, 'Big Horn', 'The black orbs shine with an uncanny light when the Pokémon is erecting invisible barriers. The fur shed from its beard retains heat well and is a highly useful material for winter clothing.', '9', NULL, '0899_Wyrdeer'),
(900, 'KLEAVOR', 'Kleavor', 'BUG', 'ROCK', 70, 135, 95, 45, 70, 85, 'Female50Percent', 'Medium', 175, 115, 50, 'SWARM', 'SHEERFORCE', 'SHARPNESS', 'Bug', 5120, 1.8, 89.0, 'Brown', 'MultiWinged', NULL, 'Axe', 'A violent creature that fells towering trees with its crude axes and shields itself with hard stone. If one should chance upon this Pokémon in the wilds, one''s only recourse is to flee.', '9', NULL, '0900_Kleavor'),
(901, 'URSALUNA', 'Ursaluna', 'GROUND', 'NORMAL', 130, 140, 105, 45, 80, 50, 'Female50Percent', 'Medium', 275, 75, 50, 'GUTS', 'BULLETPROOF', 'UNNERVE', 'Field', 5120, 2.4, 290.0, 'Brown', 'Quadruped', NULL, 'Peat', 'I believe it was Hisui''s swampy terrain that gave Ursaluna its burly physique and newfound capacity to manipulate peat at will.', '9', NULL, '0901_Ursaluna'),
(902, 'BASCULEGION', 'Basculegion', 'WATER', 'GHOST', 120, 112, 65, 80, 75, 78, 'Female50Percent', 'Medium', 265, 135, 50, 'SWIFTSWIM', 'ADAPTABILITY', 'MOLDBREAKER', 'Water2', 5120, 3.0, 110.0, 'Green', 'Finned', NULL, 'Big Fish', 'Clads itself in the souls of comrades that perished before fulfilling their goals of journeying upstream. No other species throughout all Hisui''s rivers is Basculegion''s equal.', '9', NULL, '0902_Basculegion'),
(903, 'SNEASLER', 'Sneasler', 'FIGHTING', 'POISON', 80, 130, 60, 40, 80, 120, 'Female50Percent', 'Parabolic', 102, 135, 50, 'PRESSURE', 'UNBURDEN', 'POISONTOUCH', 'Field', 5120, 1.3, 43.0, 'Gray', 'BipedalTail', NULL, 'Free Climb', 'Because of Sneasler''s virulent poison and daunting physical prowess, no other species could hope to best it on the frozen highlands. Preferring solitude, this species does not form packs.', '9', NULL, '0903_Sneasler'),
(904, 'OVERQWIL', 'Overqwil', 'DARK', 'POISON', 85, 115, 95, 65, 65, 85, 'Female50Percent', 'Medium', 179, 135, 50, 'POISONPOINT', 'SWIFTSWIM', 'INTIMIDATE', 'Water2', 5120, 2.5, 60.5, 'Black', 'Finned', NULL, 'Pin Cluster', 'Its lancelike spikes and savage temperament have earned it the nickname "sea fiend." It slurps up poison to nourish itself.', '9', NULL, '0904_Overqwil'),
(905, 'ENAMORUS', 'Enamorus', 'FAIRY', 'FLYING', 74, 115, 70, 135, 80, 106, 'AlwaysFemale', 'Slow', 116, 3, 50, 'CUTECHARM', NULL, 'CONTRARY', 'Undiscovered', 5120, 1.6, 48.0, 'Pink', 'HeadArms', NULL, 'Love-Hate', 'When it flies to this land from across the sea, the bitter winter comes to an end. According to legend, this Pokémon''s love gives rise to the budding of fresh life across Hisui.', '9', NULL, '0905_Enamorus'),
(906, 'SPRIGATITO', 'Sprigatito', 'GRASS', NULL, 40, 61, 54, 45, 45, 65, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'OVERGROW', NULL, 'PROTEAN', 'Field,Grass', 5120, 0.4, 4.1, 'Green', 'Quadruped', NULL, 'Grass Cat', 'The sweet scent its body gives off mesmerizes those around it. The scent grows stronger when this Pokémon is in the sun.', '9', NULL, '0906_Sprigatito'),
(907, 'FLORAGATO', 'Floragato', 'GRASS', NULL, 61, 80, 63, 60, 63, 83, 'FemaleOneEighth', 'Parabolic', 144, 45, 50, 'OVERGROW', NULL, 'PROTEAN', 'Field,Grass', 5120, 0.9, 12.2, 'Green', 'BipedalTail', NULL, 'Grass Cat', 'The hardness of Floragato''s fur depends on the Pokémon''s mood. When Floragato is prepared to battle, its fur becomes pointed and needle sharp.', '9', NULL, '0907_Floragato'),
(908, 'MEOWSCARADA', 'Meowscarada', 'GRASS', 'DARK', 76, 110, 70, 81, 70, 123, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'OVERGROW', NULL, 'PROTEAN', 'Field,Grass', 5120, 1.5, 31.2, 'Green', 'BipedalTail', NULL, 'Magician', 'With skillful misdirection, it rigs foes with pollen-packed flower bombs. Meowscarada sets off the bombs before its foes realize what''s going on.', '9', NULL, '0908_Meowscarada'),
(909, 'FUECOCO', 'Fuecoco', 'FIRE', NULL, 67, 45, 59, 63, 40, 36, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'BLAZE', NULL, 'UNAWARE', 'Field', 5120, 0.4, 9.8, 'Red', 'BipedalTail', NULL, 'Fire Croc', 'Its flame sac is small, so energy is always leaking out. This energy is released from the dent atop Fuecoco''s head and flickers to and fro.', '9', NULL, '0909_Fuecoco'),
(910, 'CROCALOR', 'Crocalor', 'FIRE', NULL, 81, 55, 78, 90, 58, 49, 'FemaleOneEighth', 'Parabolic', 144, 45, 50, 'BLAZE', NULL, 'UNAWARE', 'Field', 5120, 1.0, 30.7, 'Red', 'BipedalTail', NULL, 'Fire Croc', 'The valve in Crocalor''s flame sac is closely connected to its vocal cords. This Pokémon utters a guttural cry as it spews flames every which way.', '9', NULL, '0910_Crocalor'),
(911, 'SKELEDIRGE', 'Skeledirge', 'FIRE', 'GHOST', 104, 75, 100, 110, 75, 66, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'BLAZE', NULL, 'UNAWARE', 'Field', 5120, 1.6, 326.5, 'Red', 'Quadruped', NULL, 'Singer', 'Skeledirge''s gentle singing soothes the souls of all that hear it. It burns its enemies to a crisp with flames of over 5,400 degrees Fahrenheit.', '9', NULL, '0911_Skeledirge'),
(912, 'QUAXLY', 'Quaxly', 'WATER', NULL, 55, 65, 45, 50, 45, 50, 'FemaleOneEighth', 'Parabolic', 62, 45, 50, 'TORRENT', NULL, 'MOXIE', 'Flying,Water1', 5120, 0.5, 6.1, 'White', 'BipedalTail', NULL, 'Duckling', 'Its strong legs let it easily swim around in even fast-flowing rivers. It likes to keep things tidy and is prone to overthinking things.', '9', NULL, '0912_Quaxly'),
(913, 'QUAXWELL', 'Quaxwell', 'WATER', NULL, 70, 85, 65, 65, 60, 65, 'FemaleOneEighth', 'Parabolic', 144, 45, 50, 'TORRENT', NULL, 'MOXIE', 'Flying,Water1', 5120, 1.2, 21.5, 'Blue', 'BipedalTail', NULL, 'Practicing', 'The hardworking Quaxwell observes people and Pokémon from various regions and incorporates their movements into its own dance routines.', '9', NULL, '0913_Quaxwell'),
(914, 'QUAQUAVAL', 'Quaquaval', 'WATER', 'FIGHTING', 85, 120, 80, 85, 75, 85, 'FemaleOneEighth', 'Parabolic', 265, 45, 50, 'TORRENT', NULL, 'MOXIE', 'Flying,Water1', 5120, 1.8, 61.9, 'Blue', 'BipedalTail', NULL, 'Dancer', 'Dancing in ways that evoke far-away places, this Pokémon mesmerizes all that see it. Flourishes of its decorative water feathers slice into its foes.', '9', NULL, '0914_Quaquaval'),
(915, 'LECHONK', 'Lechonk', 'NORMAL', NULL, 54, 45, 40, 35, 45, 35, 'Female50Percent', 'Medium', 51, 255, 50, 'AROMAVEIL', 'GLUTTONY', 'THICKFAT', 'Field', 3840, 0.5, 10.2, 'Gray', 'Quadruped', NULL, 'Hog', 'This Pokémon spurns all but the finest of foods. Its body gives off an herblike scent that bug Pokémon detest.', '9', NULL, '0915_Lechonk'),
(916, 'OINKOLOGNE', 'Oinkologne', 'NORMAL', NULL, 110, 100, 75, 59, 80, 65, 'AlwaysMale', 'Medium', 171, 100, 50, 'LINGERINGAROMA', 'GLUTTONY', 'THICKFAT', 'Field', 3840, 1.0, 120.0, 'Gray', 'Quadruped', NULL, 'Hog', 'It entrances female Pokémon with the sweet, alluring scent that wafts from all over its body.', '9', NULL, '0916_Oinkologne'),
(917, 'TAROUNTULA', 'Tarountula', 'BUG', NULL, 35, 41, 45, 29, 40, 20, 'Female50Percent', 'Erratic', 42, 255, 50, 'INSOMNIA', NULL, 'STAKEOUT', 'Bug', 3840, 0.3, 4.0, 'White', 'Insectoid', NULL, 'String Ball', 'The thread it secretes from its rear is as strong as wire. The secret behind the thread''s strength is the topic of ongoing research.', '9', NULL, '0917_Tarountula'),
(918, 'SPIDOPS', 'Spidops', 'BUG', NULL, 60, 79, 92, 52, 86, 35, 'Female50Percent', 'Erratic', 141, 120, 50, 'INSOMNIA', NULL, 'STAKEOUT', 'Bug', 3840, 1.0, 16.5, 'Green', 'Insectoid', NULL, 'Trap', 'Spidops covers its territory in tough, sticky threads to set up traps for intruders.', '9', NULL, '0918_Spidops'),
(919, 'NYMBLE', 'Nymble', 'BUG', NULL, 33, 46, 40, 21, 25, 45, 'Female50Percent', 'Medium', 42, 190, 20, 'SWARM', NULL, 'TINTEDLENS', 'Bug', 5120, 0.2, 1.0, 'Gray', 'Insectoid', NULL, 'Grasshopper', 'It''s highly skilled at a fighting style in which it uses its jumping capabilities to dodge incoming attacks while also dealing damage to opponents.', '9', NULL, '0919_Nymble'),
(920, 'LOKIX', 'Lokix', 'BUG', 'DARK', 71, 102, 78, 52, 55, 92, 'Female50Percent', 'Medium', 158, 30, 0, 'SWARM', NULL, 'TINTEDLENS', 'Bug', 5120, 1.0, 17.5, 'Gray', 'Bipedal', NULL, 'Grasshopper', 'It uses its normally folded third set of legs when in Showdown Mode. This places a huge burden on its body, so it can''t stay in this mode for long.', '9', NULL, '0920_Lokix'),
(921, 'PAWMI', 'Pawmi', 'ELECTRIC', NULL, 45, 50, 20, 40, 25, 60, 'Female50Percent', 'Medium', 48, 190, 50, 'STATIC', 'NATURALCURE', 'IRONFIST', 'Field', 3840, 0.3, 2.5, 'Yellow', 'Quadruped', NULL, 'Mouse', 'The pads of its paws are electricity-discharging organs. Pawmi fires electricity from its forepaws while standing unsteadily on its hind legs.', '9', NULL, '0921_Pawmi'),
(922, 'PAWMO', 'Pawmo', 'ELECTRIC', 'FIGHTING', 60, 75, 40, 50, 40, 85, 'Female50Percent', 'Medium', 123, 80, 50, 'VOLTABSORB', 'NATURALCURE', 'IRONFIST', 'Field', 3840, 0.4, 6.5, 'Yellow', 'BipedalTail', NULL, 'Mouse', 'Pawmo uses a unique fighting technique in which it uses its forepaws to strike foes and zap them with electricity from its paw pads simultaneously.', '9', NULL, '0922_Pawmo'),
(923, 'PAWMOT', 'Pawmot', 'ELECTRIC', 'FIGHTING', 70, 115, 70, 70, 60, 105, 'Female50Percent', 'Medium', 245, 45, 50, 'VOLTABSORB', 'NATURALCURE', 'IRONFIST', 'Field', 3840, 0.9, 41.0, 'Yellow', 'BipedalTail', NULL, 'Hands-On', 'Pawmot''s fluffy fur acts as a battery. It can store the same amount of electricity as an electric car.', '9', NULL, '0923_Pawmot'),
(924, 'TANDEMAUS', 'Tandemaus', 'NORMAL', NULL, 50, 50, 45, 40, 45, 75, 'Genderless', 'Fast', 61, 150, 50, 'RUNAWAY', 'PICKUP', 'OWNTEMPO', 'Field,Fairy', 2560, 0.3, 1.8, 'White', 'MultiBody', NULL, 'Couple', 'The pair sticks together no matter what. They split any food they find exactly in half and then eat it together.', '9', NULL, '0924_Tandemaus'),
(925, 'MAUSHOLD', 'Maushold', 'NORMAL', NULL, 74, 75, 70, 65, 75, 111, 'Genderless', 'Fast', 165, 75, 50, 'FRIENDGUARD', 'CHEEKPOUCH', 'TECHNICIAN', 'Field,Fairy', 2560, 0.3, 2.8, 'White', 'MultiBody', NULL, 'Family', 'The larger pair protects the little ones during battles. When facing strong opponents, the whole group will join the fight.', '9', NULL, '0925_Maushold'),
(926, 'FIDOUGH', 'Fidough', 'FAIRY', NULL, 37, 55, 70, 30, 55, 65, 'Female50Percent', 'Parabolic', 62, 190, 50, 'OWNTEMPO', NULL, 'KLUTZ', 'Field,Mineral', 5120, 0.3, 10.9, 'Yellow', 'Quadruped', NULL, 'Puppy', 'The yeast in Fidough''s breath is useful for cooking, so this Pokémon has been protected by people since long ago.', '9', NULL, '0926_Fidough'),
(927, 'DACHSBUN', 'Dachsbun', 'FAIRY', NULL, 57, 80, 115, 50, 80, 95, 'Female50Percent', 'Parabolic', 167, 90, 50, 'WELLBAKEDBODY', NULL, 'AROMAVEIL', 'Field,Mineral', 5120, 0.5, 14.9, 'Brown', 'Quadruped', NULL, 'Dog', 'The surface of this Pokémon''s skin hardens when exposed to intense heat, and its body has an appetizing aroma.', '9', NULL, '0927_Dachsbun'),
(928, 'SMOLIV', 'Smoliv', 'GRASS', 'NORMAL', 41, 35, 45, 58, 51, 30, 'Female50Percent', 'Parabolic', 52, 255, 50, 'EARLYBIRD', NULL, 'HARVEST', 'Grass', 5120, 0.3, 6.5, 'Green', 'HeadLegs', NULL, 'Olive', 'This Pokémon converts nutrients into oil, which it stores in the fruit on its head. It can easily go a whole week without eating or drinking.', '9', NULL, '0928_Smoliv'),
(929, 'DOLLIV', 'Dolliv', 'GRASS', 'NORMAL', 52, 53, 60, 78, 78, 33, 'Female50Percent', 'Parabolic', 124, 120, 50, 'EARLYBIRD', NULL, 'HARVEST', 'Grass', 5120, 0.6, 11.9, 'Green', 'Bipedal', NULL, 'Olive', 'It basks in the sun to its heart''s content until the fruits on its head ripen. After that, Dolliv departs from human settlements and goes on a journey.', '9', NULL, '0929_Dolliv'),
(930, 'ARBOLIVA', 'Arboliva', 'GRASS', 'NORMAL', 78, 69, 90, 125, 109, 39, 'Female50Percent', 'Parabolic', 255, 45, 50, 'SEEDSOWER', NULL, 'HARVEST', 'Grass', 5120, 1.4, 48.2, 'Green', 'Bipedal', NULL, 'Olive', 'This Pokémon drives back enemies by launching its rich, aromatic oil at them with enough force to smash a boulder.', '9', NULL, '0930_Arboliva'),
(931, 'SQUAWKABILLY', 'Squawkabilly', 'NORMAL', 'FLYING', 82, 96, 51, 45, 51, 92, 'Female50Percent', 'Erratic', 146, 190, 50, 'INTIMIDATE', 'HUSTLE', 'GUTS', 'Flying', 3840, 0.6, 2.4, 'Green', 'Winged', NULL, 'Parrot', 'Green-feathered flocks hold the most sway. When they''re out searching for food in the mornings and evenings, it gets very noisy.', '9', NULL, '0931_Squawkabilly'),
(932, 'NACLI', 'Nacli', 'ROCK', NULL, 55, 55, 75, 35, 35, 25, 'Female50Percent', 'Parabolic', 56, 255, 50, 'PURIFYINGSALT', 'STURDY', 'CLEARBODY', 'Mineral', 5120, 0.4, 16.0, 'Brown', 'Head', NULL, 'Rock Salt', 'The ground scrapes its body as it travels, causing it to leave salt behind. Salt is constantly being created and replenished inside Nacli''s body.', '9', NULL, '0932_Nacli'),
(933, 'NACLSTACK', 'Naclstack', 'ROCK', NULL, 60, 60, 100, 35, 65, 35, 'Female50Percent', 'Parabolic', 124, 120, 50, 'PURIFYINGSALT', 'STURDY', 'CLEARBODY', 'Mineral', 5120, 0.6, 105.0, 'Brown', 'Quadruped', NULL, 'Rock Salt', 'It compresses rock salt inside its body and shoots out hardened salt pellets with enough force to perforate an iron sheet.', '9', NULL, '0933_Naclstack'),
(934, 'GARGANACL', 'Garganacl', 'ROCK', NULL, 100, 100, 130, 45, 90, 35, 'Female50Percent', 'Parabolic', 250, 45, 50, 'PURIFYINGSALT', 'STURDY', 'CLEARBODY', 'Mineral', 5120, 2.3, 240.0, 'Brown', 'Bipedal', NULL, 'Rock Salt', 'Many Pokémon gather around Garganacl, hoping to lick at its mineral-rich salt.', '9', NULL, '0934_Garganacl'),
(935, 'CHARCADET', 'Charcadet', 'FIRE', NULL, 40, 50, 40, 50, 40, 35, 'Female50Percent', 'Slow', 51, 90, 50, 'FLASHFIRE', NULL, 'FLAMEBODY', 'Humanlike', 8960, 0.6, 10.5, 'Red', 'Bipedal', NULL, 'Fire Child', 'Its firepower increases when it fights, reaching over 1,800 degrees Fahrenheit. It likes berries that are rich in fat.', '9', NULL, '0935_Charcadet'),
(936, 'ARMAROUGE', 'Armarouge', 'FIRE', 'PSYCHIC', 85, 60, 100, 125, 80, 75, 'Female50Percent', 'Slow', 263, 25, 20, 'FLASHFIRE', NULL, 'WEAKARMOR', 'Humanlike', 8960, 1.5, 85.0, 'Red', 'Bipedal', NULL, 'Fire Warrior', 'This Pokémon clads itself in armor that has been fortified by psychic and fire energy, and it shoots blazing fireballs.', '9', NULL, '0936_Armarouge'),
(937, 'CERULEDGE', 'Ceruledge', 'FIRE', 'GHOST', 75, 125, 80, 60, 100, 85, 'Female50Percent', 'Slow', 263, 25, 20, 'FLASHFIRE', NULL, 'WEAKARMOR', 'Humanlike', 8960, 1.6, 62.0, 'Blue', 'Bipedal', NULL, 'Fire Blades', 'An old set of armor steeped in grudges caused this Pokémon''s evolution. Ceruledge cuts its enemies to pieces without mercy.', '9', NULL, '0937_Ceruledge'),
(938, 'TADBULB', 'Tadbulb', 'ELECTRIC', NULL, 61, 31, 41, 59, 35, 45, 'Female50Percent', 'Medium', 54, 190, 50, 'OWNTEMPO', 'STATIC', 'DAMP', 'Water1', 5120, 0.3, 0.4, 'Yellow', 'Head', NULL, 'EleTadpole', 'It floats using the electricity stored in its body. When thunderclouds are around, Tadbulb will float higher off the ground.', '9', NULL, '0938_Tadbulb'),
(939, 'BELLIBOLT', 'Bellibolt', 'ELECTRIC', NULL, 109, 64, 91, 103, 83, 45, 'Female50Percent', 'Medium', 173, 50, 50, 'ELECTROMORPHOSIS', 'STATIC', 'DAMP', 'Water1', 5120, 1.2, 113.0, 'Green', 'Bipedal', NULL, 'EleFrog', 'What appear to be eyeballs are actually organs for discharging the electricity generated by Bellibolt''s belly-button dynamo.', '9', NULL, '0939_Bellibolt'),
(940, 'WATTREL', 'Wattrel', 'ELECTRIC', 'FLYING', 40, 40, 35, 55, 40, 70, 'Female50Percent', 'Parabolic', 56, 180, 50, 'WINDPOWER', 'VOLTABSORB', 'COMPETITIVE', 'Water1,Flying', 5120, 0.4, 3.6, 'Black', 'Winged', NULL, 'Storm Petrel', 'These Pokémon make their nests on coastal cliffs. The nests have a strange, crackling texture, and they''re a popular delicacy.', '9', NULL, '0940_Wattrel'),
(941, 'KILOWATTREL', 'Kilowattrel', 'ELECTRIC', 'FLYING', 70, 70, 60, 105, 60, 125, 'Female50Percent', 'Parabolic', 172, 90, 50, 'WINDPOWER', 'VOLTABSORB', 'COMPETITIVE', 'Water1,Flying', 5120, 1.4, 38.6, 'Yellow', 'Winged', NULL, 'Frigatebird', 'It uses its throat sac to store electricity generated by its wings. There''s hardly any oil in its feathers, so it is a poor swimmer.', '9', NULL, '0941_Kilowattrel'),
(942, 'MASCHIFF', 'Maschiff', 'DARK', NULL, 60, 78, 60, 40, 51, 51, 'Female50Percent', 'Parabolic', 68, 150, 50, 'INTIMIDATE', 'RUNAWAY', 'STAKEOUT', 'Field', 5120, 0.5, 16.0, 'Brown', 'Quadruped', NULL, 'Rascal', 'Its well-developed jaw and fangs are strong enough to crunch through boulders, and its thick fat makes for an excellent defense.', '9', NULL, '0942_Maschiff'),
(943, 'MABOSSTIFF', 'Mabosstiff', 'DARK', NULL, 80, 120, 90, 60, 70, 85, 'Female50Percent', 'Parabolic', 177, 75, 50, 'INTIMIDATE', 'GUARDDOG', 'STAKEOUT', 'Field', 5120, 1.1, 61.0, 'Gray', 'Quadruped', NULL, 'Boss', 'Mabosstiff loves playing with children. Though usually gentle, it takes on an intimidating look when protecting its family.', '9', NULL, '0943_Mabosstiff'),
(944, 'SHROODLE', 'Shroodle', 'POISON', 'NORMAL', 40, 65, 35, 40, 35, 75, 'Female50Percent', 'Parabolic', 58, 190, 50, 'UNBURDEN', 'PICKPOCKET', 'PRANKSTER', 'Field', 5120, 0.2, 0.7, 'Gray', 'Quadruped', NULL, 'Toxic Mouse', 'To keep enemies away from its territory, it paints markings around its nest using a poisonous liquid that has an acrid odor.', '9', NULL, '0944_Shroodle'),
(945, 'GRAFAIAI', 'Grafaiai', 'POISON', 'NORMAL', 63, 95, 65, 80, 72, 110, 'Female50Percent', 'Parabolic', 170, 90, 50, 'UNBURDEN', 'POISONTOUCH', 'PRANKSTER', 'Field', 5120, 0.7, 27.2, 'Gray', 'BipedalTail', NULL, 'Toxic Monkey', 'Each Grafaiai paints its own individual pattern, and it will paint that same pattern over and over again throughout its life.', '9', NULL, '0945_Grafaiai'),
(946, 'BRAMBLIN', 'Bramblin', 'GRASS', 'GHOST', 40, 65, 30, 45, 35, 60, 'Female50Percent', 'Medium', 55, 190, 50, 'WINDRIDER', NULL, 'INFILTRATOR', 'Grass', 5120, 0.6, 0.6, 'Brown', 'Head', NULL, 'Tumbleweed', 'Not even Bramblin knows where it is headed as it tumbles across the wilderness, blown by the wind. It loathes getting wet.', '9', NULL, '0946_Bramblin'),
(947, 'BRAMBLEGHAST', 'Brambleghast', 'GRASS', 'GHOST', 55, 115, 70, 80, 70, 90, 'Female50Percent', 'Medium', 168, 45, 50, 'WINDRIDER', NULL, 'INFILTRATOR', 'Grass', 5120, 1.2, 6.0, 'Brown', 'Head', NULL, 'Tumbleweed', 'Brambleghast wanders around arid regions. On rare occasions, mass outbreaks of these Pokémon will bury an entire town.', '9', NULL, '0947_Brambleghast'),
(948, 'TOEDSCOOL', 'Toedscool', 'GROUND', 'GRASS', 40, 40, 35, 50, 100, 70, 'Female50Percent', 'Parabolic', 67, 190, 50, 'MYCELIUMMIGHT', NULL, NULL, 'Grass', 5120, 0.9, 33.0, 'Yellow', 'HeadLegs', NULL, 'Woodear', 'Though it looks like Tentacool, Toedscool is a completely different species. Its legs may be thin, but it can run at a speed of 30 mph.', '9', NULL, '0948_Toedscool'),
(949, 'TOEDSCRUEL', 'Toedscruel', 'GROUND', 'GRASS', 80, 70, 65, 80, 120, 100, 'Female50Percent', 'Parabolic', 180, 90, 50, 'MYCELIUMMIGHT', NULL, NULL, 'Grass', 5120, 1.9, 58.0, 'Black', 'Multiped', NULL, 'Woodear', 'It coils its 10 tentacles around prey and sucks out their nutrients, causing the prey pain. The folds along the rim of its head are a popular delicacy.', '9', NULL, '0949_Toedscruel'),
(950, 'KLAWF', 'Klawf', 'ROCK', NULL, 70, 100, 115, 35, 55, 75, 'Female50Percent', 'Medium', 158, 120, 50, 'ANGERSHELL', 'SHELLARMOR', 'REGENERATOR', 'Water3', 8960, 1.3, 79.0, 'Red', 'Insectoid', NULL, 'Ambush', 'This Pokémon lives on sheer cliffs. It sidesteps opponents'' attacks, then lunges for their weak spots with its claws.', '9', NULL, '0950_Klawf'),
(951, 'CAPSAKID', 'Capsakid', 'GRASS', NULL, 50, 62, 40, 62, 40, 50, 'Female50Percent', 'Medium', 61, 190, 50, 'CHLOROPHYLL', 'INSOMNIA', 'KLUTZ', 'Grass', 5120, 0.3, 3.0, 'Green', 'BipedalTail', NULL, 'Spicy Pepper', 'Traditional Paldean dishes can be extremely spicy because they include the shed front teeth of Capsakid among their ingredients.', '9', NULL, '0951_Capsakid'),
(952, 'SCOVILLAIN', 'Scovillain', 'GRASS', 'FIRE', 65, 108, 65, 108, 65, 75, 'Female50Percent', 'Medium', 170, 75, 50, 'CHLOROPHYLL', 'INSOMNIA', 'MOODY', 'Grass', 5120, 0.9, 15.0, 'Green', 'BipedalTail', NULL, 'Spicy Pepper', 'The green head has turned vicious due to the spicy chemicals stimulating its brain. Once it goes on a rampage, there is no stopping it.', '9', NULL, '0952_Scovillain'),
(953, 'RELLOR', 'Rellor', 'BUG', NULL, 41, 50, 60, 31, 58, 30, 'Female50Percent', 'Fast', 54, 190, 50, 'COMPOUNDEYES', NULL, 'SHEDSKIN', 'Bug', 5120, 0.2, 1.0, 'Brown', 'Insectoid', NULL, 'Rolling', 'It rolls its mud ball around while the energy it needs for evolution matures. Eventually the time comes for it to evolve.', '9', NULL, '0953_Rellor'),
(954, 'RABSCA', 'Rabsca', 'BUG', 'PSYCHIC', 75, 50, 85, 115, 100, 45, 'Female50Percent', 'Fast', 165, 45, 50, 'SYNCHRONIZE', NULL, 'TELEPATHY', 'Bug', 5120, 0.3, 3.5, 'Green', 'Insectoid', NULL, 'Rolling', 'An infant sleeps inside the ball. Rabsca rolls the ball soothingly with its legs to ensure the infant sleeps comfortably.', '9', NULL, '0954_Rabsca'),
(955, 'FLITTLE', 'Flittle', 'PSYCHIC', NULL, 30, 35, 30, 55, 30, 75, 'Female50Percent', 'Parabolic', 51, 120, 50, 'ANTICIPATION', 'FRISK', 'SPEEDBOOST', 'Flying', 5120, 0.2, 1.5, 'Yellow', 'HeadLegs', NULL, 'Frill', 'It spends its time running around wastelands. If anyone steals its beloved berries, it will chase them down and exact its revenge.', '9', NULL, '0955_Flittle'),
(956, 'ESPATHRA', 'Espathra', 'PSYCHIC', NULL, 95, 60, 60, 101, 60, 105, 'Female50Percent', 'Parabolic', 168, 60, 50, 'OPPORTUNIST', 'FRISK', 'SPEEDBOOST', 'Flying', 5120, 1.9, 90.0, 'Yellow', 'BipedalTail', NULL, 'Ostrich', 'It emits psychic power from the gaps between its multicolored frills and sprints at speeds greater than 120 mph.', '9', NULL, '0956_Espathra'),
(957, 'TINKATINK', 'Tinkatink', 'FAIRY', 'STEEL', 50, 45, 45, 35, 64, 58, 'AlwaysFemale', 'Parabolic', 59, 190, 50, 'MOLDBREAKER', 'OWNTEMPO', 'PICKPOCKET', 'Fairy', 5120, 0.4, 8.9, 'Pink', 'Bipedal', NULL, 'Metalsmith', 'This Pokémon pounds iron scraps together to make a hammer. It will remake the hammer again and again until it''s satisfied with the result.', '9', NULL, '0957_Tinkatink'),
(958, 'TINKATUFF', 'Tinkatuff', 'FAIRY', 'STEEL', 65, 55, 55, 45, 82, 78, 'AlwaysFemale', 'Parabolic', 133, 90, 50, 'MOLDBREAKER', 'OWNTEMPO', 'PICKPOCKET', 'Fairy', 5120, 0.7, 59.1, 'Pink', 'Bipedal', NULL, 'Hammer', 'These Pokémon make their homes in piles of scrap metal. They test the strength of each other''s hammers by smashing them together.', '9', NULL, '0958_Tinkatuff'),
(959, 'TINKATON', 'Tinkaton', 'FAIRY', 'STEEL', 85, 75, 77, 70, 105, 94, 'AlwaysFemale', 'Parabolic', 253, 45, 50, 'MOLDBREAKER', 'OWNTEMPO', 'PICKPOCKET', 'Fairy', 5120, 0.7, 112.8, 'Pink', 'Bipedal', NULL, 'Hammer', 'The hammer tops 220 pounds, yet it gets swung around easily by Tinkaton as it steals whatever it pleases and carries its plunder back home.', '9', NULL, '0959_Tinkaton'),
(960, 'WIGLETT', 'Wiglett', 'WATER', NULL, 10, 55, 25, 35, 25, 95, 'Female50Percent', 'Medium', 49, 255, 50, 'GOOEY', 'RATTLED', 'SANDVEIL', 'Water3', 5120, 1.2, 1.8, 'White', 'HeadBase', NULL, 'Garden Eel', 'Though it looks like Diglett, Wiglett is an entirely different species. The resemblance seems to be a coincidental result of environmental adaptation.', '9', NULL, '0960_Wiglett');
REPLACE INTO `battlemon_species` (`id`, `internal_name`, `name`, `type1`, `type2`, `hp`, `atk`, `def`, `spa`, `spd`, `spe`, `gender_ratio`, `growth_rate`, `base_exp`, `catch_rate`, `happiness`, `ability1`, `ability2`, `hidden_ability`, `egg_groups`, `hatch_steps`, `height`, `weight`, `color`, `shape`, `habitat`, `category`, `pokedex`, `generation`, `evolutions`, `sprite`) VALUES
(961, 'WUGTRIO', 'Wugtrio', 'WATER', NULL, 35, 100, 50, 50, 70, 120, 'Female50Percent', 'Medium', 149, 50, 50, 'GOOEY', 'RATTLED', 'SANDVEIL', 'Water3', 5120, 1.2, 5.4, 'Red', 'HeadBase', NULL, 'Garden Eel', 'A variety of fish Pokémon, Wugtrio was once considered to be a regional form of Dugtrio.', '9', NULL, '0961_Wugtrio'),
(962, 'BOMBIRDIER', 'Bombirdier', 'FLYING', 'DARK', 70, 103, 85, 60, 85, 82, 'Female50Percent', 'Slow', 243, 25, 50, 'BIGPECKS', 'KEENEYE', 'ROCKYPAYLOAD', 'Flying', 8960, 1.5, 42.9, 'White', 'Winged', NULL, 'Item Drop', 'Bombirdier uses the apron on its chest to bundle up food, which it carries back to its nest. It enjoys dropping things that make loud noises.', '9', NULL, '0962_Bombirdier'),
(963, 'FINIZEN', 'Finizen', 'WATER', NULL, 70, 45, 40, 45, 40, 75, 'Female50Percent', 'Slow', 63, 200, 50, 'WATERVEIL', NULL, NULL, 'Field,Water2', 10240, 1.3, 60.2, 'Blue', 'Finned', NULL, 'Dolphin', 'Its water ring is made from seawater mixed with a sticky fluid that Finizen secretes from its blowhole.', '9', NULL, '0963_Finizen'),
(964, 'PALAFIN', 'Palafin', 'WATER', NULL, 100, 70, 72, 53, 62, 100, 'Female50Percent', 'Slow', 160, 45, 50, 'ZEROTOHERO', NULL, NULL, 'Field,Water2', 10240, 1.3, 60.2, 'Blue', 'Finned', NULL, 'Dolphin', 'Its physical capabilities are no different than a Finizen''s, but when its allies are in danger, it transforms and powers itself up.', '9', NULL, '0964_Palafin'),
(965, 'VAROOM', 'Varoom', 'STEEL', 'POISON', 45, 70, 63, 30, 45, 47, 'Female50Percent', 'Medium', 60, 190, 50, 'OVERCOAT', NULL, 'SLOWSTART', 'Mineral', 5120, 1.0, 35.0, 'Gray', 'HeadLegs', NULL, 'Single-Cyl', 'The steel section is Varoom''s actual body. This Pokémon clings to rocks and converts the minerals within into energy to fuel its activities.', '9', NULL, '0965_Varoom'),
(966, 'REVAVROOM', 'Revavroom', 'STEEL', 'POISON', 80, 119, 90, 54, 67, 90, 'Female50Percent', 'Medium', 175, 75, 50, 'OVERCOAT', NULL, 'FILTER', 'Mineral', 5120, 1.8, 120.0, 'Gray', 'HeadLegs', NULL, 'Multi-Cyl', 'Revavroom viciously threatens others with the sound of its exhaust. It sticks its tongue out from its cylindrical mouth and sprays toxic fluids.', '9', NULL, '0966_Revavroom'),
(967, 'CYCLIZAR', 'Cyclizar', 'DRAGON', 'NORMAL', 70, 95, 65, 85, 65, 121, 'Female50Percent', 'Parabolic', 175, 190, 50, 'SHEDSKIN', NULL, 'REGENERATOR', 'Field', 7680, 1.6, 63.0, 'Green', 'Quadruped', NULL, 'Mount', 'It can sprint at over 70 mph while carrying a human. The rider''s body heat warms Cyclizar''s back and lifts the Pokémon''s spirit.', '9', NULL, '0967_Cyclizar'),
